const API = process.env.REACT_APP_BACKEND_URL;

const SHOT_ICONS = {
  close_up: Aperture,
  wide: Tv,
  speaker_focus: Users,
  split_screen: Camera,
};

const SHOT_COLORS = {
  close_up: { bg: 'bg-violet-500/10', text: 'text-violet-400', border: 'border-violet-500/20' },
  wide: { bg: 'bg-blue-500/10', text: 'text-blue-400', border: 'border-blue-500/20' },
