            <Trophy className="w-3.5 h-3.5 text-amber-400" />
          </div>
          <div>
            <h3 className="text-xs font-semibold text-white">Leaderboard</h3>
            <p className="text-[9px] text-slate-500">{leaderboard.length} participants</p>
          </div>
        </div>
      </div>

      {/* Reaction Summary */}
