                  {showLangMenu && (
                    <div className="absolute left-full bottom-0 ml-1 bg-karau-surface border border-karau-border rounded-xl shadow-2xl py-1.5 w-44 z-50 max-h-60 overflow-y-auto" data-testid="language-submenu">
