import { useRef, useCallback, useState } from 'react';

/**
 * Enhanced AI Noise Cancellation Hook
 * Dual-engine approach:
 * - Primary: RNNoise WASM (ML-based, superior quality)
 * - Fallback: Multi-stage Web Audio API pipeline
 */
export const useNoiseCancellation = () => {
  const audioContextRef = useRef(null);
  const sourceRef = useRef(null);
  const gainRef = useRef(null);
  const analyserRef = useRef(null);
  const noiseFloorRef = useRef(-60);
  const animFrameRef = useRef(null);
  const processorRef = useRef(null);
  const [isActive, setIsActive] = useState(false);
  const [noiseLevel, setNoiseLevel] = useState(0);
  const [suppressionStrength, setSuppressionStrength] = useState('medium');
  const [activeEngine, setActiveEngine] = useState(null);

  const PROFILES = {
    low: { threshold: -55, hpFreq: 60, lpFreq: 16000, ratio: 6, gain: 1.0 },
    medium: { threshold: -45, hpFreq: 85, lpFreq: 14000, ratio: 12, gain: 1.0 },
    high: { threshold: -35, hpFreq: 120, lpFreq: 12000, ratio: 20, gain: 0.9 },
  };

  const tryRnnoise = async (audioContext, source, destination) => {
    try {
      const { Rnnoise } = await import('@shiguredo/rnnoise-wasm');
      const rnnoise = await Rnnoise.load();
      const denoiseState = rnnoise.createDenoiseState();
      const frameSize = 480;
      const processor = audioContext.createScriptProcessor(4096, 1, 1);

      processor.onaudioprocess = (e) => {
        const input = e.inputBuffer.getChannelData(0);
        const output = e.outputBuffer.getChannelData(0);
        for (let offset = 0; offset < input.length; offset += frameSize) {
          const end = Math.min(offset + frameSize, input.length);
          const frame = new Float32Array(frameSize);
          for (let i = 0; i < end - offset; i++) frame[i] = input[offset + i] * 32768;
          denoiseState.processFrame(frame);
          for (let i = 0; i < end - offset; i++) output[offset + i] = frame[i] / 32768;
        }
      };

      source.connect(processor);
      processor.connect(destination);
      processorRef.current = processor;
      setActiveEngine('rnnoise');
      return true;
    } catch (err) {
      console.warn('RNNoise unavailable, using Web Audio fallback:', err);
      return false;
    }
  };

  const applyWebAudioPipeline = (audioContext, source, destination, profile) => {
    const highPass = audioContext.createBiquadFilter();
    highPass.type = 'highpass';
    highPass.frequency.setValueAtTime(profile.hpFreq, audioContext.currentTime);
    highPass.Q.setValueAtTime(0.71, audioContext.currentTime);

    const notch50 = audioContext.createBiquadFilter();
    notch50.type = 'notch';
    notch50.frequency.setValueAtTime(50, audioContext.currentTime);
    notch50.Q.setValueAtTime(15, audioContext.currentTime);

    const notch60 = audioContext.createBiquadFilter();
    notch60.type = 'notch';
    notch60.frequency.setValueAtTime(60, audioContext.currentTime);
    notch60.Q.setValueAtTime(15, audioContext.currentTime);

    const lowPass = audioContext.createBiquadFilter();
    lowPass.type = 'lowpass';
    lowPass.frequency.setValueAtTime(profile.lpFreq, audioContext.currentTime);
    lowPass.Q.setValueAtTime(0.71, audioContext.currentTime);

    const voiceBoost = audioContext.createBiquadFilter();
    voiceBoost.type = 'peaking';
    voiceBoost.frequency.setValueAtTime(3000, audioContext.currentTime);
    voiceBoost.Q.setValueAtTime(1.0, audioContext.currentTime);
    voiceBoost.gain.setValueAtTime(2, audioContext.currentTime);

    const compressor = audioContext.createDynamicsCompressor();
    compressor.threshold.setValueAtTime(profile.threshold, audioContext.currentTime);
    compressor.knee.setValueAtTime(30, audioContext.currentTime);
    compressor.ratio.setValueAtTime(profile.ratio, audioContext.currentTime);
    compressor.attack.setValueAtTime(0.003, audioContext.currentTime);
    compressor.release.setValueAtTime(0.15, audioContext.currentTime);

    const gain = audioContext.createGain();
    gain.gain.setValueAtTime(profile.gain, audioContext.currentTime);
    gainRef.current = gain;

    source.connect(highPass);
    highPass.connect(notch50);
    notch50.connect(notch60);
    notch60.connect(lowPass);
    lowPass.connect(voiceBoost);
    voiceBoost.connect(compressor);
    compressor.connect(gain);
    gain.connect(destination);
    setActiveEngine('webaudio');
  };

  const enableNoiseCancellation = useCallback(async (stream, strength = 'medium') => {
    try {
      setSuppressionStrength(strength);
      const profile = PROFILES[strength] || PROFILES.medium;
      const audioContext = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 48000 });
      audioContextRef.current = audioContext;

      const source = audioContext.createMediaStreamSource(stream);
      sourceRef.current = source;

      const analyser = audioContext.createAnalyser();
      analyser.fftSize = 4096;
      analyser.smoothingTimeConstant = 0.85;
      analyserRef.current = analyser;

      const destination = audioContext.createMediaStreamDestination();

      // Create an intermediate gain to connect analyser
      const monitorGain = audioContext.createGain();
      monitorGain.gain.value = 1;

      // Try RNNoise first, fallback to Web Audio
      const rnnoiseOk = await tryRnnoise(audioContext, source, monitorGain);
      if (!rnnoiseOk) {
        applyWebAudioPipeline(audioContext, source, monitorGain, profile);
      }

      monitorGain.connect(analyser);
      analyser.connect(destination);

      setIsActive(true);

      // Noise level monitoring
      const dataArray = new Float32Array(analyser.frequencyBinCount);
      const updateLevel = () => {
        if (!analyserRef.current) return;
        analyser.getFloatFrequencyData(dataArray);
        const binWidth = audioContext.sampleRate / analyser.fftSize;
        const startBin = Math.floor(300 / binWidth);
        const endBin = Math.ceil(3400 / binWidth);
        let sum = 0, count = 0;
        for (let i = startBin; i < endBin && i < dataArray.length; i++) { sum += dataArray[i]; count++; }
        const avgDb = count > 0 ? sum / count : -100;
        if (avgDb < noiseFloorRef.current + 5) noiseFloorRef.current = noiseFloorRef.current * 0.99 + avgDb * 0.01;
        setNoiseLevel(Math.round(Math.max(0, Math.min(100, ((avgDb + 100) / 60) * 100))));
        animFrameRef.current = requestAnimationFrame(updateLevel);
      };
      updateLevel();

      return destination.stream;
    } catch (e) {
      console.warn('Noise cancellation not supported:', e);
      return stream;
    }
  }, []);

  const disableNoiseCancellation = useCallback(() => {
    if (animFrameRef.current) { cancelAnimationFrame(animFrameRef.current); animFrameRef.current = null; }
    if (processorRef.current) { try { processorRef.current.disconnect(); } catch {} processorRef.current = null; }
    if (audioContextRef.current) { audioContextRef.current.close(); audioContextRef.current = null; }
    sourceRef.current = null;
    gainRef.current = null;
    analyserRef.current = null;
    noiseFloorRef.current = -60;
    setIsActive(false);
    setNoiseLevel(0);
    setActiveEngine(null);
  }, []);

  const setStrength = useCallback((strength) => {
    setSuppressionStrength(strength);
  }, []);

  return {
    isActive,
    noiseLevel,
    suppressionStrength,
    activeEngine,
    setStrength,
    enableNoiseCancellation,
    disableNoiseCancellation
  };
};

export default useNoiseCancellation;

/**
 * useVirtualBackground Hook - Enterprise Grade
 * Real-time AI-powered background replacement using MediaPipe Image Segmenter
 * Benchmarked against Zoom/Teams/Webex standards
 */

import { useEffect, useRef, useState, useCallback } from 'react';

// MediaPipe WASM and model URLs - pinned version for stability
const WASM_CDN = 'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14/wasm';
const MODEL_URL = 'https://storage.googleapis.com/mediapipe-models/image_segmenter/selfie_segmenter/float16_quant/1/selfie_segmenter.tflite';

/**
 * Custom hook for virtual background effects
 * @param {HTMLVideoElement} videoElement - Source video element
 * @param {string} backgroundType - 'none' | 'blur' | 'blur-light' | 'blur-heavy' | background id
 * @param {string} backgroundUrl - URL for image backgrounds
 * @returns {Object} - { canvasRef, isLoading, error, isSupported, isActive }
 */
export const useVirtualBackground = (videoElement, backgroundType, backgroundUrl = null) => {
  const canvasRef = useRef(null);
  const offscreenCanvasRef = useRef(null);
  const segmenterRef = useRef(null);
  const animationFrameRef = useRef(null);
  const backgroundImageRef = useRef(null);
  const activeRef = useRef(false);
  const backgroundTypeRef = useRef(backgroundType);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [isSupported, setIsSupported] = useState(true);
  const [isActive, setIsActive] = useState(false);

  // Keep ref in sync
  useEffect(() => {
    backgroundTypeRef.current = backgroundType;
  }, [backgroundType]);

  // Check browser support
  useEffect(() => {
    if (typeof WebAssembly !== 'object') {
      setIsSupported(false);
      setError('WebAssembly not supported');
    }
  }, []);

  // Load background image when URL changes
  useEffect(() => {
    if (backgroundUrl && backgroundType !== 'none' && !backgroundType.includes('blur')) {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        backgroundImageRef.current = img;
      };
      img.onerror = () => {
        console.error('Failed to load background image:', backgroundUrl);
        backgroundImageRef.current = null;
      };
      img.src = backgroundUrl;
    } else if (backgroundType === 'none') {
      backgroundImageRef.current = null;
    }
  }, [backgroundUrl, backgroundType]);

  // Initialize MediaPipe segmenter
  const initializeSegmenter = useCallback(async () => {
    if (segmenterRef.current) return true;

    setIsLoading(true);
    setError(null);

    try {
      const { ImageSegmenter, FilesetResolver } = await import('@mediapipe/tasks-vision');
      const filesetResolver = await FilesetResolver.forVisionTasks(WASM_CDN);

      segmenterRef.current = await ImageSegmenter.createFromOptions(filesetResolver, {
        baseOptions: {
          modelAssetPath: MODEL_URL,
          delegate: 'GPU'
        },
        runningMode: 'VIDEO',
        outputCategoryMask: true,
        outputConfidenceMasks: false
      });

      setIsLoading(false);
      return true;
    } catch (err) {
      console.error('Failed to initialize segmenter:', err);
      setError(`Failed to load AI model: ${err.message}`);
      setIsLoading(false);
      return false;
    }
  }, []);

  /**
   * Skin Tone Protection - Automatic AI Enhancement
   * Adjusts luminance and saturation of skin-tone color ranges to ensure
   * inclusive, natural rendering for all skin tones without overexposure.
   * Inspired by Agora SDK skinProtectLevel and Zoom/Teams rendering.
   */
  const applySkinToneProtection = useCallback((pixels, maskData) => {
    for (let i = 0; i < maskData.length; i++) {
      if (maskData[i] === 0) continue; // Skip background pixels

      const px = i * 4;
      const r = pixels[px];
      const g = pixels[px + 1];
      const b = pixels[px + 2];

      // Fast RGB-to-HSL inline (avoid function call overhead per pixel)
      const rn = r / 255, gn = g / 255, bn = b / 255;
      const max = Math.max(rn, gn, bn), min = Math.min(rn, gn, bn);
      const delta = max - min;
      let h = 0, s = 0, l = (max + min) / 2;

      if (delta > 0) {
        s = l > 0.5 ? delta / (2 - max - min) : delta / (max + min);
        if (max === rn) h = ((gn - bn) / delta + (gn < bn ? 6 : 0)) * 60;
        else if (max === gn) h = ((bn - rn) / delta + 2) * 60;
        else h = ((rn - gn) / delta + 4) * 60;
      }

      // Detect skin tone: hue 8-50 (orange-yellow range), saturation > 0.15, lightness 0.15-0.85
      if (h >= 8 && h <= 50 && s > 0.15 && l > 0.15 && l < 0.85) {
        // Boost saturation slightly for vibrancy (stronger for darker tones)
        const darkBoost = l < 0.4 ? 0.08 : l < 0.55 ? 0.05 : 0.02;
        s = Math.min(s + darkBoost, 1.0);

        // Lift shadows on darker skin without washing out mid/light tones
        if (l < 0.35) {
          l = l + 0.03;
        } else if (l < 0.5) {
          l = l + 0.015;
        }
        // Prevent overexposure on lighter skin
        if (l > 0.75) {
          l = l - 0.01;
        }

        // HSL back to RGB
        const c = (1 - Math.abs(2 * l - 1)) * s;
        const x = c * (1 - Math.abs((h / 60) % 2 - 1));
        const m = l - c / 2;
        let r1, g1, b1;
        if (h < 60)       { r1 = c; g1 = x; b1 = 0; }
        else if (h < 120) { r1 = x; g1 = c; b1 = 0; }
        else if (h < 180) { r1 = 0; g1 = c; b1 = x; }
        else if (h < 240) { r1 = 0; g1 = x; b1 = c; }
        else if (h < 300) { r1 = x; g1 = 0; b1 = c; }
        else               { r1 = c; g1 = 0; b1 = x; }

        pixels[px]     = Math.round((r1 + m) * 255);
        pixels[px + 1] = Math.round((g1 + m) * 255);
        pixels[px + 2] = Math.round((b1 + m) * 255);
      }
    }
  }, []);

  // Composite a frame with background effect
  const compositeFrame = useCallback(() => {
    if (!activeRef.current) return;

    const video = videoElement;
    const canvas = canvasRef.current;
    const segmenter = segmenterRef.current;
    const bgType = backgroundTypeRef.current;

    if (!segmenter || !video || !canvas || video.readyState < 2 || video.videoWidth === 0) {
      animationFrameRef.current = requestAnimationFrame(compositeFrame);
      return;
    }

    try {
      const width = video.videoWidth;
      const height = video.videoHeight;

      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      }

      const ctx = canvas.getContext('2d', { willReadFrequently: true });

      // Run segmentation
      const result = segmenter.segmentForVideo(video, performance.now());

      if (result && result.categoryMask) {
        const maskData = result.categoryMask.getAsUint8Array();
        const isBlur = bgType.includes('blur');

        // Draw original video first
        ctx.drawImage(video, 0, 0, width, height);
        const originalFrame = ctx.getImageData(0, 0, width, height);
        const origPixels = originalFrame.data;

        // Create background frame
        let bgPixels = null;

        if (isBlur) {
          // Create blurred version
          const blurAmount = bgType === 'blur-light' ? 10 : bgType === 'blur-heavy' ? 28 : 16;
          if (!offscreenCanvasRef.current) {
            offscreenCanvasRef.current = document.createElement('canvas');
          }
          const offCanvas = offscreenCanvasRef.current;
          offCanvas.width = width;
          offCanvas.height = height;
          const offCtx = offCanvas.getContext('2d');
          offCtx.filter = `blur(${blurAmount}px)`;
          offCtx.drawImage(video, 0, 0, width, height);
          offCtx.filter = 'none';
          bgPixels = offCtx.getImageData(0, 0, width, height).data;
        } else if (backgroundImageRef.current) {
          // Draw background image
          if (!offscreenCanvasRef.current) {
            offscreenCanvasRef.current = document.createElement('canvas');
          }
          const offCanvas = offscreenCanvasRef.current;
          offCanvas.width = width;
          offCanvas.height = height;
          const offCtx = offCanvas.getContext('2d');
          offCtx.drawImage(backgroundImageRef.current, 0, 0, width, height);
          bgPixels = offCtx.getImageData(0, 0, width, height).data;
        }

        if (bgPixels) {
          for (let i = 0; i < maskData.length; i++) {
            const isPerson = maskData[i] > 0;

            if (!isPerson) {
              const px = i * 4;
              origPixels[px] = bgPixels[px];
              origPixels[px + 1] = bgPixels[px + 1];
              origPixels[px + 2] = bgPixels[px + 2];
            }
          }
        }

        // Apply automatic skin tone protection on person pixels
        applySkinToneProtection(origPixels, maskData);

        ctx.putImageData(originalFrame, 0, 0);

        result.categoryMask.close();
      } else {
        // No mask available — just draw original video
        ctx.drawImage(video, 0, 0, width, height);
      }
    } catch (err) {
      // Frame error — silently skip, next frame will retry
    }

    animationFrameRef.current = requestAnimationFrame(compositeFrame);
  }, [videoElement, applySkinToneProtection]);

  // Start/stop processing based on background type
  useEffect(() => {
    const shouldProcess = backgroundType && backgroundType !== 'none' && isSupported;

    if (shouldProcess && !activeRef.current) {
      activeRef.current = true;
      setIsActive(true);

      const start = async () => {
        const initialized = await initializeSegmenter();
        if (initialized && activeRef.current) {
          compositeFrame();
        }
      };
      start();
    } else if (!shouldProcess && activeRef.current) {
      activeRef.current = false;
      setIsActive(false);
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
        animationFrameRef.current = null;
      }
    }

    return () => {
      if (!shouldProcess) {
        activeRef.current = false;
        if (animationFrameRef.current) {
          cancelAnimationFrame(animationFrameRef.current);
          animationFrameRef.current = null;
        }
      }
    };
  }, [backgroundType, isSupported, initializeSegmenter, compositeFrame]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      activeRef.current = false;
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      if (segmenterRef.current) {
        segmenterRef.current.close();
        segmenterRef.current = null;
      }
    };
  }, []);

  return {
    canvasRef,
    isLoading,
    error,
    isSupported,
    isActive
  };
};

export default useVirtualBackground;

import { useState, useEffect } from "react";
import { Globe, X, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useTranslation, LANGUAGE_META } from "@/utils/i18n";

const BANNER_DISMISSED_KEY = "medmatch-lang-banner-dismissed";

/**
 * Language Detection Banner
 * Shows a notification when the user's browser language differs from the app language
 * Offers to switch to the detected language
 */
const LanguageDetectionBanner = () => {
  const { language, setLanguage, t, detectBrowserLanguage, getLanguageInfo } = useTranslation();
  const [showBanner, setShowBanner] = useState(false);
  const [detectedLang, setDetectedLang] = useState(null);

  useEffect(() => {
    // Check if banner was already dismissed for this session
    const dismissed = sessionStorage.getItem(BANNER_DISMISSED_KEY);
    if (dismissed) return;

    // Check if this is first visit (no saved language preference)
    const savedLang = localStorage.getItem("medmatch-language");

    // Detect browser language
    const browserLang = detectBrowserLanguage();

    // Only show banner if:
    // 1. User has NOT previously set a language preference (first visit)
    // 2. Browser language is different from current language (English)
    // 3. Browser language is supported
    if (!savedLang && browserLang && browserLang !== 'en' && LANGUAGE_META[browserLang]) {
      setDetectedLang(browserLang);
      setShowBanner(true);
    }
  }, [detectBrowserLanguage]);

  const handleSwitchLanguage = () => {
    if (detectedLang) {
      setLanguage(detectedLang);
      setShowBanner(false);
      sessionStorage.setItem(BANNER_DISMISSED_KEY, "switched");
    }
  };

  const handleDismiss = () => {
    setShowBanner(false);
    sessionStorage.setItem(BANNER_DISMISSED_KEY, "dismissed");
  };

  if (!showBanner || !detectedLang) return null;

  const langInfo = getLanguageInfo(detectedLang);

  return (
    <div 
      className="fixed bottom-4 left-4 right-4 md:left-auto md:right-4 md:w-96 z-50 animate-in slide-in-from-bottom-4"
      data-testid="language-detection-banner"
    >
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg border border-slate-200 dark:border-slate-700 p-4">
        <div className="flex items-start gap-3">
          {/* Icon */}
          <div className="w-10 h-10 bg-teal-100 dark:bg-teal-900/30 rounded-full flex items-center justify-center flex-shrink-0">
            <Globe className="w-5 h-5 text-teal-600 dark:text-teal-400" />
          </div>

          {/* Content */}
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-1">
              <span className="text-xl">{langInfo.flag}</span>
              <p className="font-medium text-slate-900 dark:text-white text-sm">
                {t("language.detectedBrowserLanguage", { language: langInfo.name })}
              </p>
            </div>

            <p className="text-xs text-slate-500 dark:text-slate-400 mb-3">
              Would you like to switch to {langInfo.name}?
            </p>

            {/* Action Buttons */}
            <div className="flex gap-2">
              <Button
                size="sm"
                onClick={handleSwitchLanguage}
                className="bg-teal-600 hover:bg-teal-700 text-white"
                data-testid="switch-language-btn"
              >
                <Check className="w-4 h-4 mr-1" />
                {t("language.switchToLanguage", { language: langInfo.name })}
              </Button>
              <Button
                size="sm"
                variant="outline"
                onClick={handleDismiss}
                data-testid="keep-language-btn"
              >
                {t("language.keepCurrentLanguage")}
              </Button>
            </div>
          </div>

          {/* Close Button */}
          <button
            onClick={handleDismiss}
            className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300"
            aria-label="Dismiss"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

