/* ============ Knowledge Graph Tab ============ */
const KnowledgeTab = ({ data }) => {
  const [hovered, setHovered] = useState(null);
  const [selected, setSelected] = useState(null);

  if (!data) return null;
  const { nodes, connections, categories } = data;

  const CATEGORY_NAMES = ['People', 'Projects', 'Tasks', 'Channels'];

  const handleNodeClick = (node, i) => {
    setSelected(selected === i ? null : i);
  };

  const getConnectedNodes = (idx) => {
    if (idx === null) return new Set();
    const node = nodes[idx];
    const linked = new Set(node.links || []);
    // Also find nodes that link TO this node
    nodes.forEach((n, ni) => { if ((n.links || []).includes(idx)) linked.add(ni); });
    return linked;
  };

  const activeConnections = hovered !== null ? getConnectedNodes(hovered) : (selected !== null ? getConnectedNodes(selected) : null);
  const activeIdx = hovered !== null ? hovered : selected;

  return (
    <div className="space-y-6">
      {/* Category distribution + Connection strength */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-slate-50 rounded-xl p-4 border border-slate-100">
          <h3 className="text-sm font-bold text-slate-800 mb-3">Entity Distribution</h3>
          <ResponsiveContainer width="100%" height={200}>
            <PieChart>
              <Pie data={categories || []} cx="50%" cy="50%" innerRadius={50} outerRadius={80} paddingAngle={3} dataKey="count">
                {(categories || []).map((_, i) => <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />)}
              </Pie>
              <Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #E2E8F0', fontSize: 12 }} />
            </PieChart>
          </ResponsiveContainer>
          <div className="flex flex-wrap gap-2 mt-2">
            {(categories || []).map((cat, i) => (
              <span key={i} className="flex items-center gap-1.5 text-[10px] font-semibold text-slate-600">
                <span className="w-2 h-2 rounded-full" style={{ backgroundColor: CHART_COLORS[i % CHART_COLORS.length] }} />
                {cat.name} ({cat.count})
              </span>
            ))}
          </div>
        </div>

        <div className="bg-slate-50 rounded-xl p-4 border border-slate-100">
          <h3 className="text-sm font-bold text-slate-800 mb-3">Connection Strength</h3>
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={connections || []}>
              <CartesianGrid strokeDasharray="3 3" stroke="#E2E8F0" />
              <XAxis dataKey="type" tick={{ fontSize: 9, fill: '#94A3B8' }} />
              <YAxis tick={{ fontSize: 10, fill: '#94A3B8' }} />
              <Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #E2E8F0', fontSize: 12 }} />
              <Bar dataKey="strength" radius={[6, 6, 0, 0]}>
                {(connections || []).map((_, i) => <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />)}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Interactive knowledge graph */}
      <div className="bg-slate-50 rounded-xl p-4 border border-slate-100">
        <h3 className="text-sm font-bold text-slate-800 mb-3 flex items-center gap-2">
          <Network className="w-4 h-4" style={{ color: ESY.turquoise }} />Knowledge Network
          <span className="text-[10px] text-slate-400 font-normal ml-auto">Click a node to explore connections</span>
        </h3>
        <div className="relative bg-slate-900 rounded-xl overflow-hidden" style={{ height: 340 }} data-testid="knowledge-network-viz">
          <svg width="100%" height="100%" viewBox="0 0 600 340" className="cursor-pointer" onClick={() => { setSelected(null); setHovered(null); }}>
            {/* Links */}
            {(nodes || []).map((node, ni) => {
              const links = node.links || [];
              return links.map((linkIdx, li) => {
                const target = (nodes || [])[linkIdx];
                if (!target) return null;
                const isActive = activeIdx !== null && (activeIdx === ni || activeIdx === linkIdx);
                const isDirectConnection = activeConnections && (activeConnections.has(ni) || activeConnections.has(linkIdx)) && (activeIdx === ni || activeIdx === linkIdx);
                return (
                  <line key={`link-${ni}-${li}`}
                    x1={node.x} y1={node.y} x2={target.x} y2={target.y}
                    stroke={isDirectConnection ? CHART_COLORS[node.category % CHART_COLORS.length] : activeIdx !== null ? 'rgba(255,255,255,0.03)' : 'rgba(255,255,255,0.08)'}
                    strokeWidth={isDirectConnection ? 2 : 1}
                    style={{ transition: 'all 0.3s ease' }} />
                );
              });
            })}
            {/* Nodes */}
            {(nodes || []).map((node, i) => {
              const isActive = activeIdx === i;
              const isConnected = activeConnections ? activeConnections.has(i) : false;
              const isDimmed = activeIdx !== null && !isActive && !isConnected;
              const size = node.size || 12;
              const renderSize = isActive ? size * 1.3 : isConnected ? size * 1.1 : size;
              return (
                <g key={i} transform={`translate(${node.x},${node.y})`}
                  onMouseEnter={() => setHovered(i)}
                  onMouseLeave={() => setHovered(null)}
                  onClick={(e) => { e.stopPropagation(); handleNodeClick(node, i); }}
                  style={{ cursor: 'pointer', transition: 'all 0.3s ease' }}
                  data-testid={`kg-node-${i}`}>
                  {/* Glow */}
                  {isActive && <circle r={renderSize + 8} fill={CHART_COLORS[node.category % CHART_COLORS.length]} opacity={0.15} />}
                  {/* Pulse ring for active */}
                  {isActive && <circle r={renderSize + 4} fill="none" stroke={CHART_COLORS[node.category % CHART_COLORS.length]} strokeWidth={1.5} opacity={0.4}>
                    <animate attributeName="r" from={renderSize + 2} to={renderSize + 12} dur="1.5s" repeatCount="indefinite" />
                    <animate attributeName="opacity" from="0.4" to="0" dur="1.5s" repeatCount="indefinite" />
                  </circle>}
                  {/* Node circle */}
                  <circle r={renderSize} fill={CHART_COLORS[node.category % CHART_COLORS.length]}
                    opacity={isDimmed ? 0.2 : 0.9}
                    style={{ transition: 'all 0.3s ease' }} />
                  <circle r={renderSize} fill="none"
                    stroke={isActive ? 'white' : 'rgba(255,255,255,0.2)'}
                    strokeWidth={isActive ? 2 : 1}
                    style={{ transition: 'all 0.3s ease' }} />
                  {/* Label */}
                  <text y={-(renderSize + 6)} textAnchor="middle"
                    fill={isDimmed ? 'rgba(255,255,255,0.15)' : isActive ? 'white' : 'rgba(255,255,255,0.7)'}
                    fontSize={isActive ? 11 : 9} fontWeight={isActive ? '700' : '600'}
                    style={{ transition: 'all 0.3s ease' }}>
                    {node.label}
                  </text>
                  {/* Category label on hover */}
                  {isActive && (
                    <text y={renderSize + 14} textAnchor="middle" fill="rgba(255,255,255,0.5)" fontSize={8} fontWeight="500">
                      {CATEGORY_NAMES[node.category] || 'Unknown'}
                    </text>
                  )}
                </g>
              );
            })}
          </svg>

          {/* Selected node detail card */}
          {selected !== null && nodes[selected] && (
            <div className="absolute top-3 right-3 bg-black/80 backdrop-blur-md border border-white/10 rounded-xl p-3 max-w-[180px]" data-testid="kg-detail-card">
              <div className="flex items-center gap-2 mb-2">
                <div className="w-6 h-6 rounded-full flex items-center justify-center" style={{ backgroundColor: CHART_COLORS[nodes[selected].category % CHART_COLORS.length] }}>
                  <span className="text-[9px] text-white font-bold">{nodes[selected].label[0]}</span>
                </div>
                <div>
                  <p className="text-xs font-bold text-white">{nodes[selected].label}</p>
                  <p className="text-[9px] text-white/50">{CATEGORY_NAMES[nodes[selected].category]}</p>
                </div>
              </div>
              <div className="text-[9px] text-white/60 space-y-1">
                <p>Connections: {(nodes[selected].links || []).length}</p>
                <p className="text-white/40">Click elsewhere to deselect</p>
              </div>
            </div>
          )}

          {/* Legend */}
          <div className="absolute bottom-3 left-3 flex items-center gap-3">
            {CATEGORY_NAMES.map((label, i) => (
              <span key={i} className="flex items-center gap-1 text-[9px] font-semibold text-white/50">
                <span className="w-2 h-2 rounded-full" style={{ backgroundColor: CHART_COLORS[i] }} />{label}
              </span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

/**
 * My Reviews Section Component
 * Displays reviews received by a candidate with response capability
 */
import { useState, useEffect } from "react";
import { Star, MessageSquare, TrendingUp, RefreshCw, Send } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import axios from "axios";
import EmployerReviewCard, { ReviewSummary } from "./EmployerReviewCard";
import { useTranslation } from "@/utils/i18n";

const API = process.env.REACT_APP_BACKEND_URL;

const MyReviewsSection = ({ userId }) => {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(true);
  const [reviewData, setReviewData] = useState(null);
  const [responseDialog, setResponseDialog] = useState({ open: false, review: null });
  const [responseText, setResponseText] = useState("");
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    fetchMyReviews();
  }, [userId]);

  const fetchMyReviews = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem("medmatch-token");
      const response = await axios.get(
        `${API}/api/reviews/my-reviews`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setReviewData(response.data);
    } catch (err) {
      console.error("Failed to fetch reviews:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleRespond = (review) => {
    setResponseDialog({ open: true, review });
    setResponseText("");
  };

  const submitResponse = async () => {
    if (!responseText.trim()) {
      toast.error("Please write a response");
      return;
    }

    setSubmitting(true);
    try {
      const token = localStorage.getItem("medmatch-token");
      await axios.post(
        `${API}/api/reviews/respond/${responseDialog.review.id}`,
        {
          candidate_id: userId,
          response_text: responseText,
          is_public: true
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      toast.success("Response submitted successfully!");
      setResponseDialog({ open: false, review: null });
      fetchMyReviews(); // Refresh to show response
    } catch (err) {
      toast.error(err.response?.data?.detail || "Failed to submit response");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-8 text-center">
          <RefreshCw className="w-8 h-8 animate-spin text-slate-400 mx-auto mb-2" />
          <p className="text-slate-500">Loading reviews...</p>
        </CardContent>
      </Card>
    );
  }

  if (!reviewData || reviewData.total_reviews === 0) {
    return (
      <Card>
        <CardContent className="p-8 text-center">
          <Star className="w-12 h-12 text-slate-300 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-slate-900 dark:text-slate-100 mb-2">
            No Reviews Yet
          </h3>
          <p className="text-slate-500 text-sm">
            Reviews from employers will appear here once they&apos;re approved.
            Getting positive reviews can boost your Trust Score!
          </p>
        </CardContent>
      </Card>
    );
  }

  // Build summary object for ReviewSummary component
  const summaryData = {
    average_rating: reviewData.average_rating,
    total_reviews: reviewData.approved_reviews,
    would_hire_again_percentage: 0, // Would need to calculate from reviews
    rating_distribution: {},
    top_strengths: []
  };

  // Calculate rating distribution and strengths from reviews
  const strengthCounts = {};
  reviewData.reviews?.forEach(r => {
    // Rating distribution
    const rating = r.rating;
    summaryData.rating_distribution[rating] = (summaryData.rating_distribution[rating] || 0) + 1;

    // Strengths
    r.strengths?.forEach(s => {
      strengthCounts[s] = (strengthCounts[s] || 0) + 1;
    });

    // Would hire again
    if (r.would_hire_again) {
      summaryData.would_hire_again_percentage++;
    }
  });

  // Convert to percentage
  if (reviewData.reviews?.length > 0) {
    summaryData.would_hire_again_percentage = Math.round(
      (summaryData.would_hire_again_percentage / reviewData.reviews.length) * 100
    );
  }

  // Top strengths
  summaryData.top_strengths = Object.entries(strengthCounts)
    .map(([strength, count]) => ({ strength, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 5);

  return (
    <div className="space-y-6" data-testid="my-reviews-section">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-semibold text-slate-900 dark:text-slate-100" style={{ fontFamily: 'IBM Plex Sans' }}>
            Employer Reviews
          </h2>
          <p className="text-sm text-slate-500 mt-1">
            {reviewData.approved_reviews} approved review{reviewData.approved_reviews !== 1 ? 's' : ''}
            {reviewData.pending_count > 0 && (
              <span className="ml-2 text-amber-500">
                ({reviewData.pending_count} pending)
              </span>
            )}
          </p>
        </div>
        <Button variant="outline" size="sm" onClick={fetchMyReviews}>
          <RefreshCw className="w-4 h-4 mr-2" />
          Refresh
        </Button>
      </div>

      {/* Summary */}
      <ReviewSummary summary={summaryData} />

      {/* Impact on Trust Score */}
      <Card className="bg-gradient-to-r from-turquoise/5 to-emerald-50 dark:from-turquoise/10 dark:to-emerald-900/10 border-turquoise/20">
        <CardContent className="p-4">
          <div className="flex items-center gap-3">
            <TrendingUp className="w-8 h-8 text-turquoise" />
            <div>
              <p className="font-medium text-slate-900 dark:text-slate-100">
                Reviews Boost Your Trust Score
              </p>
              <p className="text-xs text-slate-500">
                Each positive review (4+ stars) adds 10 points to your Trust Score, up to 50 points maximum
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Reviews List */}
      <div className="space-y-4">
        {reviewData.reviews?.map((review) => (
          <EmployerReviewCard
            key={review.id}
            review={review}
            showResponse={true}
            onRespond={handleRespond}
          />
        ))}
      </div>

      {/* Response Dialog */}
      <Dialog 
        open={responseDialog.open} 
        onOpenChange={(open) => setResponseDialog({ open, review: responseDialog.review })}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <MessageSquare className="w-5 h-5 text-turquoise" />
              Respond to Review
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-4">
            {/* Original Review Preview */}
            {responseDialog.review && (
              <div className="p-3 bg-slate-50 dark:bg-slate-800/50 rounded-lg">
                <div className="flex items-center gap-2 mb-2">
                  <div className="flex">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <Star
                        key={star}
                        className={`w-4 h-4 ${
                          star <= responseDialog.review.rating
                            ? "fill-amber-400 text-amber-400"
                            : "fill-slate-200 text-slate-200"
                        }`}
                      />
                    ))}
                  </div>
                  <span className="text-sm text-slate-500">
                    by {responseDialog.review.recruiter_name || "Anonymous"}
                  </span>
                </div>
                <p className="text-sm text-slate-600 dark:text-slate-400 line-clamp-3">
                  &ldquo;{responseDialog.review.comment || "No comment provided"}&rdquo;
                </p>
              </div>
            )}

            {/* Response Input */}
            <div>
              <label className="text-sm font-medium text-slate-700 dark:text-slate-300 block mb-2">
                {t("reviews.yourResponse")}
              </label>
              <Textarea
                placeholder={t("reviews.responsePlaceholder")}
                value={responseText}
                onChange={(e) => setResponseText(e.target.value)}
                rows={4}
                className="resize-none"
              />
              <p className="text-xs text-slate-400 mt-1">
                {t("reviews.responseVisibility")}
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button 
              variant="outline" 
              onClick={() => setResponseDialog({ open: false, review: null })}
            >
              Cancel
            </Button>
            <Button 
              onClick={submitResponse}
              disabled={submitting || !responseText.trim()}
              className="bg-turquoise hover:bg-turquoise/90"
            >
              {submitting ? (
                "Submitting..."
              ) : (
                <>
                  <Send className="w-4 h-4 mr-2" />
                  Post Response
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default MyReviewsSection;

