// ============== Lazy Image Component ==============

export const LazyImage = memo(({ 
  src, 
  alt, 
  className = "", 
  placeholder = null,
  onLoad,
  onError 
}) => {
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState(false);
  const [inView, setInView] = useState(false);
  const imgRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setInView(true);
            observer.unobserve(entry.target);
          }
        });
      },
      { rootMargin: '100px', threshold: 0.1 }
    );

    if (imgRef.current) {
      observer.observe(imgRef.current);
    }

    return () => observer.disconnect();
  }, []);

  const handleLoad = useCallback(() => {
    setLoaded(true);
    onLoad?.();
  }, [onLoad]);

  const handleError = useCallback(() => {
    setError(true);
    onError?.();
  }, [onError]);

  return (
    <div ref={imgRef} className={`relative ${className}`}>
      {/* Placeholder while loading */}
      {!loaded && !error && (
        placeholder || <ThumbnailSkeleton className="absolute inset-0" />
      )}

      {/* Actual image - only load when in view */}
      {inView && !error && (
        <img
          src={src}
          alt={alt}
          className={`${className} transition-opacity duration-300 ${loaded ? 'opacity-100' : 'opacity-0'}`}
          onLoad={handleLoad}
          onError={handleError}
          loading="lazy"
          decoding="async"
        />
      )}

      {/* Error state */}
      {error && (
        <div className={`${className} bg-gray-200 dark:bg-gray-700 flex items-center justify-center`}>
          <span className="text-gray-400 text-sm">Image unavailable</span>
        </div>
      )}
    </div>
  );
});

// ============== Optimized Video Player ==============

export const OptimizedVideoPlayer = memo(forwardRef(({ 
  src,
  poster,
  controls = true,
  autoPlay = false,
  muted = false,
  loop = false,
  playsInline = true,
  className = "",
  onLoadedMetadata,
  onCanPlay,
  onPlay,
  onPause,
  onEnded,
  onError,
  showLoadingOverlay = true,
  "data-testid": testId
}, ref) => {
  const [loading, setLoading] = useState(true);
  const [buffering, setBuffering] = useState(false);
  const [hasError, setHasError] = useState(false);
  const internalRef = useRef(null);
  const videoRef = ref || internalRef;

  const handleLoadedMetadata = useCallback((e) => {
    setLoading(false);
    onLoadedMetadata?.(e);
  }, [onLoadedMetadata]);

  const handleCanPlay = useCallback((e) => {
    setBuffering(false);
    onCanPlay?.(e);
  }, [onCanPlay]);

  const handleWaiting = useCallback(() => {
    setBuffering(true);
  }, []);

  const handlePlaying = useCallback(() => {
    setBuffering(false);
  }, []);

  const handleError = useCallback((e) => {
    setHasError(true);
    setLoading(false);
    onError?.(e);
  }, [onError]);

  // Cleanup on unmount to prevent memory leaks
  useEffect(() => {
    const video = videoRef.current;
    return () => {
      if (video) {
        video.pause();
        video.src = '';
        video.load();
      }
    };
  }, [videoRef]);

  return (
    <div className={`relative ${className}`}>
      {/* Loading/Buffering overlay */}
      {showLoadingOverlay && (loading || buffering) && !hasError && (
        <div className="absolute inset-0 bg-black/60 flex items-center justify-center z-10 rounded-lg">
          <div className="text-center text-white">
            <Loader2 className="w-10 h-10 animate-spin mx-auto mb-2" />
            <p className="text-sm">{loading ? 'Loading video...' : 'Buffering...'}</p>
          </div>
        </div>
      )}

      {/* Poster image while loading */}
      {loading && poster && (
        <div className="absolute inset-0 z-5">
          <img 
            src={poster} 
            alt="Video thumbnail" 
            className="w-full h-full object-cover rounded-lg opacity-50"
          />
        </div>
      )}

      {/* Error state */}
      {hasError && (
        <div className="absolute inset-0 bg-gray-900 flex items-center justify-center rounded-lg">
          <div className="text-center text-white">
            <p className="text-sm">Failed to load video</p>
            <button 
              onClick={() => { setHasError(false); setLoading(true); videoRef.current?.load(); }}
              className="mt-2 text-xs text-teal-400 hover:underline"
            >
              Retry
            </button>
          </div>
        </div>
      )}

      <video
        ref={videoRef}
        src={src}
        poster={poster}
        controls={controls}
        autoPlay={autoPlay}
        muted={muted}
        loop={loop}
        playsInline={playsInline}
        preload="metadata"
        className={`w-full h-full rounded-lg ${loading ? 'opacity-0' : 'opacity-100'} transition-opacity duration-300`}
        onLoadedMetadata={handleLoadedMetadata}
        onCanPlay={handleCanPlay}
        onWaiting={handleWaiting}
        onPlaying={handlePlaying}
        onPlay={onPlay}
        onPause={onPause}
        onEnded={onEnded}
        onError={handleError}
        data-testid={testId}
      />
    </div>
  );
}));

// ============== Optimized Audio Player ==============

export const OptimizedAudioPlayer = memo(forwardRef(({
  src,
  className = "",
  showWaveform = false,
  onPlay,
  onPause,
  onEnded,
  onError,
  "data-testid": testId
}, ref) => {
  const [loading, setLoading] = useState(true);
  const [playing, setPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [muted, setMuted] = useState(false);
  const internalRef = useRef(null);
  const audioRef = ref || internalRef;

  const handleLoadedMetadata = useCallback(() => {
    setLoading(false);
    setDuration(audioRef.current?.duration || 0);
  }, [audioRef]);

  const handleTimeUpdate = useCallback(() => {
    const audio = audioRef.current;
    if (audio && audio.duration) {
      setProgress((audio.currentTime / audio.duration) * 100);
    }
  }, [audioRef]);

  const handlePlay = useCallback(() => {
    setPlaying(true);
    onPlay?.();
  }, [onPlay]);

  const handlePause = useCallback(() => {
    setPlaying(false);
    onPause?.();
  }, [onPause]);

  const handleEnded = useCallback(() => {
    setPlaying(false);
    setProgress(0);
    onEnded?.();
  }, [onEnded]);

  const togglePlay = useCallback(() => {
    const audio = audioRef.current;
    if (audio) {
      if (playing) {
        audio.pause();
      } else {
        audio.play();
      }
    }
  }, [playing, audioRef]);

  const toggleMute = useCallback(() => {
    const audio = audioRef.current;
    if (audio) {
      audio.muted = !muted;
      setMuted(!muted);
    }
  }, [muted, audioRef]);

  const seekTo = useCallback((e) => {
    const audio = audioRef.current;
    const rect = e.currentTarget.getBoundingClientRect();
    const percent = (e.clientX - rect.left) / rect.width;
    if (audio && audio.duration) {
      audio.currentTime = percent * audio.duration;
    }
  }, [audioRef]);

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Cleanup
  useEffect(() => {
    const audio = audioRef.current;
    return () => {
      if (audio) {
        audio.pause();
        audio.src = '';
      }
    };
  }, [audioRef]);

  return (
    <div className={`flex items-center gap-3 p-3 bg-gray-100 dark:bg-gray-800 rounded-lg ${className}`}>
      {/* Play/Pause Button */}
      <button
        onClick={togglePlay}
        disabled={loading}
        className="w-10 h-10 flex items-center justify-center bg-teal-500 hover:bg-teal-600 text-white rounded-full transition-colors disabled:opacity-50"
        data-testid={testId ? `${testId}-play` : undefined}
      >
        {loading ? (
          <Loader2 className="w-5 h-5 animate-spin" />
        ) : playing ? (
          <Pause className="w-5 h-5" />
        ) : (
          <Play className="w-5 h-5 ml-0.5" />
        )}
      </button>

      {/* Progress Bar */}
      <div className="flex-1 flex flex-col gap-1">
        <div 
          className="h-2 bg-gray-300 dark:bg-gray-600 rounded-full cursor-pointer overflow-hidden"
          onClick={seekTo}
        >
          <div 
            className="h-full bg-teal-500 rounded-full transition-all duration-100"
            style={{ width: `${progress}%` }}
          />
        </div>
        <div className="flex justify-between text-xs text-gray-500 dark:text-gray-400">
          <span>{formatTime((progress / 100) * duration)}</span>
          <span>{formatTime(duration)}</span>
        </div>
      </div>

      {/* Mute Button */}
      <button
        onClick={toggleMute}
        className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
      >
        {muted ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
      </button>

      {/* Hidden Audio Element */}
      <audio
        ref={audioRef}
        src={src}
        preload="metadata"
        onLoadedMetadata={handleLoadedMetadata}
        onTimeUpdate={handleTimeUpdate}
        onPlay={handlePlay}
        onPause={handlePause}
        onEnded={handleEnded}
        onError={onError}
        className="hidden"
      />
    </div>
  );
}));

