import { toast } from "sonner";
import { useTranslation } from "@/utils/i18n";
import { apiClient } from "@/utils/apiClient";

/**
 * Resume Auto-Fill Component
 * Provides copy-ready data from resume for job application forms
 */
const ResumeAutoFill = ({ resume }) => {
  const { t } = useTranslation();
  const [autofillData, setAutofillData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [copiedField, setCopiedField] = useState(null);
  const [activeTab, setActiveTab] = useState("personal");

  useEffect(() => {
    if (resume) {
      fetchAutofillData();
    } else {
      setLoading(false);
    }
  }, [resume]);

  const fetchAutofillData = async () => {
    try {
      const response = await apiClient.get("/autofill/data");
      setAutofillData(response.autofill_data);
    } catch (error) {
      console.error("Failed to fetch autofill data:", error);
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = async (value, fieldName) => {
    try {
      await navigator.clipboard.writeText(value);
      setCopiedField(fieldName);
      toast.success(t("autofill.copied") || "Copied to clipboard!");
      setTimeout(() => setCopiedField(null), 2000);
    } catch (error) {
      toast.error(t("autofill.copyFailed") || "Failed to copy");
    }
  };

  const copyAllInCategory = async (category) => {
    if (!autofillData?.[category]) return;

    const text = autofillData[category]
      .map(field => `${field.field_label}: ${field.value}`)
      .join("\n");

    await copyToClipboard(text, `all_${category}`);
  };

  const getIconForCategory = (category) => {
    switch (category) {
      case "personal": return User;
      case "professional": return Briefcase;
      case "education": return GraduationCap;
      case "skills": return Sparkles;
      case "work_history": return FileText;
      default: return FileText;
    }
  };

  const getIconForField = (fieldName) => {
    if (fieldName.includes("email")) return Mail;
    if (fieldName.includes("phone")) return Phone;
    if (fieldName.includes("location") || fieldName.includes("address")) return MapPin;
    if (fieldName.includes("linkedin")) return LinkedinIcon;
    return ClipboardCopy;
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-6 flex items-center justify-center">
          <Loader2 className="w-6 h-6 animate-spin text-turquoise" />
        </CardContent>
      </Card>
    );
  }

  if (!resume) {
    return (
      <Card>
        <CardContent className="p-6 text-center">
          <FileText className="w-12 h-12 text-slate-300 mx-auto mb-4" />
          <h3 className="font-medium text-slate-900 dark:text-slate-100 mb-2">
            {t("autofill.noResume") || "No Resume Found"}
          </h3>
          <p className="text-sm text-slate-500 dark:text-slate-400">
            {t("autofill.uploadFirst") || "Upload your resume to enable auto-fill"}
          </p>
        </CardContent>
      </Card>
    );
  }

  const categories = [
    { id: "personal", label: t("autofill.personal") || "Personal Info" },
    { id: "professional", label: t("autofill.professional") || "Professional" },
    { id: "education", label: t("autofill.education") || "Education" },
    { id: "skills", label: t("autofill.skills") || "Skills" },
    { id: "work_history", label: t("autofill.workHistory") || "Work History" }
  ];

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <ClipboardCopy className="w-5 h-5 text-turquoise" />
              {t("autofill.title") || "Auto-Fill Data"}
            </CardTitle>
            <CardDescription>
              {t("autofill.description") || "Click any field to copy for job applications"}
            </CardDescription>
          </div>
          <Button variant="outline" size="sm" onClick={fetchAutofillData}>
            <RefreshCw className="w-4 h-4 mr-1" />
            {t("common.refresh") || "Refresh"}
          </Button>
        </div>
      </CardHeader>

      <CardContent>
        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="grid grid-cols-5 mb-4">
            {categories.map(cat => {
              const Icon = getIconForCategory(cat.id);
              return (
                <TabsTrigger key={cat.id} value={cat.id} className="text-xs">
                  <Icon className="w-3 h-3 mr-1" />
                  <span className="hidden sm:inline">{cat.label}</span>
                </TabsTrigger>
              );
            })}
          </TabsList>

          {categories.map(cat => (
            <TabsContent key={cat.id} value={cat.id}>
              <div className="space-y-2">
                {/* Copy All Button */}
                {autofillData?.[cat.id]?.length > 0 && (
                  <div className="flex justify-end mb-3">
                    <Button 
                      variant="outline" 
                      size="sm"
                      onClick={() => copyAllInCategory(cat.id)}
                    >
                      <Copy className="w-3 h-3 mr-1" />
                      {t("autofill.copyAll") || "Copy All"}
                    </Button>
                  </div>
                )}

                {/* Fields */}
                {autofillData?.[cat.id]?.length > 0 ? (
                  <div className="grid gap-2">
                    {autofillData[cat.id].map((field, idx) => {
                      const FieldIcon = getIconForField(field.field_name);
                      const isCopied = copiedField === field.field_name;

                      return (
                        <button
                          key={idx}
                          onClick={() => copyToClipboard(field.value, field.field_name)}
                          className={`w-full p-3 rounded-lg border text-left transition-all ${
                            isCopied 
                              ? "border-green-500 bg-green-50 dark:bg-green-900/20" 
                              : "border-slate-200 dark:border-slate-700 hover:border-turquoise/50 hover:bg-slate-50 dark:hover:bg-slate-800/50"
                          }`}
                          data-testid={`autofill-${field.field_name}`}
                        >
                          <div className="flex items-start justify-between gap-2">
                            <div className="flex items-start gap-2 flex-1 min-w-0">
                              <FieldIcon className={`w-4 h-4 mt-0.5 flex-shrink-0 ${
                                isCopied ? "text-green-500" : "text-slate-400"
                              }`} />
                              <div className="min-w-0">
                                <p className="text-xs text-slate-500 dark:text-slate-400 mb-0.5">
                                  {field.field_label}
                                </p>
                                <p className={`text-sm font-medium truncate ${
                                  isCopied 
                                    ? "text-green-700 dark:text-green-300" 
                                    : "text-slate-900 dark:text-slate-100"
                                }`}>
                                  {field.value}
                                </p>
                              </div>
                            </div>
                            {isCopied ? (
                              <Check className="w-4 h-4 text-green-500 flex-shrink-0" />
                            ) : (
                              <Copy className="w-4 h-4 text-slate-300 flex-shrink-0" />
                            )}
                          </div>
                        </button>
                      );
                    })}
                  </div>
                ) : (
                  <div className="text-center py-8 text-slate-500 dark:text-slate-400">
                    <FileText className="w-8 h-8 mx-auto mb-2 opacity-50" />
                    <p className="text-sm">
                      {t("autofill.noDataInCategory") || "No data available in this category"}
                    </p>
                  </div>
                )}
              </div>
            </TabsContent>
          ))}
        </Tabs>

        {/* Quick tip */}
        <div className="mt-4 p-3 bg-turquoise/10 rounded-lg">
          <p className="text-xs text-turquoise-700 dark:text-turquoise-300">
            <Sparkles className="w-3 h-3 inline mr-1" />
            {t("autofill.tip") || "Tip: Click any field to instantly copy it for pasting into job application forms."}
          </p>
        </div>
      </CardContent>
    </Card>
  );
};

export default ResumeAutoFill;

import { useState, useEffect } from "react";
import { useTranslation } from "@/utils/i18n";
import { toast } from "sonner";
import { 
  CreditCard, Calendar, Clock, AlertCircle, CheckCircle, 
  XCircle, RefreshCw, ExternalLink, Download, Loader2,
  ChevronDown, ChevronUp, Shield
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import api from "@/utils/apiClient";

const API = process.env.REACT_APP_BACKEND_URL;

const SubscriptionManager = ({ user }) => {
  const { t } = useTranslation();
  const [subscription, setSubscription] = useState(null);
  const [billingHistory, setBillingHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  useEffect(() => {
    fetchSubscription();
    fetchBillingHistory();
  }, []);

  const fetchSubscription = async () => {
    try {
      const response = await api.client.get(`${API}/api/payments/subscription`);
      setSubscription(response.data);
    } catch (e) {
      console.error("Failed to fetch subscription:", e);
    }
    setLoading(false);
  };

  const fetchBillingHistory = async () => {
    try {
      const response = await api.client.get(`${API}/api/payments/billing-history`);
      setBillingHistory(response.data.stripe_invoices || []);
    } catch (e) {
      console.error("Failed to fetch billing history:", e);
    }
  };

  const handleCancelSubscription = async () => {
    setActionLoading(true);
    try {
      const response = await api.client.post(`${API}/api/payments/subscription/cancel`);
      toast.success(response.data.message);
      fetchSubscription();
    } catch (e) {
      toast.error(e.response?.data?.detail || "Failed to cancel subscription");
    }
    setActionLoading(false);
  };

  const handleReactivateSubscription = async () => {
    setActionLoading(true);
    try {
      const response = await api.client.post(`${API}/api/payments/subscription/reactivate`);
      toast.success(response.data.message);
      fetchSubscription();
    } catch (e) {
      toast.error(e.response?.data?.detail || "Failed to reactivate subscription");
    }
    setActionLoading(false);
  };

  const handleUpdatePaymentMethod = async () => {
    setActionLoading(true);
    try {
      const response = await api.client.post(`${API}/api/payments/update-payment-method`);
      if (response.data.url) {
        window.location.href = response.data.url;
      }
    } catch (e) {
      toast.error(e.response?.data?.detail || "Failed to open payment settings");
    }
    setActionLoading(false);
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return "N/A";
    return new Date(dateStr).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      active: { color: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400", icon: CheckCircle },
      trialing: { color: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400", icon: Clock },
      past_due: { color: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400", icon: AlertCircle },
      canceled: { color: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400", icon: XCircle },
      canceling: { color: "bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400", icon: Clock },
    };

    const config = statusConfig[status] || statusConfig.active;
    const Icon = config.icon;

    return (
      <Badge className={`${config.color} flex items-center gap-1`}>
        <Icon className="w-3 h-3" />
        {status?.toUpperCase()}
      </Badge>
    );
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="w-6 h-6 animate-spin text-violet-500" />
      </div>
    );
  }

  if (!subscription?.has_subscription) {
    return null; // Don't show if no subscription
  }

  return (
    <Card className="border-violet-200 dark:border-violet-800" data-testid="subscription-manager">
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2 text-lg">
              <Shield className="w-5 h-5 text-violet-500" />
              Subscription Management
            </CardTitle>
            <CardDescription>Manage your Recruiter Pro subscription</CardDescription>
          </div>
          {getStatusBadge(subscription.status)}
        </div>
      </CardHeader>

      <CardContent className="space-y-6">
        {/* Current Plan Info */}
        <div className="grid md:grid-cols-2 gap-4">
          <div className="p-4 bg-violet-50 dark:bg-violet-900/20 rounded-lg">
            <p className="text-sm text-slate-500 dark:text-slate-400 mb-1">Current Plan</p>
            <p className="font-semibold text-slate-900 dark:text-slate-100">
              {subscription.plan} - ${subscription.price}/month
            </p>
          </div>

          <div className="p-4 bg-violet-50 dark:bg-violet-900/20 rounded-lg">
            <p className="text-sm text-slate-500 dark:text-slate-400 mb-1">
              {subscription.trial_end && new Date(subscription.trial_end) > new Date() 
                ? "Trial Ends" 
                : "Next Billing Date"}
            </p>
            <p className="font-semibold text-slate-900 dark:text-slate-100 flex items-center gap-2">
              <Calendar className="w-4 h-4 text-violet-500" />
              {subscription.trial_end && new Date(subscription.trial_end) > new Date()
                ? formatDate(subscription.trial_end)
                : formatDate(subscription.current_period_end)}
            </p>
          </div>
        </div>

        {/* Payment Method */}
        {subscription.payment_method && (
          <div className="p-4 border border-slate-200 dark:border-slate-700 rounded-lg">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-slate-100 dark:bg-slate-800 rounded-lg flex items-center justify-center">
                  <CreditCard className="w-5 h-5 text-slate-600 dark:text-slate-400" />
                </div>
                <div>
                  <p className="font-medium text-slate-900 dark:text-slate-100 capitalize">
                    {subscription.payment_method.brand} •••• {subscription.payment_method.last4}
                  </p>
                  <p className="text-sm text-slate-500 dark:text-slate-400">
                    Expires {subscription.payment_method.exp_month}/{subscription.payment_method.exp_year}
                  </p>
                </div>
              </div>
              <Button 
                variant="outline" 
                size="sm"
                onClick={handleUpdatePaymentMethod}
                disabled={actionLoading}
              >
                {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : "Update"}
              </Button>
            </div>
          </div>
        )}

        {/* Cancel Warning */}
        {subscription.cancel_at_period_end && (
          <div className="p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg">
            <div className="flex items-start gap-3">
              <AlertCircle className="w-5 h-5 text-amber-600 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-medium text-amber-800 dark:text-amber-200">
                  Subscription ending
                </p>
                <p className="text-sm text-amber-700 dark:text-amber-300">
                  Your subscription will end on {formatDate(subscription.current_period_end)}. 
                  You'll lose access to premium features after this date.
                </p>
                <Button 
                  size="sm" 
                  className="mt-3 bg-amber-600 hover:bg-amber-700"
                  onClick={handleReactivateSubscription}
                  disabled={actionLoading}
                >
                  {actionLoading ? (
                    <Loader2 className="w-4 h-4 animate-spin mr-2" />
                  ) : (
                    <RefreshCw className="w-4 h-4 mr-2" />
                  )}
                  Keep Subscription
                </Button>
              </div>
            </div>
          </div>
        )}

        {/* Billing History */}
        <div>
          <button 
            onClick={() => setShowHistory(!showHistory)}
            className="flex items-center justify-between w-full p-3 text-left hover:bg-slate-50 dark:hover:bg-slate-800 rounded-lg transition-colors"
          >
            <span className="font-medium text-slate-900 dark:text-slate-100">Billing History</span>
            {showHistory ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
          </button>

          {showHistory && (
            <div className="mt-2 space-y-2">
              {billingHistory.length === 0 ? (
                <p className="text-sm text-slate-500 dark:text-slate-400 p-3">
                  No billing history yet
                </p>
              ) : (
                billingHistory.map((invoice, idx) => (
                  <div 
                    key={invoice.invoice_id || idx}
                    className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800 rounded-lg"
                  >
                    <div>
                      <p className="font-medium text-slate-900 dark:text-slate-100">
                        ${invoice.amount?.toFixed(2)} {invoice.currency?.toUpperCase()}
                      </p>
                      <p className="text-sm text-slate-500 dark:text-slate-400">
                        {formatDate(invoice.paid_at || invoice.period_start)}
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge className={
                        invoice.status === 'paid' 
                          ? 'bg-emerald-100 text-emerald-700' 
                          : 'bg-slate-100 text-slate-700'
                      }>
                        {invoice.status}
                      </Badge>
                      {invoice.invoice_pdf && (
                        <a 
                          href={invoice.invoice_pdf} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="p-1.5 hover:bg-slate-200 dark:hover:bg-slate-700 rounded"
                        >
                          <Download className="w-4 h-4 text-slate-500" />
                        </a>
                      )}
                      {invoice.hosted_invoice_url && (
                        <a 
                          href={invoice.hosted_invoice_url} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="p-1.5 hover:bg-slate-200 dark:hover:bg-slate-700 rounded"
                        >
                          <ExternalLink className="w-4 h-4 text-slate-500" />
                        </a>
                      )}
                    </div>
                  </div>
                ))
              )}
            </div>
          )}
        </div>

        {/* Actions */}
        {!subscription.cancel_at_period_end && subscription.status !== 'canceled' && (
          <div className="pt-4 border-t border-slate-200 dark:border-slate-700">
            <AlertDialog>
              <AlertDialogTrigger asChild>
                <Button variant="outline" className="text-red-600 border-red-200 hover:bg-red-50">
                  Cancel Subscription
                </Button>
              </AlertDialogTrigger>
              <AlertDialogContent>
                <AlertDialogHeader>
                  <AlertDialogTitle>Cancel your subscription?</AlertDialogTitle>
                  <AlertDialogDescription>
                    Your subscription will remain active until the end of your current billing period 
                    ({formatDate(subscription.current_period_end)}). After that, you'll lose access to:
                    <ul className="list-disc list-inside mt-2 space-y-1">
                      <li>Unlimited job postings</li>
                      <li>Advanced candidate search</li>
                      <li>ATS and analytics</li>
                      <li>In-app messaging</li>
                    </ul>
                  </AlertDialogDescription>
                </AlertDialogHeader>
                <AlertDialogFooter>
                  <AlertDialogCancel>{t("subscription.keepSubscription")}</AlertDialogCancel>
                  <AlertDialogAction 
                    onClick={handleCancelSubscription}
                    className="bg-red-600 hover:bg-red-700"
                  >
                    {actionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : t("subscription.cancelSubscription")}
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>
            </AlertDialog>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

export default SubscriptionManager;

/**
 * Translation Benchmarking Dashboard
 * Shows KPI metrics, tier coverage, and auto-translation controls
 */
import React, { useState, useEffect } from 'react';
import { 
  BarChart3, Target, Globe, AlertTriangle, CheckCircle, 
  Play, RefreshCw, TrendingUp, Award, Zap, Bell, BellOff,
  ChevronDown, ChevronUp, Loader2
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Switch } from '@/components/ui/switch';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import axios from 'axios';

const API = process.env.REACT_APP_BACKEND_URL;

// Grade color mapping
const gradeColors = {
  'A+': 'bg-emerald-500',
  'A': 'bg-green-500',
  'B+': 'bg-lime-500',
  'B': 'bg-yellow-500',
  'C': 'bg-orange-500',
  'D': 'bg-red-400',
  'F': 'bg-red-600'
};

// Status colors
const statusColors = {
  excellent: 'text-emerald-500',
  good: 'text-green-500',
  needs_improvement: 'text-yellow-500',
  critical: 'text-red-500'
};

// Tier badge colors
const tierBadgeColors = {
  tier1: 'bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400',
  tier2: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400',
  tier3: 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400'
};

const TranslationBenchmarkDashboard = () => {
  const [benchmark, setBenchmark] = useState(null);
  const [loading, setLoading] = useState(true);
  const [autoTranslating, setAutoTranslating] = useState(false);
  const [translationJob, setTranslationJob] = useState(null);
  const [alertThreshold, setAlertThreshold] = useState(90);
  const [alertsEnabled, setAlertsEnabled] = useState(true);
  const [expandedTiers, setExpandedTiers] = useState({});
  const [targetKpi, setTargetKpi] = useState(95);

  useEffect(() => {
    fetchBenchmark();
  }, []);

  // Poll for translation job status
  useEffect(() => {
    if (!translationJob || translationJob.status === 'completed') return;

    const interval = setInterval(async () => {
      try {
        const res = await axios.get(`${API}/api/translation-qa/auto-translate/${translationJob.job_id}`);
        setTranslationJob(res.data);

        if (res.data.status === 'completed') {
          toast.success(`Auto-translation complete! ${res.data.keys_translated} keys translated.`);
          setAutoTranslating(false);
          fetchBenchmark();
        }
      } catch (err) {
        console.error('Status check failed:', err);
      }
    }, 3000);

    return () => clearInterval(interval);
  }, [translationJob]);

  const fetchBenchmark = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API}/api/translation-qa/benchmark`);
      setBenchmark(res.data);
      setAlertThreshold(res.data.alert_config?.threshold || 90);
      setAlertsEnabled(res.data.alert_config?.enabled ?? true);
    } catch (err) {
      console.error('Failed to fetch benchmark:', err);
      toast.error('Failed to load benchmark data');
    }
    setLoading(false);
  };

  const startAutoTranslation = async (dryRun = false) => {
    try {
      setAutoTranslating(true);
      const res = await axios.post(`${API}/api/translation-qa/auto-translate`, {
        target_kpi: targetKpi,
        dry_run: dryRun
      });

      if (dryRun) {
        toast.info(`Dry run: Would translate ${res.data.total_keys_to_translate} keys in ${res.data.languages_to_translate} languages`);
        setAutoTranslating(false);
      } else {
        setTranslationJob(res.data);
        toast.info(`Started auto-translation for ${res.data.languages_to_translate} languages...`);
      }
    } catch (err) {
      setAutoTranslating(false);
      toast.error('Failed to start auto-translation');
    }
