              {/* Work Type Badge (Remote/Hybrid/On-site) */}
              {job.work_type && (
                <Badge 
                  className={`text-xs px-2 py-0.5 flex items-center gap-1 font-medium ${
                    job.work_type === 'Remote' 
                      ? 'bg-turquoise/20 text-turquoise border border-turquoise/30' 
                      : job.work_type === 'Hybrid'
                      ? 'bg-purple-500/20 text-purple-600 dark:text-purple-400 border border-purple-500/30'
                      : 'bg-orange-500/20 text-orange-600 dark:text-orange-400 border border-orange-500/30'
                  }`}
                  data-testid="work-type-badge"
                >
                  {job.work_type === 'Remote' && <Laptop className="w-3 h-3" />}
                  {job.work_type === 'Hybrid' && <Home className="w-3 h-3" />}
                  {job.work_type === 'On-site' && <Building className="w-3 h-3" />}
                  {job.work_type}
                </Badge>
              )}

              <span className="flex items-center gap-1">
                <MapPin className="w-4 h-4" />
                {job.location}
              </span>
              {job.posted_at && (
                <span className="flex items-center gap-1">
                  <Clock className="w-4 h-4" />
                  {formatDate(job.posted_at)}
                </span>
              )}
              {job.salary && (
                <span className="text-emerald-600 dark:text-emerald-400 font-medium">{job.salary}</span>
              )}
              <Badge variant="secondary" className="text-xs dark:bg-slate-700 dark:text-slate-200">
                {job.source}
              </Badge>
            </div>

            {job.tags?.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-3">
                {job.tags.slice(0, 5).map((tag, i) => (
                  <span key={i} className="tag-badge dark:bg-slate-700 dark:text-slate-200">{tag}</span>
                ))}
              </div>
            )}

            {matchData?.analysis && (
              <p className="text-sm text-slate-600 dark:text-slate-300 bg-slate-50 dark:bg-slate-800 p-3 rounded-lg mb-3">
                {matchData.analysis}
              </p>
            )}

            {showActions && (
              <div className="flex flex-wrap items-center gap-2 pt-2">
                {/* Why was I matched? - Explainable AI (always show if job has ID) */}
                {job.id && (
                  <MatchExplanation
                    jobId={job.id}
                    jobTitle={job.title}
                    matchScore={matchData?.match_score || job.match_score || job.relevance_score}
                    trigger={
                      <Button 
                        variant="ghost" 
                        size="sm"
                        className="text-turquoise hover:text-turquoise/80 hover:bg-turquoise/10"
                        data-testid={`why-matched-btn-${job.id}`}
                      >
                        <Brain className="w-4 h-4 mr-1" />
                        Why matched?
                      </Button>
                    }
                  />
                )}
                {!matchData && (
                  <Button 
                    variant="outline" size="sm"
                    onClick={handleAnalyze}
                    disabled={analyzing}
                    data-testid={`analyze-btn-${job.id}`}
                  >
                    {analyzing ? <><Loader2 className="w-4 h-4 mr-1 animate-spin" /> Analyzing...</> : "Analyze Match"}
                  </Button>
                )}
                {job.url && !verifiedStatus && (
                  <Button
                    variant="outline" size="sm"
                    onClick={handleVerifyStatus}
                    disabled={verifyingStatus}
                    data-testid={`verify-status-btn-${job.id}`}
                    className="text-slate-600 dark:text-slate-300"
                  >
                    {verifyingStatus ? (
                      <><Loader2 className="w-4 h-4 mr-1 animate-spin" /> Checking...</>
                    ) : (
                      <><CheckCircle2 className="w-4 h-4 mr-1" /> Verify Status</>
                    )}
                  </Button>
                )}
                <Button 
                  variant={isSaved ? "secondary" : "outline"}
                  size="sm"
                  onClick={() => onSave(job)}
                  data-testid={`save-btn-${job.id}`}
                >
                  <Bookmark className={`w-4 h-4 mr-1 ${isSaved ? 'fill-current' : ''}`} />
                  {isSaved ? t("jobs.saved") : t("common.save")}
                </Button>
                <Button size="sm" onClick={() => onApply(job)} data-testid={`apply-btn-${job.id}`}>
                  {t("jobs.apply")} <ChevronRight className="w-4 h-4 ml-1" />
                </Button>
                {job.url && (
                  <a href={job.url} target="_blank" rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-sm text-sky-600 hover:text-sky-700 dark:text-sky-400 dark:hover:text-sky-300">
                    {t("jobs.viewOriginal")} <ExternalLink className="w-3 h-3" />
                  </a>
                )}
                {/* Report Ghost Job Button */}
                {job.id && (
                  <ReportExpiredJob jobId={job.id} jobTitle={job.title} />
                )}
              </div>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

