import { useState, useRef, useCallback } from 'react';

const API = process.env.REACT_APP_BACKEND_URL;

export const CAPTION_LANGUAGES = {
  en: 'English', es: 'Spanish', fr: 'French', de: 'German',
  it: 'Italian', pt: 'Portuguese', 'pt-BR': 'Portuguese (Brazil)', 'pt-PT': 'Portuguese (Portugal)',
  ja: 'Japanese', ko: 'Korean', zh: 'Chinese', nl: 'Dutch', ar: 'Arabic', hi: 'Hindi',
  ru: 'Russian', tr: 'Turkish', pl: 'Polish', sv: 'Swedish', sw: 'Swahili',
  da: 'Danish', fi: 'Finnish', el: 'Greek', cs: 'Czech', hu: 'Hungarian', ro: 'Romanian',
  bn: 'Bengali', ta: 'Tamil', ur: 'Urdu', vi: 'Vietnamese', th: 'Thai', id: 'Indonesian',
  ms: 'Malay', tl: 'Filipino', am: 'Amharic', ha: 'Hausa', yo: 'Yoruba', ig: 'Igbo'
};

/**
 * Live transcription hook with multi-language support.
 * Captures audio, sends to Whisper, optionally translates captions.
 * Auto-syncs display language from user's i18n locale preference.
 */
export function useLiveTranscription() {
  const [active, setActive] = useState(false);
  const [captions, setCaptions] = useState([]);
  const [fullTranscript, setFullTranscript] = useState('');

  // Auto-detect user's preferred language from localStorage (set by i18n)
  const getUserLangPref = () => {
    const savedLang = localStorage.getItem('karau_language') || localStorage.getItem('language') || 'en';
    // Map i18n locale to caption language (strip region if needed)
    const base = savedLang.split('-')[0];
    // Check exact match first (pt-BR, pt-PT), then base
    if (CAPTION_LANGUAGES[savedLang]) return savedLang;
    if (CAPTION_LANGUAGES[base]) return base;
    return 'en';
  };

  const [sourceLanguage, setSourceLanguage] = useState('en');
  const [displayLanguage, setDisplayLanguage] = useState(getUserLangPref);
  const recorderRef = useRef(null);
  const intervalRef = useRef(null);
  const chunksRef = useRef([]);
  const srcLangRef = useRef('en');
  const dspLangRef = useRef(getUserLangPref());

  // Keep refs in sync with state for use inside callbacks
  const updateSourceLang = useCallback((lang) => {
    setSourceLanguage(lang);
    srcLangRef.current = lang;
  }, []);

  const updateDisplayLang = useCallback((lang) => {
    setDisplayLanguage(lang);
    dspLangRef.current = lang;
  }, []);

  const translateText = useCallback(async (text, src, tgt) => {
    if (src === tgt || !text.trim()) return text;
    const token = localStorage.getItem('token') || localStorage.getItem('karau_token');
    try {
      const res = await fetch(`${API}/api/karau/webinar/translate-caption`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify({ text, source_language: src, target_language: tgt })
      });
      if (res.ok) {
        const data = await res.json();
        return data.translated || text;
      }
    } catch (e) { console.warn('Translation error:', e); }
    return text;
  }, []);

  const activeSpeakerRef = useRef(null);

  const setActiveSpeaker = useCallback((speaker) => {
    activeSpeakerRef.current = speaker;
  }, []);

  const transcribeChunk = useCallback(async (blob) => {
    if (blob.size < 1000) return;
    const token = localStorage.getItem('token') || localStorage.getItem('karau_token');
    try {
      const reader = new FileReader();
      const base64 = await new Promise((resolve) => {
        reader.onloadend = () => resolve(reader.result.split(',')[1]);
        reader.readAsDataURL(blob);
      });

      const res = await fetch(`${API}/api/realtime-stt/transcribe-base64`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify({ audio: base64, format: 'webm', language: srcLangRef.current })
      });
      if (res.ok) {
        const data = await res.json();
        if (data.text?.trim()) {
          const originalText = data.text.trim();
          const speaker = activeSpeakerRef.current;
          const speakerLabel = speaker?.name || '';
          const fullLine = speakerLabel ? `${speakerLabel}: ${originalText}` : originalText;
          setFullTranscript(prev => prev + ' ' + fullLine);

          // Translate if display language differs
          let displayText = originalText;
          if (srcLangRef.current !== dspLangRef.current) {
            displayText = await translateText(originalText, srcLangRef.current, dspLangRef.current);
          }

          const caption = {
            text: displayText,
            original: originalText,
            speaker: speakerLabel,
            speakerColor: speaker?.color || '#a78bfa',
            ts: Date.now(),
            lang: dspLangRef.current
          };
          setCaptions(prev => [...prev.slice(-20), caption]);
        }
      }
    } catch (e) { console.warn('Transcription chunk error:', e); }
  }, [translateText]);

  const start = useCallback((stream) => {
    if (!stream || active) return;
    try {
      const audioTracks = stream.getAudioTracks();
      if (audioTracks.length === 0) return;
      const audioStream = new MediaStream(audioTracks);

      const recorder = new MediaRecorder(audioStream, {
        mimeType: MediaRecorder.isTypeSupported('audio/webm;codecs=opus')
          ? 'audio/webm;codecs=opus' : 'audio/webm'
      });
      recorderRef.current = recorder;
      chunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      };

      intervalRef.current = setInterval(() => {
        if (chunksRef.current.length > 0) {
          const blob = new Blob(chunksRef.current, { type: 'audio/webm' });
          chunksRef.current = [];
          transcribeChunk(blob);
        }
      }, 8000);

      recorder.start(1000);
      setActive(true);
    } catch (e) { console.error('Live transcription start error:', e); }
  }, [active, transcribeChunk]);

  const stop = useCallback(() => {
    if (intervalRef.current) clearInterval(intervalRef.current);
    if (recorderRef.current?.state !== 'inactive') {
      try { recorderRef.current?.stop(); } catch {}
    }
    if (chunksRef.current.length > 0) {
      const blob = new Blob(chunksRef.current, { type: 'audio/webm' });
      chunksRef.current = [];
      transcribeChunk(blob);
    }
    recorderRef.current = null;
    setActive(false);
  }, [transcribeChunk]);

  const clear = useCallback(() => {
    setCaptions([]);
    setFullTranscript('');
  }, []);

  return {
    active, captions, fullTranscript,
    sourceLanguage, displayLanguage,
    setSourceLanguage: updateSourceLang,
    setDisplayLanguage: updateDisplayLang,
    setActiveSpeaker,
    start, stop, clear
  };
}

export default useLiveTranscription;

import { useState, useRef, useCallback, useEffect } from 'react';

/**
 * Enhanced Noise cancellation hook with dual-engine approach:
 * 1. RNNoise WASM - ML-based noise suppression (preferred)
 * 2. Web Audio API - noise gate + bandpass filter (fallback)
 */
export function useNoiseCancellation() {
  const [enabled, setEnabled] = useState(false);
  const [level, setLevel] = useState(50);
  const [engine, setEngine] = useState('auto'); // 'auto', 'rnnoise', 'webaudio'
  const [activeEngine, setActiveEngine] = useState(null);
  const audioCtxRef = useRef(null);
  const sourceRef = useRef(null);
  const destRef = useRef(null);
  const streamRef = useRef(null);
  const processedStreamRef = useRef(null);
  const rnnoiseRef = useRef(null);
  const workletNodeRef = useRef(null);
  const gainRef = useRef(null);
  const analyserRef = useRef(null);
  const rafRef = useRef(null);

  const cleanup = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    if (workletNodeRef.current) { try { workletNodeRef.current.disconnect(); } catch {} }
    if (sourceRef.current) { try { sourceRef.current.disconnect(); } catch {} }
    if (audioCtxRef.current?.state !== 'closed') {
      try { audioCtxRef.current?.close(); } catch {}
    }
    audioCtxRef.current = null;
    processedStreamRef.current = null;
    workletNodeRef.current = null;
    rnnoiseRef.current = null;
    setActiveEngine(null);
  }, []);

  useEffect(() => cleanup, [cleanup]);

  /**
   * Try to initialize RNNoise WASM engine
   */
  const initRnnoise = useCallback(async (ctx, source, dest) => {
    try {
      const { Rnnoise } = await import('@shiguredo/rnnoise-wasm');
      const rnnoise = await Rnnoise.load();
      rnnoiseRef.current = rnnoise;

      // Create ScriptProcessor for RNNoise processing
      // RNNoise needs 480 samples per frame at 48kHz
      const bufferSize = 4096;
      const processor = ctx.createScriptProcessor(bufferSize, 1, 1);
      const denoiseState = rnnoise.createDenoiseState();
      const frameSize = 480;

      processor.onaudioprocess = (e) => {
        const input = e.inputBuffer.getChannelData(0);
        const output = e.outputBuffer.getChannelData(0);

        // Process in 480-sample frames
        for (let offset = 0; offset < input.length; offset += frameSize) {
          const end = Math.min(offset + frameSize, input.length);
          const frame = new Float32Array(frameSize);

          // Copy and scale input (RNNoise expects [-32768, 32767] range)
          for (let i = 0; i < end - offset; i++) {
            frame[i] = input[offset + i] * 32768;
          }

          // Apply RNNoise
          denoiseState.processFrame(frame);

          // Scale back and copy to output
          for (let i = 0; i < end - offset; i++) {
            output[offset + i] = frame[i] / 32768;
          }
        }
      };

      source.connect(processor);
      processor.connect(dest);
      workletNodeRef.current = processor;
      setActiveEngine('rnnoise');
      return true;
    } catch (err) {
      console.warn('RNNoise init failed, falling back to Web Audio:', err);
      return false;
    }
  }, []);

  /**
   * Fallback: Web Audio API noise gate + bandpass filter
   */
  const initWebAudio = useCallback((ctx, source, dest) => {
    // High-pass filter to remove rumble (<80Hz)
    const hpFilter = ctx.createBiquadFilter();
    hpFilter.type = 'highpass';
    hpFilter.frequency.value = 80;
    hpFilter.Q.value = 0.7;

    // Bandpass focused on voice (300Hz - 3400Hz)
    const bpFilter = ctx.createBiquadFilter();
    bpFilter.type = 'bandpass';
    bpFilter.frequency.value = 1500;
    bpFilter.Q.value = 0.5;

    // Compressor
    const compressor = ctx.createDynamicsCompressor();
    compressor.threshold.value = -50;
    compressor.knee.value = 40;
    compressor.ratio.value = 12;
    compressor.attack.value = 0;
    compressor.release.value = 0.25;

    // Noise gate via gain
    const gain = ctx.createGain();
    gain.gain.value = 1;
    gainRef.current = gain;

    // Analyser for level detection
    const analyser = ctx.createAnalyser();
    analyser.fftSize = 2048;
    analyser.smoothingTimeConstant = 0.8;
    analyserRef.current = analyser;

    // Chain: source -> HP -> BP -> compressor -> gain -> analyser -> dest
    source.connect(hpFilter);
    hpFilter.connect(bpFilter);
    bpFilter.connect(compressor);
    compressor.connect(gain);
    gain.connect(analyser);
    analyser.connect(dest);

    // Noise gate loop
    const dataArray = new Uint8Array(analyser.frequencyBinCount);
    const gateLoop = () => {
      if (!analyserRef.current) return;
      analyser.getByteFrequencyData(dataArray);
      const voiceStart = Math.floor(300 / (ctx.sampleRate / analyser.fftSize));
      const voiceEnd = Math.floor(3400 / (ctx.sampleRate / analyser.fftSize));
      let sum = 0;
      for (let i = voiceStart; i < voiceEnd && i < dataArray.length; i++) sum += dataArray[i];
      const avg = sum / Math.max(voiceEnd - voiceStart, 1);
      const threshold = 10 + (level / 100) * 70;

      if (avg < threshold) {
        gain.gain.setTargetAtTime(0.02, ctx.currentTime, 0.015);
      } else {
        gain.gain.setTargetAtTime(1, ctx.currentTime, 0.005);
      }
      rafRef.current = requestAnimationFrame(gateLoop);
    };
    gateLoop();

    setActiveEngine('webaudio');
  }, [level]);

  /**
   * Apply noise cancellation to a MediaStream
   */
  const applyToStream = useCallback(async (stream) => {
    if (!stream) return stream;
    cleanup();
    streamRef.current = stream;

    const ctx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 48000 });
    audioCtxRef.current = ctx;

    const source = ctx.createMediaStreamSource(stream);
    sourceRef.current = source;
    const dest = ctx.createMediaStreamDestination();
    destRef.current = dest;

    // Try RNNoise first if engine allows
    let useRnnoise = false;
    if (engine === 'auto' || engine === 'rnnoise') {
      useRnnoise = await initRnnoise(ctx, source, dest);
    }

    // Fallback to Web Audio
    if (!useRnnoise) {
      initWebAudio(ctx, source, dest);
    }

    // Combine processed audio with original video tracks
    const processedStream = new MediaStream();
    dest.stream.getAudioTracks().forEach(t => processedStream.addTrack(t));
    stream.getVideoTracks().forEach(t => processedStream.addTrack(t));

    processedStreamRef.current = processedStream;
    setEnabled(true);
    return processedStream;
  }, [engine, level, cleanup, initRnnoise, initWebAudio]);

  const removeFromStream = useCallback(() => {
    cleanup();
    setEnabled(false);
    return streamRef.current;
  }, [cleanup]);

  const updateLevel = useCallback((newLevel) => {
    setLevel(newLevel);
  }, []);

  const switchEngine = useCallback((newEngine) => {
    setEngine(newEngine);
    // If currently active, re-apply with new engine
    if (enabled && streamRef.current) {
      applyToStream(streamRef.current);
    }
  }, [enabled, applyToStream]);

  return {
    enabled,
    level,
    engine,
    activeEngine,
    applyToStream,
    removeFromStream,
    updateLevel,
    switchEngine,
    processedStream: processedStreamRef.current,
    isSupported: typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)
  };
}

export default useNoiseCancellation;

import { useState, useRef, useCallback, useEffect } from 'react';

/**
 * Spatial audio hook - positions audio in 3D space based on speaker video tile location.
 * Uses Web Audio API PannerNode for directional audio.
 */
export function useSpatialAudio() {
  const [enabled, setEnabled] = useState(false);
  const audioContextRef = useRef(null);
  const pannersRef = useRef({});
  const listenerPosRef = useRef({ x: 0, y: 0, z: 0 });

  const getContext = useCallback(() => {
    if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
      audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
    }
    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
    return audioContextRef.current;
  }, []);

  /**
   * Connect a remote audio stream to spatial panner.
   * @param {string} userId - Unique ID for the remote participant
   * @param {MediaStream} stream - The remote audio stream
   * @param {Object} position - {x, y} normalized position (-1 to 1) of the video tile
   */
  const connectStream = useCallback((userId, stream, position = { x: 0, y: 0 }) => {
    if (!enabled || !stream) return;
    // Disconnect existing if any
    disconnectStream(userId);

    const ctx = getContext();
    try {
      const source = ctx.createMediaStreamSource(stream);
      const panner = ctx.createPanner();
      panner.panningModel = 'HRTF';
      panner.distanceModel = 'inverse';
      panner.refDistance = 1;
      panner.maxDistance = 10;
      panner.rolloffFactor = 1;
      panner.coneInnerAngle = 360;
      panner.coneOuterAngle = 0;
      panner.coneOuterGain = 0;

      // Position in 3D space (x = left/right, y = up/down, z = front/back)
      const x = (position.x || 0) * 3;
      const y = (position.y || 0) * 1;
      const z = -2;
      panner.positionX.setValueAtTime(x, ctx.currentTime);
      panner.positionY.setValueAtTime(y, ctx.currentTime);
      panner.positionZ.setValueAtTime(z, ctx.currentTime);

      source.connect(panner);
      panner.connect(ctx.destination);

      pannersRef.current[userId] = { source, panner, stream };
    } catch (e) {
      console.warn('Spatial audio connect error:', e);
    }
  }, [enabled, getContext]);

  /**
   * Update the spatial position of an existing stream.
   */
  const updatePosition = useCallback((userId, position) => {
    const entry = pannersRef.current[userId];
    if (!entry || !audioContextRef.current) return;

    const ctx = audioContextRef.current;
    const x = (position.x || 0) * 3;
    const y = (position.y || 0) * 1;

    // Smooth transition
    entry.panner.positionX.linearRampToValueAtTime(x, ctx.currentTime + 0.3);
    entry.panner.positionY.linearRampToValueAtTime(y, ctx.currentTime + 0.3);
  }, []);

  const disconnectStream = useCallback((userId) => {
    const entry = pannersRef.current[userId];
    if (entry) {
      try {
        entry.source.disconnect();
        entry.panner.disconnect();
      } catch {}
      delete pannersRef.current[userId];
    }
  }, []);

  const toggle = useCallback(() => {
    setEnabled(prev => {
      const next = !prev;
      if (!next) {
        // Disconnect all panners when disabling
        Object.keys(pannersRef.current).forEach(uid => disconnectStream(uid));
        if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
          try { audioContextRef.current.close(); } catch {}
        }
        audioContextRef.current = null;
      }
      return next;
    });
  }, [disconnectStream]);

  const cleanup = useCallback(() => {
    Object.keys(pannersRef.current).forEach(uid => disconnectStream(uid));
    if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
      try { audioContextRef.current.close(); } catch {}
    }
    audioContextRef.current = null;
    pannersRef.current = {};
  }, [disconnectStream]);

  useEffect(() => {
    return cleanup;
  }, [cleanup]);

  return {
    enabled,
    toggle,
    connectStream,
    updatePosition,
    disconnectStream,
    cleanup
  };
}

export default useSpatialAudio;

import { useState, useRef, useCallback, useEffect } from 'react';

const SPEAKER_COLORS = [
  '#a78bfa', '#34d399', '#fbbf24', '#f87171', '#38bdf8',
  '#fb923c', '#e879f9', '#22d3ee', '#a3e635', '#f472b6'
];

/**
 * Detects active speakers from WebRTC audio streams using Web Audio API.
 * Maps stream audio levels to participant names.
 */
export function useSpeakerDetection() {
  const [activeSpeaker, setActiveSpeaker] = useState(null);
  const [speakers, setSpeakers] = useState({});
  const audioContextRef = useRef(null);
  const analysersRef = useRef({});
  const intervalRef = useRef(null);
  const colorMapRef = useRef({});
  const colorIndexRef = useRef(0);

  const getColor = useCallback((name) => {
    if (!colorMapRef.current[name]) {
      colorMapRef.current[name] = SPEAKER_COLORS[colorIndexRef.current % SPEAKER_COLORS.length];
      colorIndexRef.current++;
    }
    return colorMapRef.current[name];
  }, []);

  const addStream = useCallback((userId, name, stream) => {
    if (!stream || analysersRef.current[userId]) return;

    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
    }
    const ctx = audioContextRef.current;

    try {
      const source = ctx.createMediaStreamSource(stream);
      const analyser = ctx.createAnalyser();
      analyser.fftSize = 256;
      analyser.smoothingTimeConstant = 0.5;
      source.connect(analyser);

      analysersRef.current[userId] = { analyser, name, source };
      setSpeakers(prev => ({
        ...prev,
        [userId]: { name, color: getColor(name), level: 0, speaking: false }
      }));
    } catch (e) { console.warn('Speaker detection addStream error:', e); }
  }, [getColor]);

  const addLocalStream = useCallback((name, stream) => {
    addStream('__local__', name || 'You', stream);
  }, [addStream]);

  const removeStream = useCallback((userId) => {
    if (analysersRef.current[userId]) {
      try { analysersRef.current[userId].source.disconnect(); } catch {}
      delete analysersRef.current[userId];
    }
    setSpeakers(prev => {
      const next = { ...prev };
      delete next[userId];
      return next;
    });
  }, []);

  // Poll audio levels
  useEffect(() => {
    intervalRef.current = setInterval(() => {
      const entries = Object.entries(analysersRef.current);
      if (entries.length === 0) return;

      let maxLevel = 0;
      let maxSpeaker = null;
      const updates = {};

      for (const [uid, { analyser, name }] of entries) {
        const data = new Uint8Array(analyser.frequencyBinCount);
        analyser.getByteFrequencyData(data);
        const avg = data.reduce((a, b) => a + b, 0) / data.length;
        const speaking = avg > 15; // threshold
        updates[uid] = { name, color: getColor(name), level: avg, speaking };
        if (avg > maxLevel) { maxLevel = avg; maxSpeaker = { userId: uid, name, color: getColor(name) }; }
      }

      setSpeakers(prev => ({ ...prev, ...updates }));
      setActiveSpeaker(maxLevel > 15 ? maxSpeaker : null);
    }, 200);

    return () => { if (intervalRef.current) clearInterval(intervalRef.current); };
  }, [getColor]);

  const cleanup = useCallback(() => {
    if (intervalRef.current) clearInterval(intervalRef.current);
    Object.values(analysersRef.current).forEach(({ source }) => {
      try { source.disconnect(); } catch {}
    });
    analysersRef.current = {};
    if (audioContextRef.current?.state !== 'closed') {
      try { audioContextRef.current?.close(); } catch {}
    }
    audioContextRef.current = null;
  }, []);

  return { activeSpeaker, speakers, addStream, addLocalStream, removeStream, cleanup };
}

export default useSpeakerDetection;

import { useRef, useState, useCallback } from 'react';

const API = process.env.REACT_APP_BACKEND_URL;
const WS_URL = API.replace('https://', 'wss://').replace('http://', 'ws://');

export function useWebRTC(webinarId, speakerDetection) {
  const localVideoRef = useRef(null);
  const localStreamRef = useRef(null);
  const peerConnectionsRef = useRef({});
  const remoteStreamsRef = useRef({});
  const [remoteStreams, setRemoteStreams] = useState({});
  const wsRef = useRef(null);
  const reconnectRef = useRef(null);

  const createPeerConnection = useCallback(async (remoteUserId, remoteName, createOffer) => {
    if (peerConnectionsRef.current[remoteUserId]) return;
    const pc = new RTCPeerConnection({ iceServers: [{ urls: 'stun:stun.l.google.com:19302' }] });
    peerConnectionsRef.current[remoteUserId] = pc;

    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach(track => pc.addTrack(track, localStreamRef.current));
    }

    pc.ontrack = (event) => {
      const [stream] = event.streams;
      remoteStreamsRef.current[remoteUserId] = stream;
      setRemoteStreams(prev => ({ ...prev, [remoteUserId]: { stream, name: remoteName } }));
      speakerDetection.addStream(remoteUserId, remoteName, stream);
    };

    pc.onicecandidate = (event) => {
      if (event.candidate && wsRef.current?.readyState === WebSocket.OPEN) {
        wsRef.current.send(JSON.stringify({ type: 'ice_candidate', target_user_id: remoteUserId, candidate: event.candidate.toJSON() }));
      }
    };

    if (createOffer) {
      const offer = await pc.createOffer();
      await pc.setLocalDescription(offer);
      wsRef.current?.send(JSON.stringify({ type: 'offer', target_user_id: remoteUserId, sdp: offer.sdp }));
    }
  }, [speakerDetection]);

  const handleOffer = useCallback(async (msg) => {
    await createPeerConnection(msg.user_id, msg.user_name || 'Peer', false);
    const pc = peerConnectionsRef.current[msg.user_id];
    if (!pc) return;
    await pc.setRemoteDescription(new RTCSessionDescription({ type: 'offer', sdp: msg.sdp }));
    const answer = await pc.createAnswer();
    await pc.setLocalDescription(answer);
    wsRef.current?.send(JSON.stringify({ type: 'answer', target_user_id: msg.user_id, sdp: answer.sdp }));
  }, [createPeerConnection]);

  const handleAnswer = useCallback(async (msg) => {
    const pc = peerConnectionsRef.current[msg.user_id];
    if (pc) await pc.setRemoteDescription(new RTCSessionDescription({ type: 'answer', sdp: msg.sdp }));
  }, []);

  const handleIceCandidate = useCallback(async (msg) => {
    const pc = peerConnectionsRef.current[msg.user_id];
    if (pc && msg.candidate) await pc.addIceCandidate(new RTCIceCandidate(msg.candidate));
  }, []);

  const closePeerConnection = useCallback((userId) => {
    if (peerConnectionsRef.current[userId]) {
      peerConnectionsRef.current[userId].close();
      delete peerConnectionsRef.current[userId];
    }
    delete remoteStreamsRef.current[userId];
    speakerDetection.removeStream(userId);
    setRemoteStreams(prev => { const next = { ...prev }; delete next[userId]; return next; });
  }, [speakerDetection]);

  const connectWebSocket = useCallback((info, onSlideChange, fetchRoomInfo) => {
    const token = localStorage.getItem('token');
    const wsUrl = `${WS_URL}/api/karau-meet/ws/webinar-${webinarId}?token=${token}&user_name=${encodeURIComponent(info.host_name || 'User')}&is_host=${info.my_role === 'host'}`;
    const ws = new WebSocket(wsUrl);
    wsRef.current = ws;

    ws.onopen = () => console.log('WebRTC WS connected');
    ws.onmessage = async (event) => {
      try {
        const msg = JSON.parse(event.data);
        switch (msg.type) {
          case 'user_joined': if (info.can_stream_video) createPeerConnection(msg.user_id, msg.user_name, true); break;
          case 'user_left': closePeerConnection(msg.user_id); break;
          case 'offer': await handleOffer(msg); break;
          case 'answer': await handleAnswer(msg); break;
          case 'ice_candidate': await handleIceCandidate(msg); break;
          case 'role_changed': fetchRoomInfo(); break;
          case 'slide_change': onSlideChange(msg.slide_index || 0); break;
          default: break;
        }
      } catch (e) { console.error('WS message error:', e); }
    };
    ws.onclose = () => { reconnectRef.current = setTimeout(() => connectWebSocket(info, onSlideChange, fetchRoomInfo), 3000); };
  }, [webinarId, createPeerConnection, closePeerConnection, handleOffer, handleAnswer, handleIceCandidate]);

  const startLocalMedia = useCallback(async (video, audio, noiseCancellation, hostName) => {
    try {
      let stream = await navigator.mediaDevices.getUserMedia({ video, audio });
      if (noiseCancellation?.isSupported && audio) {
        try { stream = await noiseCancellation.applyToStream(stream); } catch {}
      }
      localStreamRef.current = stream;
      if (localVideoRef.current) localVideoRef.current.srcObject = stream;
      speakerDetection.addLocalStream(hostName || 'You', stream);
      return { video, audio };
    } catch (e) {
      console.error('Media error:', e);
      return null;
    }
  }, [speakerDetection]);

  const cleanup = useCallback(() => {
    if (localStreamRef.current) localStreamRef.current.getTracks().forEach(t => t.stop());
    Object.values(peerConnectionsRef.current).forEach(pc => pc.close());
    peerConnectionsRef.current = {};
    if (wsRef.current) wsRef.current.close();
    if (reconnectRef.current) clearTimeout(reconnectRef.current);
  }, []);

  return {
    localVideoRef, localStreamRef, wsRef,
    remoteStreams, cleanup,
    connectWebSocket, startLocalMedia,
  };
}

/**
 * WebRTC Peer Connection Service Hook
 * Manages peer-to-peer connections via the signaling server.
 * Features: ICE candidate handling, reconnection, media track management.
 */
import { useRef, useCallback, useState, useEffect } from 'react';

const API = process.env.REACT_APP_BACKEND_URL;

// Default ICE servers (STUN)
const DEFAULT_ICE_SERVERS = [
  { urls: ['stun:stun.l.google.com:19302'] },
  { urls: ['stun:stun1.l.google.com:19302'] },
];

export function useWebRTCService({ meetingId, userId, userName, isHost = false }) {
  const [peers, setPeers] = useState({});       // userId -> { pc, streams, state }
  const [connected, setConnected] = useState(false);
  const [participants, setParticipants] = useState([]);
  const wsRef = useRef(null);
  const peerConnectionsRef = useRef({});
  const localStreamRef = useRef(null);
  const iceServersRef = useRef(DEFAULT_ICE_SERVERS);
  const sessionTokenRef = useRef(null);
  const reconnectRef = useRef(null);

  /**
   * Create a new peer connection for a remote user
   */
  const createPeerConnection = useCallback((remoteUserId) => {
    const config = { iceServers: iceServersRef.current };
    const pc = new RTCPeerConnection(config);

    // Add local tracks
    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach(track => {
        pc.addTrack(track, localStreamRef.current);
      });
    }

    // ICE candidate events
    pc.onicecandidate = (event) => {
      if (event.candidate && wsRef.current?.readyState === WebSocket.OPEN) {
        wsRef.current.send(JSON.stringify({
          type: 'ice_candidate',
          target: remoteUserId,
          candidate: event.candidate.toJSON()
        }));
      }
    };

    // Track events
    pc.ontrack = (event) => {
      setPeers(prev => ({
        ...prev,
        [remoteUserId]: {
          ...prev[remoteUserId],
          streams: event.streams,
          state: 'connected'
        }
      }));
    };

    // Connection state
    pc.onconnectionstatechange = () => {
      setPeers(prev => ({
        ...prev,
        [remoteUserId]: {
          ...prev[remoteUserId],
          state: pc.connectionState
        }
      }));

      if (pc.connectionState === 'failed') {
        // Attempt ICE restart
        pc.restartIce();
      }
    };

    peerConnectionsRef.current[remoteUserId] = pc;
    return pc;
  }, []);

  /**
   * Connect to signaling server
   */
  const connect = useCallback(async (localStream) => {
    localStreamRef.current = localStream;

    // Fetch ICE servers
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`${API}/api/karau/webrtc/ice-servers`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (res.ok) {
        const data = await res.json();
        if (data.ice_servers?.length) {
          iceServersRef.current = data.ice_servers;
        }
      }
    } catch {}

    // Connect WebSocket
    const wsProtocol = API.startsWith('https') ? 'wss' : 'ws';
    const wsUrl = `${wsProtocol}://${API.replace(/^https?:\/\//, '')}/api/karau-meet/ws/${meetingId}?user_id=${userId}&user_name=${encodeURIComponent(userName)}&is_host=${isHost}${sessionTokenRef.current ? `&session_token=${sessionTokenRef.current}` : ''}`;

    const ws = new WebSocket(wsUrl);
    wsRef.current = ws;

    ws.onopen = () => {
      setConnected(true);
      // Start ping interval
      const pingInterval = setInterval(() => {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(JSON.stringify({ type: 'ping' }));
        }
      }, 10000);
      ws._pingInterval = pingInterval;
    };

    ws.onmessage = async (event) => {
      const data = JSON.parse(event.data);

      switch (data.type) {
        case 'room_state':
          sessionTokenRef.current = data.session_token;
          setParticipants(data.participants || []);
          // Create offers to existing participants
          for (const participant of data.participants || []) {
            if (participant.user_id !== userId) {
              const pc = createPeerConnection(participant.user_id);
              const offer = await pc.createOffer();
              await pc.setLocalDescription(offer);
              ws.send(JSON.stringify({
                type: 'offer',
                target: participant.user_id,
                offer: pc.localDescription.toJSON()
              }));
            }
          }
          break;

        case 'user_joined':
          setParticipants(data.participants || []);
          break;

        case 'user_left':
          setParticipants(data.participants || []);
          // Cleanup peer connection
          const leavingPc = peerConnectionsRef.current[data.user_id];
          if (leavingPc) {
            leavingPc.close();
            delete peerConnectionsRef.current[data.user_id];
            setPeers(prev => {
              const next = { ...prev };
              delete next[data.user_id];
              return next;
            });
          }
          break;

        case 'offer':
          {
            let pc = peerConnectionsRef.current[data.from_user] || createPeerConnection(data.from_user);
            await pc.setRemoteDescription(new RTCSessionDescription(data.offer));
            const answer = await pc.createAnswer();
            await pc.setLocalDescription(answer);
            ws.send(JSON.stringify({
              type: 'answer',
              target: data.from_user,
              answer: pc.localDescription.toJSON()
            }));
          }
          break;

        case 'answer':
          {
            const pc = peerConnectionsRef.current[data.from_user];
            if (pc) await pc.setRemoteDescription(new RTCSessionDescription(data.answer));
          }
          break;

        case 'ice_candidate':
          {
            const pc = peerConnectionsRef.current[data.from_user];
            if (pc && data.candidate) {
              await pc.addIceCandidate(new RTCIceCandidate(data.candidate));
            }
          }
          break;

        case 'participant_state_changed':
          setParticipants(data.participants || []);
          break;

        case 'pong':
          // Heartbeat acknowledged
          break;

        default:
          break;
      }
    };

    ws.onclose = () => {
      setConnected(false);
      clearInterval(ws._pingInterval);
      // Auto-reconnect after 3s
      reconnectRef.current = setTimeout(() => {
        if (localStreamRef.current) {
          connect(localStreamRef.current);
        }
      }, 3000);
    };

    ws.onerror = () => {
      console.warn('WebRTC signaling WebSocket error');
    };
  }, [meetingId, userId, userName, isHost, createPeerConnection]);

  /**
   * Disconnect from signaling server and cleanup
   */
  const disconnect = useCallback(() => {
    if (reconnectRef.current) clearTimeout(reconnectRef.current);
    Object.values(peerConnectionsRef.current).forEach(pc => pc.close());
    peerConnectionsRef.current = {};
    setPeers({});
    if (wsRef.current) {
      clearInterval(wsRef.current._pingInterval);
      wsRef.current.close();
      wsRef.current = null;
    }
    setConnected(false);
  }, []);

  /**
   * Send media state update (mute/video toggle)
   */
  const sendMediaState = useCallback((state) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: 'state_update', state }));
    }
  }, []);

  /**
   * Replace a track (e.g., switching camera, adding screen share)
   */
  const replaceTrack = useCallback(async (newTrack, kind) => {
    for (const pc of Object.values(peerConnectionsRef.current)) {
      const sender = pc.getSenders().find(s => s.track?.kind === kind);
      if (sender) {
        await sender.replaceTrack(newTrack);
      }
    }
  }, []);

  useEffect(() => {
    return () => disconnect();
  }, [disconnect]);

  return {
    connect,
    disconnect,
    connected,
    peers,
    participants,
    sendMediaState,
    replaceTrack,
    ws: wsRef
  };
}

export default useWebRTCService;

/**
 * ATS Management Page
 * Recruiters can create application links, view invitations, and manage ATS settings
 */
import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import { useTheme } from '@/App';
import { useTranslation } from '@/utils/i18n';
import { apiClient } from '@/utils/apiClient';
import {
  Link2, Plus, Copy, Trash2, Mail, Send, Users, BarChart3,
  Calendar, Loader2, ExternalLink, Eye,
  Clock, AlertCircle
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/components/ui/tabs';

export default function ATSManagementPage() {
  const navigate = useNavigate();
  const { isDark } = useTheme();
  const { t } = useTranslation();

  const [loading, setLoading] = useState(true);
  const [links, setLinks] = useState([]);
  const [invitations, setInvitations] = useState([]);
  const [stats, setStats] = useState(null);
  const [jobs, setJobs] = useState([]);

  // Create link dialog
  const [showCreateLink, setShowCreateLink] = useState(false);
  const [creatingLink, setCreatingLink] = useState(false);
  const [newLink, setNewLink] = useState({
    job_id: '',
    expires_in_days: 30,
    max_applications: '',
    require_resume: true
  });

  // Invite dialog
  const [showInviteDialog, setShowInviteDialog] = useState(false);
  const [sendingInvite, setSendingInvite] = useState(false);
  const [inviteData, setInviteData] = useState({
    job_id: '',
    candidate_email: '',
    candidate_name: '',
    personal_message: ''
  });

  const loadData = useCallback(async () => {
    setLoading(true);
    try {
      const [linksRes, statsRes, jobsRes, invitationsRes] = await Promise.all([
        apiClient.get('/api/ats/links'),
        apiClient.get('/api/ats/stats'),
        apiClient.get('/api/recruiter/jobs'),
        apiClient.get('/api/ats/invitations')
      ]);

      setLinks(linksRes.data.links || []);
      setStats(statsRes.data);
      setJobs(jobsRes.data.jobs || []);
      setInvitations(invitationsRes.data.invitations || []);
    } catch (err) {
      toast.error('Failed to load ATS data');
      console.error(err);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const createApplicationLink = async () => {
    if (!newLink.job_id) {
      toast.error('Please select a job');
      return;
    }

    setCreatingLink(true);
    try {
      const response = await apiClient.post('/api/ats/links', {
        job_id: newLink.job_id,
        expires_in_days: newLink.expires_in_days,
        max_applications: newLink.max_applications ? parseInt(newLink.max_applications) : null,
        require_resume: newLink.require_resume
      });

      toast.success('Application link created!');
      navigator.clipboard.writeText(response.data.application_url);
      toast.info('Link copied to clipboard');

      setShowCreateLink(false);
      setNewLink({ job_id: '', expires_in_days: 30, max_applications: '', require_resume: true });
      loadData();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to create link');
    }
    setCreatingLink(false);
  };

  const deactivateLink = async (linkId) => {
    try {
      await apiClient.delete(`/api/ats/links/${linkId}`);
      toast.success('Link deactivated');
      loadData();
    } catch (err) {
      toast.error('Failed to deactivate link');
    }
  };

  const copyLink = (url) => {
    navigator.clipboard.writeText(url);
    toast.success('Link copied to clipboard!');
  };

  const sendInvitation = async () => {
    if (!inviteData.job_id || !inviteData.candidate_email) {
      toast.error('Please fill in required fields');
      return;
    }

    setSendingInvite(true);
    try {
      await apiClient.post(`/api/ats/invite?job_id=${inviteData.job_id}`, {
        candidate_email: inviteData.candidate_email,
        candidate_name: inviteData.candidate_name,
        personal_message: inviteData.personal_message
      });

      toast.success('Invitation sent!');
      setShowInviteDialog(false);
      setInviteData({ job_id: '', candidate_email: '', candidate_name: '', personal_message: '' });
      loadData();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to send invitation');
    }
    setSendingInvite(false);
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return 'N/A';
    return new Date(dateStr).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="w-8 h-8 animate-spin text-turquoise" />
      </div>
    );
  }

  return (
    <div className="p-6 md:p-8 lg:p-12 max-w-7xl mx-auto animate-fade-in" data-testid="ats-management">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-2xl md:text-3xl font-semibold text-slate-900 dark:text-slate-100">
          Applicant Tracking System
        </h1>
        <p className="text-slate-500 dark:text-slate-400 mt-1">
          Manage application links, track candidates, and send invitations
        </p>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-100 dark:bg-blue-900/30">
                <Users className="h-5 w-5 text-blue-600 dark:text-blue-400" />
              </div>
              <div>
                <p className="text-2xl font-bold">{stats?.total_applications || 0}</p>
                <p className="text-xs text-muted-foreground">Total Applications</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-green-100 dark:bg-green-900/30">
                <Clock className="h-5 w-5 text-green-600 dark:text-green-400" />
              </div>
              <div>
                <p className="text-2xl font-bold">{stats?.recent_applications || 0}</p>
                <p className="text-xs text-muted-foreground">This Week</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-purple-100 dark:bg-purple-900/30">
                <Link2 className="h-5 w-5 text-purple-600 dark:text-purple-400" />
              </div>
              <div>
                <p className="text-2xl font-bold">{stats?.active_links || 0}</p>
                <p className="text-xs text-muted-foreground">Active Links</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-amber-100 dark:bg-amber-900/30">
                <Mail className="h-5 w-5 text-amber-600 dark:text-amber-400" />
              </div>
              <div>
                <p className="text-2xl font-bold">{stats?.invitations_sent || 0}</p>
                <p className="text-xs text-muted-foreground">Invitations Sent</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Tabs */}
      <Tabs defaultValue="links" className="space-y-6">
        <TabsList>
          <TabsTrigger value="links" className="gap-2">
            <Link2 className="h-4 w-4" />
            Application Links
          </TabsTrigger>
          <TabsTrigger value="invitations" className="gap-2">
            <Mail className="h-4 w-4" />
            Invitations
          </TabsTrigger>
          <TabsTrigger value="status" className="gap-2">
            <BarChart3 className="h-4 w-4" />
            Status Breakdown
          </TabsTrigger>
        </TabsList>

        {/* Application Links Tab */}
        <TabsContent value="links" className="space-y-4">
          <div className="flex justify-between items-center">
            <h2 className="text-lg font-semibold">Shareable Application Links</h2>
            <Button onClick={() => setShowCreateLink(true)} className="gap-2">
              <Plus className="h-4 w-4" />
              Create Link
            </Button>
          </div>

          {links.length > 0 ? (
            <div className="space-y-3">
              {links.map((link) => (
                <Card key={link.id} className={!link.active ? 'opacity-60' : ''}>
                  <CardContent className="p-4">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <h3 className="font-semibold">{link.job_title}</h3>
                          {link.active ? (
                            <Badge className="bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400">
                              Active
                            </Badge>
                          ) : (
                            <Badge variant="secondary">Inactive</Badge>
                          )}
                        </div>
                        <p className="text-sm text-muted-foreground">{link.company}</p>
                        <div className="flex items-center gap-4 mt-2 text-xs text-muted-foreground">
                          <span className="flex items-center gap-1">
                            <Eye className="h-3 w-3" />
                            {link.views || 0} views
                          </span>
                          <span className="flex items-center gap-1">
                            <Users className="h-3 w-3" />
                            {link.current_applications || 0} applications
                          </span>
                          {link.expires_at && (
                            <span className="flex items-center gap-1">
                              <Calendar className="h-3 w-3" />
                              Expires {formatDate(link.expires_at)}
                            </span>
                          )}
                        </div>
                      </div>

                      <div className="flex items-center gap-2">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => copyLink(`${window.location.origin}/apply/${link.token}`)}
                          className="gap-1"
                        >
                          <Copy className="h-3 w-3" />
                          Copy
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => window.open(`/apply/${link.token}`, '_blank')}
                          className="gap-1"
                        >
                          <ExternalLink className="h-3 w-3" />
                          Preview
                        </Button>
                        {link.active && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => deactivateLink(link.id)}
                            className="text-red-500 hover:text-red-600 hover:bg-red-50"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        )}
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : (
            <Card>
              <CardContent className="py-12 text-center">
                <Link2 className="h-12 w-12 mx-auto text-slate-300 mb-4" />
                <h3 className="text-lg font-medium">No Application Links Yet</h3>
                <p className="text-sm text-muted-foreground mt-1 mb-4">
                  Create shareable links to invite candidates to apply
                </p>
                <Button onClick={() => setShowCreateLink(true)}>
                  <Plus className="h-4 w-4 mr-2" />
                  Create Your First Link
                </Button>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        {/* Invitations Tab */}
        <TabsContent value="invitations" className="space-y-4">
          <div className="flex justify-between items-center">
            <h2 className="text-lg font-semibold">Candidate Invitations</h2>
            <Button onClick={() => setShowInviteDialog(true)} className="gap-2">
              <Send className="h-4 w-4" />
              Send Invitation
            </Button>
          </div>

          {invitations.length > 0 ? (
            <div className="space-y-3">
              {invitations.map((inv) => (
                <Card key={inv.id}>
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <div className="flex items-center gap-2">
                          <h3 className="font-medium">{inv.candidate_name || inv.candidate_email}</h3>
                          <Badge variant="outline" className="text-xs">
                            {inv.status}
                          </Badge>
                        </div>
                        <p className="text-sm text-muted-foreground">{inv.candidate_email}</p>
                        <p className="text-xs text-muted-foreground mt-1">
                          Sent {formatDate(inv.sent_at)}
                        </p>
                      </div>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => window.open(inv.application_url, '_blank')}
                      >
                        <ExternalLink className="h-4 w-4" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : (
            <Card>
              <CardContent className="py-12 text-center">
                <Mail className="h-12 w-12 mx-auto text-slate-300 mb-4" />
                <h3 className="text-lg font-medium">No Invitations Sent</h3>
                <p className="text-sm text-muted-foreground mt-1 mb-4">
                  Send personalized invitations to candidates
                </p>
                <Button onClick={() => setShowInviteDialog(true)}>
                  <Send className="h-4 w-4 mr-2" />
                  Send First Invitation
                </Button>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        {/* Status Breakdown Tab */}
        <TabsContent value="status" className="space-y-4">
          <h2 className="text-lg font-semibold">Applications by Status</h2>

          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {stats?.available_statuses && Object.entries(stats.available_statuses).map(([status, config]) => (
              <Card key={status}>
                <CardContent className="p-4 text-center">
                  <div className="text-3xl mb-2">{config.emoji}</div>
                  <p className="font-medium">{config.label}</p>
                  <p className="text-2xl font-bold text-turquoise">
                    {stats.by_status?.[status] || 0}
                  </p>
                </CardContent>
              </Card>
            ))}
          </div>
        </TabsContent>
      </Tabs>

      {/* Create Link Dialog */}
      <Dialog open={showCreateLink} onOpenChange={setShowCreateLink}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create Application Link</DialogTitle>
            <DialogDescription>
              Generate a shareable link for candidates to apply
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div>
              <Label>Select Job *</Label>
              <Select
                value={newLink.job_id}
                onValueChange={(v) => setNewLink({ ...newLink, job_id: v })}
              >
                <SelectTrigger>
                  <SelectValue placeholder={t("atsManagement.selectJobPlaceholder")} />
                </SelectTrigger>
                <SelectContent>
                  {jobs.map((job) => (
                    <SelectItem key={job.id} value={job.id}>
                      {job.title} - {job.company}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Expires In (Days)</Label>
                <Input
                  type="number"
                  value={newLink.expires_in_days}
                  onChange={(e) => setNewLink({ ...newLink, expires_in_days: parseInt(e.target.value) || 30 })}
                />
              </div>
              <div>
                <Label>Max Applications</Label>
                <Input
                  type="number"
                  placeholder={t("atsManagement.maxApplicantsPlaceholder")}
                  value={newLink.max_applications}
                  onChange={(e) => setNewLink({ ...newLink, max_applications: e.target.value })}
                />
              </div>
            </div>

            <div className="flex items-center justify-between">
              <Label>Require Resume</Label>
              <Switch
                checked={newLink.require_resume}
                onCheckedChange={(v) => setNewLink({ ...newLink, require_resume: v })}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowCreateLink(false)}>
              Cancel
            </Button>
            <Button onClick={createApplicationLink} disabled={creatingLink}>
              {creatingLink ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin mr-2" />
                  Creating...
                </>
              ) : (
                <>
                  <Link2 className="h-4 w-4 mr-2" />
                  Create Link
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Send Invitation Dialog */}
      <Dialog open={showInviteDialog} onOpenChange={setShowInviteDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Invite Candidate to Apply</DialogTitle>
            <DialogDescription>
              Send a personalized invitation email with application link
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div>
              <Label>Select Job *</Label>
              <Select
                value={inviteData.job_id}
                onValueChange={(v) => setInviteData({ ...inviteData, job_id: v })}
              >
                <SelectTrigger>
                  <SelectValue placeholder={t("atsManagement.selectJobPlaceholder")} />
                </SelectTrigger>
                <SelectContent>
                  {jobs.map((job) => (
                    <SelectItem key={job.id} value={job.id}>
                      {job.title} - {job.company}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label>Candidate Email *</Label>
              <Input
                type="email"
                placeholder={t("atsManagement.candidateEmailPlaceholder")}
                value={inviteData.candidate_email}
                onChange={(e) => setInviteData({ ...inviteData, candidate_email: e.target.value })}
              />
            </div>

            <div>
              <Label>Candidate Name</Label>
              <Input
                placeholder={t("atsManagement.candidateNamePlaceholder")}
                value={inviteData.candidate_name}
                onChange={(e) => setInviteData({ ...inviteData, candidate_name: e.target.value })}
              />
            </div>

            <div>
              <Label>Personal Message</Label>
              <Textarea
                placeholder={t("atsManagement.inviteNotePlaceholder")}
                rows={3}
                value={inviteData.personal_message}
                onChange={(e) => setInviteData({ ...inviteData, personal_message: e.target.value })}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowInviteDialog(false)}>
              Cancel
            </Button>
            <Button onClick={sendInvitation} disabled={sendingInvite}>
              {sendingInvite ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin mr-2" />
                  Sending...
                </>
              ) : (
                <>
                  <Send className="h-4 w-4 mr-2" />
                  Send Invitation
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Admin Dashboard - Central hub for admin functions
 * Only accessible to users with admin role
 * Feature: 3 View Options - Admin, Job Seeker, Recruiter
 */
import React, { useState, useEffect } from 'react';
import { useTranslation } from "@/utils/i18n";
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import {
  Shield,
  Bot,
  BarChart3,
  Users,
  Settings,
  Database,
  Activity,
  Bell,
  Calendar,
  Zap,
  RefreshCw,
  ChevronRight,
  Lock,
  Unlock,
  Crown,
  TrendingUp,
  AlertTriangle,
  CheckCircle,
  Brain,
  Gauge,
  History,
  Target,
  Globe,
  Languages,
  Briefcase,
  UserCircle,
  Eye
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../components/ui/card';
import { Button } from '../components/ui/button';
import { Badge } from '../components/ui/badge';
import { Progress } from '../components/ui/progress';
import { apiClient } from '@/utils/apiClient';

// View Mode Selector Component
const ViewModeSelector = ({ currentView, onViewChange }) => {
  const views = [
    { id: 'admin', label: 'Admin View', icon: Shield, description: 'Full administrative access' },
    { id: 'recruiter', label: 'Recruiter View', icon: Briefcase, description: 'See platform as a recruiter' },
    { id: 'jobseeker', label: 'Job Seeker View', icon: UserCircle, description: 'See platform as a job seeker' }
  ];

  return (
    <Card className="mb-6 border-2 border-dashed border-turquoise/30">
      <CardHeader className="pb-3">
        <CardTitle className="text-lg flex items-center gap-2">
          <Eye className="h-5 w-5 text-turquoise" />
          Platform View Mode
        </CardTitle>
        <CardDescription>Switch between different user perspectives to test the platform experience</CardDescription>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          {views.map((view) => (
            <button
              key={view.id}
              onClick={() => onViewChange(view.id)}
              className={`p-4 rounded-xl border-2 text-left transition-all ${
                currentView === view.id
                  ? 'border-turquoise bg-turquoise/10 shadow-md'
                  : 'border-border hover:border-turquoise/50 hover:bg-muted/50'
              }`}
              data-testid={`view-mode-${view.id}`}
            >
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${currentView === view.id ? 'bg-turquoise text-white' : 'bg-muted'}`}>
                  <view.icon className="h-5 w-5" />
                </div>
                <div>
                  <p className="font-semibold">{view.label}</p>
                  <p className="text-xs text-muted-foreground">{view.description}</p>
                </div>
              </div>
              {currentView === view.id && (
                <Badge className="mt-2 bg-turquoise/20 text-turquoise text-xs">Active</Badge>
              )}
            </button>
          ))}
        </div>
      </CardContent>
    </Card>
  );
};

// Admin Module Card
const AdminModuleCard = ({ title, description, icon: Icon, path, status, stats, onClick }) => (
  <Card 
    className="hover:shadow-lg transition-all cursor-pointer hover:border-turquoise/50 group"
    onClick={onClick}
  >
    <CardContent className="p-6">
      <div className="flex items-start justify-between">
        <div className="flex items-center gap-4">
          <div className="p-3 rounded-xl bg-turquoise/10 text-turquoise group-hover:bg-turquoise group-hover:text-white transition-colors">
            <Icon className="h-6 w-6" />
          </div>
          <div>
            <h3 className="font-semibold text-lg flex items-center gap-2">
              {title}
              {status === "active" && <Badge className="bg-green-500/10 text-green-500 text-xs">Active</Badge>}
              {status === "warning" && <Badge className="bg-yellow-500/10 text-yellow-500 text-xs">Warning</Badge>}
            </h3>
            <p className="text-sm text-muted-foreground">{description}</p>
          </div>
        </div>
        <ChevronRight className="h-5 w-5 text-muted-foreground group-hover:text-turquoise transition-colors" />
      </div>
      {stats && (
        <div className="mt-4 pt-4 border-t border-border/50 grid grid-cols-3 gap-4">
          {Object.entries(stats).map(([key, value]) => (
            <div key={key} className="text-center">
              <p className="text-xl font-bold">{value}</p>
              <p className="text-xs text-muted-foreground capitalize">{key.replace(/_/g, ' ')}</p>
            </div>
          ))}
        </div>
      )}
    </CardContent>
  </Card>
);

// Quick Stat Card
const QuickStatCard = ({ title, value, icon: Icon, trend, color = "turquoise" }) => {
  const colorClasses = {
    turquoise: "bg-turquoise/10 text-turquoise",
    green: "bg-green-500/10 text-green-500",
    yellow: "bg-yellow-500/10 text-yellow-500",
    red: "bg-red-500/10 text-red-500",
    purple: "bg-purple-500/10 text-purple-500"
  };

  return (
    <Card>
      <CardContent className="p-4">
        <div className="flex items-center justify-between">
          <div className={`p-2 rounded-lg ${colorClasses[color]}`}>
            <Icon className="h-5 w-5" />
          </div>
          {trend && (
            <Badge variant="outline" className={trend > 0 ? "text-green-500" : "text-red-500"}>
              {trend > 0 ? "+" : ""}{trend}%
            </Badge>
          )}
        </div>
        <p className="text-2xl font-bold mt-3">{value}</p>
        <p className="text-sm text-muted-foreground">{title}</p>
      </CardContent>
    </Card>
  );
};

