          status === 'Offer' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300' :
          'bg-rose-100 text-rose-700 dark:bg-rose-900/30 dark:text-rose-300'
        }`}>
          {status}
        </Badge>
      </div>
    </div>
  );
};

