export default function DragonAutomatorPage() {
  const [loading, setLoading] = useState(true);
  const [running, setRunning] = useState(false);
  const [health, setHealth] = useState(null);
  const [improvements, setImprovements] = useState([]);
  const [updates, setUpdates] = useState([]);
  const [version, setVersion] = useState(null);
  const [lastReport, setLastReport] = useState(null);

  // Helper to add delay between requests to prevent rate limiting
  const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

  const loadData = async () => {
    setLoading(true);
    try {
      // Stagger API calls to prevent rate limiting (thundering herd)
      // Load health first (critical data)
      try {
        const healthRes = await apiClient.get('/api/dragon/automator/health');
        setHealth(healthRes.data);
      } catch (err) {
        console.error('Health fetch failed:', err);
      }

      await delay(150); // Small delay between requests

      // Load improvements
      try {
        const improvementsRes = await apiClient.get('/api/dragon/automator/improvements');
        setImprovements(improvementsRes.data.suggestions || []);
      } catch (err) {
        console.error('Improvements fetch failed:', err);
      }

      await delay(150);

      // Load updates
      try {
        const updatesRes = await apiClient.get('/api/dragon/automator/updates');
        setUpdates(updatesRes.data.updates || []);
      } catch (err) {
        console.error('Updates fetch failed:', err);
      }

      await delay(150);

      // Load version info
      try {
        const versionRes = await apiClient.get('/api/dragon/automator/version');
        setVersion(versionRes.data);
      } catch (err) {
        console.error('Version fetch failed:', err);
      }
    } catch (error) {
      console.error('Failed to load automator data:', error);
      toast.error('Failed to load automator data');
    } finally {
      setLoading(false);
    }
  };

  const runFullAnalysis = async () => {
    setRunning(true);
    try {
      const response = await apiClient.post('/api/dragon/automator/analyze-and-fix');
      setLastReport(response.data.report);
      toast.success(`Analysis complete! ${response.data.report?.phases?.auto_fix?.fixes_applied || 0} fixes applied`);
      await loadData();
    } catch (error) {
      console.error('Analysis failed:', error);
      toast.error(error.response?.data?.detail || 'Analysis failed');
    } finally {
      setRunning(false);
    }
  };

  const applyAutoFixes = async () => {
    try {
      const response = await apiClient.post('/api/dragon/automator/auto-fix');
      toast.success(`Applied ${response.data.fixes_applied} fixes`);
      await loadData();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Auto-fix failed');
    }
  };

  const implementImprovement = async (index) => {
    try {
      const response = await apiClient.post(`/api/dragon/automator/improvements/${index}/implement`);
      if (response.data.success) {
        toast.success('Improvement implemented successfully');
        await loadData();
      } else {
        toast.info(response.data.reason || 'Manual implementation required');
      }
    } catch (error) {
      toast.error('Failed to implement improvement');
    }
  };

  const markUpdatesRead = async () => {
    try {
      await apiClient.post('/api/dragon/automator/updates/mark-read');
      setUpdates([]);
      toast.success('Updates marked as read');
    } catch (error) {
      toast.error('Failed to mark updates');
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <Bot className="h-16 w-16 animate-pulse text-turquoise mx-auto mb-4" />
          <p className="text-muted-foreground">KARAU DRAGON Automator initializing...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6" data-testid="dragon-automator-page">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-3">
            <Bot className="h-8 w-8 text-turquoise" />
            KARAU DRAGON AI Automator
          </h1>
          <p className="text-muted-foreground mt-1">
            Automatic diagnostics, fixes, improvements, and updates
          </p>
        </div>

        <div className="flex items-center gap-3">
          <Badge variant="outline" className="text-lg px-3 py-1">
            v{health?.version || version?.current_version || '2.3.0'}
          </Badge>
          <Button variant="outline" onClick={loadData}>
            <RefreshCw className="h-4 w-4 mr-2" />
            Refresh
          </Button>
          <Button 
            onClick={runFullAnalysis} 
            disabled={running}
            className="bg-turquoise hover:bg-turquoise/90"
          >
            {running ? (
              <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
            ) : (
              <Zap className="h-4 w-4 mr-2" />
            )}
            Run Full Analysis
          </Button>
        </div>
      </div>

      {/* Update Notifications */}
      {updates.length > 0 && (
        <Card className="border-turquoise/30 bg-turquoise/5">
          <CardHeader className="pb-2">
            <div className="flex items-center justify-between">
              <CardTitle className="flex items-center gap-2">
                <Bell className="h-5 w-5 text-turquoise" />
                Pending Updates ({updates.length})
              </CardTitle>
              <Button variant="ghost" size="sm" onClick={markUpdatesRead}>
                Mark all read
              </Button>
            </div>
          </CardHeader>
          <CardContent className="space-y-3">
            {updates.slice(0, 2).map((update, idx) => (
              <UpdateNotification key={idx} update={update} onMarkRead={markUpdatesRead} />
            ))}
          </CardContent>
        </Card>
      )}

      {/* Health Overview */}
      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Health Gauge */}
        <Card className="lg:col-span-1">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Activity className="h-5 w-5 text-turquoise" />
              System Health
            </CardTitle>
          </CardHeader>
          <CardContent>
            <HealthGauge score={health?.health_score || 0} />
            <div className="mt-4 text-center">
              <StatusBadge status={health?.overall_status} />
              <p className="text-xs text-muted-foreground mt-2">
                Last checked: {new Date(health?.timestamp).toLocaleTimeString()}
              </p>
            </div>
          </CardContent>
        </Card>

        {/* Quick Stats */}
        <Card className="lg:col-span-3">
          <CardHeader>
            <CardTitle>Quick Actions</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="text-center p-4 rounded-lg bg-muted/50">
                <AlertTriangle className="h-8 w-8 mx-auto mb-2 text-yellow-500" />
                <p className="text-2xl font-bold">{health?.total_issues || 0}</p>
                <p className="text-sm text-muted-foreground">Total Issues</p>
              </div>
              <div className="text-center p-4 rounded-lg bg-muted/50">
                <Wrench className="h-8 w-8 mx-auto mb-2 text-blue-500" />
                <p className="text-2xl font-bold">
                  {health?.issues?.filter(i => i.auto_fixable).length || 0}
                </p>
                <p className="text-sm text-muted-foreground">Auto-Fixable</p>
              </div>
              <div className="text-center p-4 rounded-lg bg-muted/50">
                <Lightbulb className="h-8 w-8 mx-auto mb-2 text-yellow-500" />
                <p className="text-2xl font-bold">{improvements.length}</p>
                <p className="text-sm text-muted-foreground">Improvements</p>
              </div>
              <div className="text-center p-4 rounded-lg bg-muted/50">
                <Shield className="h-8 w-8 mx-auto mb-2 text-green-500" />
                <p className="text-2xl font-bold">{version?.changelog?.length || 0}</p>
                <p className="text-sm text-muted-foreground">Updates Released</p>
              </div>
            </div>

            {health?.total_issues > 0 && (
              <Button className="w-full mt-4" onClick={applyAutoFixes}>
                <Wrench className="h-4 w-4 mr-2" />
                Apply Auto-Fixes ({health?.issues?.filter(i => i.auto_fixable).length || 0} available)
              </Button>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Tabs for Details */}
      <Tabs defaultValue="diagnostics" className="w-full">
        <TabsList className="grid w-full grid-cols-7">
          <TabsTrigger value="diagnostics">Diagnostics</TabsTrigger>
          <TabsTrigger value="improvements">Improvements</TabsTrigger>
          <TabsTrigger value="translation-qa" className="flex items-center gap-1">
            <Languages className="w-3 h-3" />
            Translation QA
          </TabsTrigger>
          <TabsTrigger value="capa" className="flex items-center gap-1">
            <Shield className="w-3 h-3" />
            CAPA
          </TabsTrigger>
          <TabsTrigger value="ai-qa" className="flex items-center gap-1">
            <Bot className="w-3 h-3" />
            AI QA
          </TabsTrigger>
          <TabsTrigger value="changelog">Changelog</TabsTrigger>
          <TabsTrigger value="reports">Reports</TabsTrigger>
        </TabsList>

        <TabsContent value="diagnostics" className="mt-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <DiagnosticCard
              title="Database"
              icon={Database}
              status={health?.diagnostics?.database?.status}
              metrics={health?.diagnostics?.database?.metrics}
              issues={health?.diagnostics?.database?.issues}
            />
            <DiagnosticCard
              title="API Services"
              icon={Zap}
              status={health?.diagnostics?.api?.status}
              metrics={health?.diagnostics?.api?.metrics}
              issues={health?.diagnostics?.api?.issues}
            />
            <DiagnosticCard
              title="AI Services"
              icon={Bot}
              status={health?.diagnostics?.ai_services?.status}
              metrics={health?.diagnostics?.ai_services?.metrics}
              issues={health?.diagnostics?.ai_services?.issues}
            />
            <DiagnosticCard
              title="Performance"
              icon={Cpu}
              status={health?.diagnostics?.performance?.status}
              metrics={health?.diagnostics?.performance?.metrics}
              issues={health?.diagnostics?.performance?.issues}
            />
          </div>
        </TabsContent>

        <TabsContent value="improvements" className="mt-4 space-y-4">
          {improvements.length > 0 ? (
            improvements.map((improvement, idx) => (
              <ImprovementCard
                key={idx}
                improvement={improvement}
                index={idx}
                onImplement={implementImprovement}
              />
            ))
          ) : (
            <Card>
              <CardContent className="py-12 text-center">
                <CheckCircle className="h-12 w-12 mx-auto mb-4 text-green-500" />
                <p className="text-lg font-medium">No improvements suggested</p>
                <p className="text-muted-foreground">Your system is running optimally!</p>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        {/* Translation QA Tab */}
        <TabsContent value="translation-qa" className="mt-4">
          <TranslationQADashboard />
        </TabsContent>

        {/* CAPA Tab */}
        <TabsContent value="capa" className="mt-4">
          <CAPADashboard />
        </TabsContent>

        {/* AI QA Compliance Tab */}
        <TabsContent value="ai-qa" className="mt-4">
          <AIQADashboard />
        </TabsContent>

        <TabsContent value="changelog" className="mt-4">
          <Card>
            <CardHeader>
              <CardTitle>Version History</CardTitle>
            </CardHeader>
            <CardContent>
              {version?.changelog?.length > 0 ? (
                <div className="space-y-4">
                  {version.changelog.map((entry, idx) => (
                    <div key={idx} className="border-l-2 border-turquoise pl-4 py-2">
                      <div className="flex items-center gap-2 mb-2">
                        <Badge variant="outline" className="bg-turquoise/10 text-turquoise">
                          v{entry.version}
                        </Badge>
                        <Badge variant="outline">{entry.type}</Badge>
                        <span className="text-sm text-muted-foreground">
                          {new Date(entry.release_date).toLocaleDateString()}
                        </span>
                      </div>
                      <ul className="space-y-1">
                        {entry.changes?.map((change, cIdx) => (
                          <li key={cIdx} className="text-sm flex items-center gap-2">
                            <ChevronRight className="h-3 w-3 text-turquoise" />
                            {change}
                          </li>
                        ))}
                      </ul>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-center text-muted-foreground py-8">
                  No version history available
                </p>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="reports" className="mt-4">
          {lastReport ? (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Clock className="h-5 w-5" />
                  Latest Analysis Report
                </CardTitle>
                <CardDescription>
                  Generated: {new Date(lastReport.timestamp).toLocaleString()}
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-3 gap-4 mb-6">
                  <div className="text-center p-4 bg-muted/50 rounded-lg">
                    <p className="text-3xl font-bold">{lastReport.phases?.diagnostics?.total_issues || 0}</p>
                    <p className="text-sm text-muted-foreground">Issues Found</p>
                  </div>
                  <div className="text-center p-4 bg-muted/50 rounded-lg">
                    <p className="text-3xl font-bold text-green-500">
                      {lastReport.phases?.auto_fix?.fixes_applied || 0}
                    </p>
                    <p className="text-sm text-muted-foreground">Fixes Applied</p>
                  </div>
                  <div className="text-center p-4 bg-muted/50 rounded-lg">
                    <p className="text-3xl font-bold text-yellow-500">
                      {lastReport.phases?.improvements?.suggestions || 0}
                    </p>
                    <p className="text-sm text-muted-foreground">Suggestions</p>
                  </div>
                </div>

                <div className="space-y-2">
                  <h4 className="font-semibold">Summary</h4>
                  <div className="flex items-center gap-4">
                    <span className="text-muted-foreground">Health Before:</span>
                    <StatusBadge status={lastReport.summary?.health_before} />
                    <ChevronRight className="h-4 w-4" />
                    <span className="text-muted-foreground">After:</span>
                    <StatusBadge status={lastReport.summary?.health_after} />
                  </div>
                </div>
              </CardContent>
            </Card>
          ) : (
            <Card>
              <CardContent className="py-12 text-center">
                <Bot className="h-12 w-12 mx-auto mb-4 text-muted-foreground" />
                <p className="text-lg font-medium">No reports yet</p>
                <p className="text-muted-foreground mb-4">Run a full analysis to generate a report</p>
                <Button onClick={runFullAnalysis} disabled={running}>
                  <Zap className="h-4 w-4 mr-2" />
                  Run Analysis
                </Button>
              </CardContent>
            </Card>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { toast } from "sonner";
import { useTheme } from "@/App";
import { 
  ShieldCheck, Upload, Camera, User, Building, BadgeCheck,
  Loader2, CheckCircle2, AlertCircle, Clock, Star,
  FileText, Globe, Link as LinkIcon, ChevronRight, X, RefreshCw
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useTranslation } from "@/utils/i18n";
import { apiClient } from "@/utils/apiClient";

const IDVerificationPage = ({ user }) => {
  const { isDark } = useTheme();
  const { t } = useTranslation();
  const fileInputRef = useRef(null);

  const [verificationStatus, setVerificationStatus] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [step, setStep] = useState(1);
  const [isUploading, setIsUploading] = useState(false);

  // ID Verification Form
  const [documentType, setDocumentType] = useState('government_id');
  const [fullName, setFullName] = useState(user?.name || '');
  const [dateOfBirth, setDateOfBirth] = useState('');
  const [country, setCountry] = useState('US');
  const [uploadedDocs, setUploadedDocs] = useState({ front: null, selfie: null });

  // Company Verification Form
  const [companyName, setCompanyName] = useState('');
  const [companyWebsite, setCompanyWebsite] = useState('');
  const [companyEmailDomain, setCompanyEmailDomain] = useState('');
  const [roleAtCompany, setRoleAtCompany] = useState('');
  const [linkedinUrl, setLinkedinUrl] = useState('');

  useEffect(() => {
    fetchVerificationStatus();
  }, []);

  const fetchVerificationStatus = async () => {
    setIsLoading(true);
    try {
      const response = await apiClient.get(`/api/id-verification/status`);
      setVerificationStatus(response.data);

      // Set step based on status
      if (response.data.status === 'approved') {
        setStep(4);
      } else if (response.data.status === 'pending') {
        setStep(3);
      }
    } catch (e) {
      console.error("Failed to fetch verification status:", e);
    }
    setIsLoading(false);
  };

  const startVerification = async () => {
    try {
      await apiClient.post(`/api/id-verification/request-verification`, {
        document_type: documentType,
        full_name: fullName,
        date_of_birth: dateOfBirth,
        country
      });

      toast.success(t("verification.requestCreated") || "Verification request created");
      setStep(2);
    } catch (e) {
      toast.error(e.data?.detail || t("verification.startFailed") || "Failed to start verification");
    }
  };

  const uploadDocument = async (file, side) => {
    if (!file) return;

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('document_side', side);

      const response = await apiClient.post(
        `/api/id-verification/upload-document`,
        formData,
        { headers: { 'Content-Type': 'multipart/form-data' } }
      );

      setUploadedDocs(prev => ({ ...prev, [side]: file.name }));
      toast.success(`${side} ${t("verification.documentUploaded") || "document uploaded"}`);

      if (response.data.next_step === 'processing') {
        setStep(3);
        fetchVerificationStatus();
      }
    } catch (e) {
      toast.error(e.data?.detail || t("verification.uploadFailed") || "Upload failed");
    }
    setIsUploading(false);
  };

  const verifyCompany = async () => {
    try {
      const response = await apiClient.post(`/api/id-verification/verify-company`, {
        company_name: companyName,
        company_website: companyWebsite,
        company_email_domain: companyEmailDomain,
        role_at_company: roleAtCompany,
        linkedin_url: linkedinUrl
      });

      if (response.data.status === 'approved') {
        toast.success(t("verification.companyVerified") || "Company verified automatically!");
      } else {
        toast.info(t("verification.pendingReview") || "Company verification pending review");
      }

      fetchVerificationStatus();
    } catch (e) {
      toast.error(e.data?.detail || t("verification.companyFailed") || "Company verification failed");
    }
  };

  const getStatusBadge = () => {
    if (!verificationStatus) return null;

    const { status, verification_level } = verificationStatus;

    const configs = {
      approved: { color: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400', icon: CheckCircle2, text: 'Verified' },
      pending: { color: 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400', icon: Clock, text: 'Pending' },
      rejected: { color: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400', icon: AlertCircle, text: 'Rejected' },
      unverified: { color: 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-400', icon: ShieldCheck, text: 'Unverified' }
    };

    const config = configs[status] || configs.unverified;
    const Icon = config.icon;

    return (
      <Badge className={`${config.color} flex items-center gap-1`}>
        <Icon className="w-3 h-3" />
        {config.text} (Level {verification_level})
      </Badge>
    );
  };

  const isRecruiter = user?.role === 'recruiter';

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="w-8 h-8 animate-spin text-turquoise" />
      </div>
    );
  }

  return (
    <div className="p-6 md:p-8 lg:p-12 max-w-4xl mx-auto" data-testid="id-verification-page">
      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-semibold text-slate-900 dark:text-slate-100" style={{ fontFamily: 'IBM Plex Sans' }}>
            Identity Verification
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mt-1">
            {isRecruiter ? "Verify your identity to unlock premium recruiter features" : "Verify your identity for trusted interactions"}
          </p>
        </div>
        {getStatusBadge()}
      </div>

      {/* Verification Levels Info */}
      <Card className="mb-8">
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Star className="w-5 h-5 text-amber-500" />
            Verification Levels
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid sm:grid-cols-4 gap-4">
            {[
              { level: 0, name: 'Unverified', icon: User, features: ['Basic search'] },
              { level: 1, name: 'Email Verified', icon: FileText, features: ['Job posting'] },
              { level: 2, name: 'Company Verified', icon: Building, features: ['Contact candidates'] },
              { level: 3, name: 'ID Verified', icon: BadgeCheck, features: ['Premium features'] }
            ].map((lvl) => {
              const Icon = lvl.icon;
              const isActive = verificationStatus?.verification_level >= lvl.level;

              return (
                <div 
                  key={lvl.level}
                  className={`p-4 rounded-lg border-2 text-center transition-all ${
                    isActive 
                      ? 'border-turquoise bg-turquoise/5 dark:bg-turquoise/10' 
                      : 'border-slate-200 dark:border-slate-700'
                  }`}
                >
                  <div className={`w-12 h-12 rounded-full mx-auto mb-3 flex items-center justify-center ${
                    isActive ? 'bg-turquoise text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'
                  }`}>
                    <Icon className="w-6 h-6" />
                  </div>
                  <p className={`font-medium text-sm ${isActive ? 'text-turquoise' : 'text-slate-500'}`}>
                    Level {lvl.level}
                  </p>
                  <p className="font-semibold text-slate-900 dark:text-slate-100 mb-2">
                    {lvl.name}
                  </p>
                  <p className="text-xs text-slate-500 dark:text-slate-400">
                    {lvl.features[0]}
                  </p>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Verification Flow */}
      {verificationStatus?.status !== 'approved' && (
        <div className="space-y-6">
          {/* Company Verification (for recruiters) */}
          {isRecruiter && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Building className="w-5 h-5 text-blue-500" />
                  Company Verification
                </CardTitle>
                <CardDescription>
                  Verify your company affiliation to reach Level 2
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid sm:grid-cols-2 gap-4">
                  <div>
                    <Label>Company Name *</Label>
                    <Input 
                      value={companyName}
                      onChange={(e) => setCompanyName(e.target.value)}
                      placeholder={t("idVerification.companyPlaceholder")}
                      data-testid="company-name-input"
                    />
                  </div>
                  <div>
                    <Label>Company Website</Label>
                    <Input 
                      value={companyWebsite}
                      onChange={(e) => setCompanyWebsite(e.target.value)}
                      placeholder={t("idVerification.websitePlaceholder")}
                    />
                  </div>
                  <div>
                    <Label>Company Email Domain *</Label>
                    <Input 
                      value={companyEmailDomain}
                      onChange={(e) => setCompanyEmailDomain(e.target.value)}
                      placeholder={t("idVerification.domainPlaceholder")}
                      data-testid="company-domain-input"
                    />
                    <p className="text-xs text-slate-500 mt-1">
                      Should match your email domain for auto-verification
                    </p>
                  </div>
                  <div>
                    <Label>Your Role *</Label>
                    <Input 
                      value={roleAtCompany}
                      onChange={(e) => setRoleAtCompany(e.target.value)}
                      placeholder={t("idVerification.jobTitlePlaceholder")}
                    />
                  </div>
                  <div className="sm:col-span-2">
                    <Label>LinkedIn Profile URL</Label>
                    <Input 
                      value={linkedinUrl}
                      onChange={(e) => setLinkedinUrl(e.target.value)}
                      placeholder={t("idVerification.linkedinPlaceholder")}
                    />
                  </div>
                </div>

                <Button 
                  onClick={verifyCompany}
                  disabled={!companyName || !companyEmailDomain || !roleAtCompany}
                  className="w-full bg-blue-500 hover:bg-blue-600"
                  data-testid="verify-company-btn"
                >
                  <Building className="w-4 h-4 mr-2" />
                  Verify Company Affiliation
                </Button>
              </CardContent>
            </Card>
          )}

          {/* ID Verification */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <ShieldCheck className="w-5 h-5 text-turquoise" />
                Government ID Verification
              </CardTitle>
              <CardDescription>
                Upload your government ID to reach Level 3 (highest trust)
              </CardDescription>
            </CardHeader>
            <CardContent>
              {/* Progress Steps */}
              <div className="flex items-center mb-8">
                {['Personal Info', 'Upload Documents', 'Processing', 'Verified'].map((label, i) => (
                  <div key={label} className="flex-1 flex items-center">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
                      step > i + 1 ? 'bg-turquoise text-white' : 
                      step === i + 1 ? 'bg-turquoise/20 text-turquoise border-2 border-turquoise' :
                      'bg-slate-100 dark:bg-slate-800 text-slate-400'
                    }`}>
