                  {locationType === "remote" && <Laptop className="w-3 h-3" />}
                  {locationType === "hybrid" && <Home className="w-3 h-3" />}
                  {locationType === "onsite" && <Building className="w-3 h-3" />}
                  {LOCATION_TYPES.find(t => t.value === locationType)?.label}
                  <button 
                    onClick={() => setLocationType("all")}
                    className="ml-1 hover:text-red-500"
                  >×</button>
                </Badge>
              )}
              {country !== "any" && (
                <Badge variant="secondary" className="flex items-center gap-1">
                  <Globe className="w-3 h-3" />
                  {country}
                  <button 
                    onClick={() => { setCountry("any"); setCity("any"); }}
                    className="ml-1 hover:text-red-500"
                  >×</button>
                </Badge>
              )}
              {city !== "any" && (
                <Badge variant="secondary" className="flex items-center gap-1">
                  <MapPin className="w-3 h-3" />
                  {city}
                  <button 
                    onClick={() => setCity("any")}
                    className="ml-1 hover:text-red-500"
                  >×</button>
                </Badge>
              )}
              <Button 
                variant="ghost" 
                size="sm" 
                onClick={() => { setCountry("any"); setCity("any"); setLocationType("all"); }}
                className="text-xs text-red-500 hover:text-red-700"
              >
                Clear all
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Life Sciences & Engineering Taxonomy Filters */}
      <TaxonomyJobFilters 
        onFiltersChange={setTaxonomyFilters}
        initialFilters={taxonomyFilters}
      />

      {/* AI Deep Search */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-2 text-sm text-slate-500">
          <Filter className="w-4 h-4" />
          {jobs.length} {t("jobs.jobsFound") || "jobs found"}
        </div>
        <Button 
          variant="outline" 
          onClick={deepSearch}
          disabled={deepSearching}
          className="gap-2 border-violet-400 bg-violet-600 text-white hover:bg-violet-700 hover:text-white font-semibold shadow-md"
          data-testid="deep-search-btn"
        >
          {deepSearching ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <Sparkles className="w-4 h-4 text-white" />
          )}
          {t("jobs.aiDeepSearch") || "AI Deep Search"}
        </Button>
      </div>

      {/* Search Stats */}
      {searchStats && (
        <Card className="mb-6 bg-violet-50 dark:bg-violet-900/20 border-violet-200">
          <CardContent className="p-4">
            <div className="flex items-center gap-4">
              <Sparkles className="w-5 h-5 text-violet-500" />
              <div>
                <p className="font-medium text-violet-700 dark:text-violet-300">
                  {t("jobs.deepSearchResults") || "AI Deep Search Results"}
                </p>
                <p className="text-sm text-violet-600 dark:text-violet-400">
                  {t("jobs.foundJobs", { count: searchStats.total }) || `Found ${searchStats.total} jobs`} • {searchStats.queries} {t("jobs.queriesUsed") || "queries used"} • {searchStats.strategy}
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Quick Presets */}
      {presets.presets?.length > 0 && (
        <div className="flex flex-wrap gap-2 mb-6">
          {presets.presets.map((preset, idx) => {
            const IconComponent = PresetIcons[preset.icon] || FileSearch;
            return (
              <Badge
                key={idx}
                variant="outline"
                className="cursor-pointer hover:bg-turquoise/10 hover:border-turquoise transition-colors py-2 px-3"
                onClick={() => handlePresetClick(preset.query)}
              >
                <IconComponent className="w-4 h-4 mr-2" />
                {preset.name}
              </Badge>
            );
          })}
        </div>
      )}

      {/* Job Results */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-turquoise" />
        </div>
      ) : jobs.length === 0 ? (
        <div className="empty-state text-center py-12">
          <Search className="w-12 h-12 text-slate-300 mb-4 mx-auto" />
          <h3 className="text-lg font-medium text-slate-700 dark:text-slate-300 mb-2">{t("jobs.noJobsFound") || "No jobs found"}</h3>
          <p className="text-slate-500 mb-4">{t("jobs.tryDifferentSearch") || "Try a different search term or use AI Deep Search"}</p>
          {query && (
            <div className="space-y-3 relative z-10">
              <p className="text-sm text-slate-400">Suggestions:</p>
              <div className="flex flex-wrap justify-center gap-2">
                {query.split(' ').filter(w => w.length > 3).slice(0, 3).map((term, idx) => (
                  <Badge
                    key={idx}
                    variant="outline"
                    className="cursor-pointer hover:bg-turquoise/10 hover:border-turquoise transition-colors relative z-20"
                    onClick={() => { setQuery(term); searchJobs(term); }}
                    data-testid={`suggestion-badge-${term.toLowerCase()}`}
                  >
                    Try: {term}
                  </Badge>
                ))}
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={() => deepSearch()}
                className="mt-4"
              >
                <Sparkles className="w-4 h-4 mr-2 text-violet-500" />
                Try AI Deep Search for related jobs
              </Button>
            </div>
          )}
        </div>
      ) : (
        <div className="grid gap-4">
          {jobs.map(job => (
            <JobCard 
              key={job.id} 
              job={job}
              isSaved={savedJobsArray.some(s => s.job?.id === job.id)}
              onSave={onSave}
              onApply={onApply}
              onAnalyze={onAnalyze}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default JobSearchPage;

import { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import {
  Video, User, ArrowRight, Loader2, Shield, Sparkles,
  Lock, Mail, KeyRound, UserCheck, ChevronLeft, RefreshCw
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent } from '@/components/ui/card';
import { Checkbox } from '@/components/ui/checkbox';
import { useTranslation } from '@/utils/i18n';

const API = process.env.REACT_APP_BACKEND_URL;

const STEPS = { INFO: 1, OTP: 2, AGE: 3 };

const GuestJoinPage = ({ onJoin, meetingIdProp }) => {
  const params = useParams();
  const meetingId = meetingIdProp || params.meetingId;
  const navigate = useNavigate();
  const { t } = useTranslation();

  const [step, setStep] = useState(STEPS.INFO);
  const [guestName, setGuestName] = useState('');
  const [email, setEmail] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [ageConfirmed, setAgeConfirmed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [pageLoading, setPageLoading] = useState(true);
  const [meetingInfo, setMeetingInfo] = useState(null);
  const [error, setError] = useState(null);
  const [resendCooldown, setResendCooldown] = useState(0);
  const otpRefs = useRef([]);

  useEffect(() => {
    if (meetingId) checkMeeting();
  }, [meetingId]);

  useEffect(() => {
    if (resendCooldown > 0) {
      const timer = setTimeout(() => setResendCooldown(c => c - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [resendCooldown]);

  const checkMeeting = async () => {
    try {
      const res = await fetch(`${API}/api/karau-meet/meetings/${meetingId}/info`);
      if (res.ok) {
        setMeetingInfo(await res.json());
      } else {
        setError('notFound');
      }
    } catch {
      setMeetingInfo({ title: 'AI KARAU Meeting', meeting_id: meetingId });
    }
    setPageLoading(false);
  };

  const handleRegister = async () => {
    if (!guestName.trim()) return toast.error(t("karauMeet.enterName"));
    if (!email.trim() || !email.includes('@')) return toast.error(t("karauMeet.enterValidEmail"));
    setLoading(true);
    try {
      const res = await fetch(`${API}/api/karau-meet/guest/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, name: guestName.trim(), meeting_id: meetingId })
      });
      const data = await res.json();
      if (res.ok && data.success) {
        toast.success(t("karauMeet.verificationCodeSentEmail"));
        setStep(STEPS.OTP);
        setResendCooldown(60);
      } else {
        toast.error(data.detail || t("karauMeet.failedSendVerification"));
      }
    } catch {
      toast.error(t("karauMeet.networkError"));
    }
    setLoading(false);
  };

  const handleVerifyOTP = async () => {
    const code = otp.join('');
    if (code.length !== 6) return toast.error(t("karauMeet.enterFullCode"));
    setLoading(true);
    try {
      const res = await fetch(`${API}/api/karau-meet/guest/verify-otp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, otp: code, meeting_id: meetingId })
      });
      const data = await res.json();
      if (res.ok && data.success) {
        toast.success(t("karauMeet.emailVerifiedSuccess"));
        setStep(STEPS.AGE);
      } else {
        toast.error(data.detail || t("karauMeet.invalidCode"));
      }
    } catch {
      toast.error(t("karauMeet.networkError"));
    }
    setLoading(false);
  };

  const handleAgeDeclaration = async () => {
    if (!ageConfirmed) return toast.error(t("karauMeet.confirmAge"));
    setLoading(true);
    try {
      const res = await fetch(`${API}/api/karau-meet/guest/age-declaration`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, meeting_id: meetingId, confirmed_age_16_plus: true })
      });
      const data = await res.json();
      if (res.ok && data.success) {
        toast.success(t("karauMeet.verificationComplete"));
        const guestUser = data.user || {
          user_id: data.guest_id,
          name: guestName,
          email,
          is_guest: true,
          is_verified: true,
        };
        if (onJoin) {
          onJoin(guestUser, meetingId);
        } else {
          localStorage.setItem('karau_guest', JSON.stringify(guestUser));
          navigate(`/karau-meet/lobby/${meetingId}`);
        }
      } else {
        toast.error(data.detail || t("karauMeet.verificationFailed2"));
        setLoading(false);
      }
    } catch {
      toast.error(t("karauMeet.networkError"));
      setLoading(false);
    }
  };

  const handleResendOTP = async () => {
    if (resendCooldown > 0) return;
    try {
      const res = await fetch(`${API}/api/karau-meet/guest/resend-otp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, name: guestName, meeting_id: meetingId })
      });
      if (res.ok) {
        toast.success(t("karauMeet.newCodeSent"));
        setResendCooldown(60);
        setOtp(['', '', '', '', '', '']);
      }
    } catch {
      toast.error(t("karauMeet.failedResend"));
    }
  };

  const handleOtpChange = (idx, val) => {
    if (val.length > 1) val = val.slice(-1);
    if (val && !/^\d$/.test(val)) return;
    const next = [...otp];
    next[idx] = val;
    setOtp(next);
    if (val && idx < 5) otpRefs.current[idx + 1]?.focus();
  };

  const handleOtpKeyDown = (idx, e) => {
    if (e.key === 'Backspace' && !otp[idx] && idx > 0) {
      otpRefs.current[idx - 1]?.focus();
    }
    if (e.key === 'Enter' && otp.join('').length === 6) handleVerifyOTP();
  };

  const handleOtpPaste = (e) => {
    e.preventDefault();
    const text = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, 6);
    if (text.length === 6) {
      setOtp(text.split(''));
      otpRefs.current[5]?.focus();
    }
  };

  if (pageLoading) {
    return (
      <div className="min-h-screen bg-karau-bg flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-purple-400 animate-spin" />
      </div>
    );
  }

  if (error === 'notFound') {
    return (
      <div className="min-h-screen bg-karau-bg flex items-center justify-center p-4">
        <Card className="bg-karau-card/80 border-karau-border max-w-md w-full rounded-2xl">
          <CardContent className="p-8 text-center">
            <div className="w-16 h-16 rounded-full bg-red-500/10 flex items-center justify-center mx-auto mb-4">
              <Video className="w-8 h-8 text-red-400" />
            </div>
            <h2 className="text-xl font-bold text-white mb-2">{t("karauMeet.meetingNotFound")}</h2>
            <p className="text-karau-muted text-sm mb-6">{t("karauMeet.meetingNotFoundDesc")}</p>
            <Button onClick={() => navigate('/karau-meet')} variant="outline" className="border-white/10 text-slate-300 rounded-xl" data-testid="guest-back-btn">
              {t("karauMeet.backToPortalBtn")}
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const stepLabels = [
    { num: 1, label: t("karauMeet.stepDetails"), icon: User },
    { num: 2, label: t("karauMeet.stepVerify"), icon: KeyRound },
    { num: 3, label: t("karauMeet.stepConfirm"), icon: UserCheck },
  ];

  return (
    <div className="min-h-screen bg-karau-bg flex items-center justify-center p-4" style={{ fontFamily: "'IBM Plex Sans', sans-serif" }}>
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-purple-500/5 rounded-full blur-3xl" />
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-emerald-500/5 rounded-full blur-3xl" />
      </div>

      <Card className="bg-karau-card/80 backdrop-blur-xl border-karau-border max-w-md w-full relative z-10 rounded-2xl" data-testid="guest-join-card">
        <CardContent className="p-8">
          <div className="flex items-center justify-center gap-3 mb-4">
            <img
              src="https://customer-assets.emergentagent.com/job_1fba32e3-e5a1-4174-b642-d1cd092309b3/artifacts/a7nojb8x_IMG_8477.jpeg"
              alt="AI KARAU"
              className="w-10 h-10 rounded-xl object-cover"
            />
            <span className="text-xl font-bold bg-gradient-to-r from-purple-400 via-violet-300 to-emerald-400 bg-clip-text text-transparent">
              AI KARAU Meeting
            </span>
          </div>

          <div className="text-center mb-5">
            <h1 className="text-xl font-bold text-white mb-1" data-testid="guest-meeting-title">
              {meetingInfo?.title || 'AI KARAU Meeting'}
            </h1>
            <p className="text-xs text-karau-muted">
              {t("karauMeet.meetingId")}: <span className="font-mono text-purple-400 font-semibold">{meetingId}</span>
            </p>
          </div>

          <div className="flex items-center justify-center gap-1 mb-6" data-testid="guest-step-indicator">
            {stepLabels.map((s, i) => (
              <div key={s.num} className="flex items-center">
                <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-all ${
                  step === s.num ? 'bg-purple-500/20 text-purple-400 border border-purple-500/30' :
                  step > s.num ? 'bg-emerald-500/15 text-emerald-400 border border-emerald-500/20' :
                  'bg-karau-surface/40 text-slate-500 border border-white/5'
                }`}>
                  <s.icon className="w-3.5 h-3.5" />
                  {s.label}
                </div>
                {i < 2 && <div className={`w-6 h-px mx-1 ${step > s.num ? 'bg-emerald-500/40' : 'bg-karau-border'}`} />}
              </div>
            ))}
          </div>

          {step === STEPS.INFO && (
            <div className="space-y-4" data-testid="guest-step-info">
              <div>
                <label className="text-sm font-medium text-slate-300 mb-1.5 block">{t("karauMeet.yourName")}</label>
                <div className="relative">
                  <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                  <Input
                    placeholder={t("karauMeet.enterFullName")}
                    value={guestName}
                    onChange={(e) => setGuestName(e.target.value)}
                    className="bg-karau-bg/60 border-white/10 text-white pl-10 h-11 rounded-xl focus:border-purple-500/40"
                    autoFocus
                    data-testid="guest-name-input"
                  />
                </div>
              </div>
              <div>
                <label className="text-sm font-medium text-slate-300 mb-1.5 block">{t("karauMeet.emailAddress")}</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                  <Input
                    type="email"
                    placeholder={t("karauMeet.emailPlaceholder")}
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleRegister()}
                    className="bg-karau-bg/60 border-white/10 text-white pl-10 h-11 rounded-xl focus:border-purple-500/40"
                    data-testid="guest-email-input"
                  />
                </div>
                <p className="text-xs text-slate-500 mt-1">{t("karauMeet.verificationCodeWillBeSent")}</p>
              </div>
              <Button
                onClick={handleRegister}
                disabled={loading || !guestName.trim() || !email.includes('@')}
                className="w-full h-11 bg-gradient-to-r from-purple-600 to-violet-600 hover:from-purple-500 hover:to-violet-500 text-white font-semibold rounded-xl shadow-lg shadow-purple-500/20"
                data-testid="guest-send-otp-btn"
              >
                {loading ? <Loader2 className="w-5 h-5 animate-spin mr-2" /> : <ArrowRight className="w-5 h-5 mr-2" />}
                {loading ? t("karauMeet.sendingCode") : t("karauMeet.sendVerificationCode")}
              </Button>
            </div>
          )}

          {step === STEPS.OTP && (
            <div className="space-y-4" data-testid="guest-step-otp">
              <div className="text-center">
                <div className="w-12 h-12 rounded-full bg-purple-500/10 flex items-center justify-center mx-auto mb-3">
                  <Mail className="w-6 h-6 text-purple-400" />
                </div>
                <p className="text-sm text-slate-300">{t("karauMeet.enterDigitCode")}</p>
                <p className="text-purple-400 font-medium text-sm">{email}</p>
              </div>

              <div className="flex justify-center gap-2" data-testid="guest-otp-inputs">
                {otp.map((digit, idx) => (
                  <input
                    key={idx}
                    ref={el => otpRefs.current[idx] = el}
                    type="text"
                    inputMode="numeric"
                    maxLength={1}
                    value={digit}
                    onChange={(e) => handleOtpChange(idx, e.target.value)}
                    onKeyDown={(e) => handleOtpKeyDown(idx, e)}
                    onPaste={idx === 0 ? handleOtpPaste : undefined}
                    className="w-11 h-12 text-center text-lg font-bold text-white bg-karau-bg/60 border border-white/10 rounded-lg focus:border-purple-500 focus:ring-1 focus:ring-purple-500/50 outline-none transition-all"
                    data-testid={`guest-otp-digit-${idx}`}
                  />
                ))}
              </div>

              <Button
                onClick={handleVerifyOTP}
                disabled={loading || otp.join('').length !== 6}
                className="w-full h-11 bg-gradient-to-r from-purple-600 to-violet-600 hover:from-purple-500 hover:to-violet-500 text-white font-semibold rounded-xl shadow-lg shadow-purple-500/20"
                data-testid="guest-verify-otp-btn"
              >
                {loading ? <Loader2 className="w-5 h-5 animate-spin mr-2" /> : <KeyRound className="w-5 h-5 mr-2" />}
                {loading ? t("karauMeet.verifying") : t("karauMeet.verifyCode")}
              </Button>

              <div className="flex items-center justify-between">
                <button
                  onClick={() => { setStep(STEPS.INFO); setOtp(['','','','','','']); }}
                  className="text-xs text-karau-muted hover:text-white flex items-center gap-1 transition-colors"
                  data-testid="guest-back-to-info"
                >
                  <ChevronLeft className="w-3 h-3" /> {t("karauMeet.changeEmail")}
                </button>
                <button
                  onClick={handleResendOTP}
                  disabled={resendCooldown > 0}
                  className={`text-xs flex items-center gap-1 transition-colors ${
                    resendCooldown > 0 ? 'text-slate-500 cursor-not-allowed' : 'text-purple-400 hover:text-purple-300'
                  }`}
                  data-testid="guest-resend-otp"
                >
                  <RefreshCw className="w-3 h-3" />
                  {resendCooldown > 0 ? t("karauMeet.resendIn", { seconds: resendCooldown }) : t("karauMeet.resendCode")}
                </button>
              </div>
            </div>
          )}

          {step === STEPS.AGE && (
            <div className="space-y-4" data-testid="guest-step-age">
              <div className="text-center">
                <div className="w-12 h-12 rounded-full bg-emerald-500/10 flex items-center justify-center mx-auto mb-3">
                  <UserCheck className="w-6 h-6 text-emerald-400" />
                </div>
                <p className="text-sm text-slate-300 mb-1">{t("karauMeet.emailVerifiedSuccessDesc")}</p>
                <p className="text-xs text-karau-muted">{t("karauMeet.lastStepBefore")}</p>
              </div>

              <div className="bg-karau-bg/60 rounded-xl p-4 border border-white/5">
                <div className="flex items-start gap-3">
                  <Checkbox
                    id="age-confirm"
                    checked={ageConfirmed}
                    onCheckedChange={setAgeConfirmed}
                    className="mt-0.5 border-white/20 data-[state=checked]:bg-emerald-500 data-[state=checked]:border-emerald-500"
                    data-testid="guest-age-checkbox"
                  />
                  <label htmlFor="age-confirm" className="text-sm text-slate-300 cursor-pointer leading-relaxed">
                    {t("karauMeet.ageConfirmTextPlain")}
                  </label>
                </div>
              </div>

              <Button
                onClick={handleAgeDeclaration}
                disabled={loading || !ageConfirmed}
                className="w-full h-11 bg-gradient-to-r from-emerald-500 to-emerald-600 hover:from-emerald-400 hover:to-emerald-500 text-white font-semibold rounded-xl shadow-lg shadow-emerald-500/20"
                data-testid="guest-join-btn"
              >
                {loading ? <Loader2 className="w-5 h-5 animate-spin mr-2" /> : <ArrowRight className="w-5 h-5 mr-2" />}
                {loading ? t("karauMeet.joining") : t("karauMeet.joinMeetingBtn")}
              </Button>

              <button
                onClick={() => setStep(STEPS.OTP)}
                className="w-full text-xs text-karau-muted hover:text-white flex items-center justify-center gap-1 transition-colors"
                data-testid="guest-back-to-otp"
              >
                <ChevronLeft className="w-3 h-3" /> {t("karauMeet.backToPortalBtn")}
              </button>
            </div>
          )}

          <div className="mt-5 grid grid-cols-3 gap-2">
            {[
              { icon: Shield, label: t("karauMeet.encrypted"), color: 'text-emerald-400' },
              { icon: Sparkles, label: t("karauMeet.aiPowered"), color: 'text-purple-400' },
              { icon: Lock, label: t("karauMeet.verified"), color: 'text-violet-400' },
            ].map((item, i) => (
              <div key={i} className="flex flex-col items-center gap-1 p-2 rounded-lg bg-karau-bg/40">
                <item.icon className={`w-4 h-4 ${item.color}`} />
                <span className="text-[10px] text-slate-500">{item.label}</span>
              </div>
            ))}
          </div>

          <div className="mt-3 text-center">
            <button
              onClick={() => navigate('/karau-meet')}
              className="text-xs text-slate-500 hover:text-purple-400 transition-colors"
              data-testid="guest-signin-link"
            >
              {t("karauMeet.haveAccount")}
            </button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default GuestJoinPage;

import { useState, useEffect } from 'react';
import { toast } from 'sonner';
import {
  Video, Clock, Archive, X, Loader2, Cloud, HardDrive,
  Download, CloudUpload, CheckCircle2, FileText, ChevronDown, ChevronUp,
  Sparkles, Send, Copy, Mail
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { useTranslation } from '@/utils/i18n';

const API = process.env.REACT_APP_BACKEND_URL;

const KarauRecordingsPage = () => {
  const { t } = useTranslation();
  const [recordings, setRecordings] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [downloadingId, setDownloadingId] = useState(null);
  const [expandedTranscript, setExpandedTranscript] = useState(null);
  const [transcriptData, setTranscriptData] = useState({});
  const [generatingNotes, setGeneratingNotes] = useState(null);
  const [notesData, setNotesData] = useState({});
  const [expandedNotes, setExpandedNotes] = useState(null);
  const [sendingNotes, setSendingNotes] = useState(null);
  const [sendEmail, setSendEmail] = useState('');

  useEffect(() => { fetchRecordings(); }, []);

  const fetchRecordings = async () => {
    const token = localStorage.getItem('token');
    try {
      const [recordingsRes, statsRes] = await Promise.all([
        fetch(`${API}/api/karau-meet/recordings/`, { headers: { 'Authorization': `Bearer ${token}` } }),
        fetch(`${API}/api/karau-meet/recordings/stats`, { headers: { 'Authorization': `Bearer ${token}` } })
      ]);
      if (recordingsRes.ok) {
        const data = await recordingsRes.json();
        setRecordings(data.recordings || []);
      }
      if (statsRes.ok) setStats(await statsRes.json());
    } catch (error) { console.error('Error fetching recordings:', error); }
    setLoading(false);
  };

  const formatDuration = (seconds) => {
    const hrs = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    if (hrs > 0) return `${hrs}h ${mins}m`;
    if (mins > 0) return `${mins}m ${secs}s`;
    return `${secs}s`;
  };

  const formatFileSize = (bytes) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
    return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
  };

  const downloadRecording = async (rec) => {
    if (rec.storage_type !== 'cloud') return;
    setDownloadingId(rec.recording_id);
    const token = localStorage.getItem('token');
    try {
      const res = await fetch(`${API}/api/karau-meet/recordings/download/${rec.recording_id}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (res.ok) {
        const blob = await res.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = rec.file_name || 'recording.webm';
        a.click();
        URL.revokeObjectURL(url);
        toast.success(t("karauMeet.downloadStarted") || 'Download started');
      } else {
        toast.error('Download failed');
      }
    } catch { toast.error('Download error'); }
    setDownloadingId(null);
  };

  const deleteRecording = async (recordingId) => {
    const token = localStorage.getItem('token');
    try {
      const res = await fetch(`${API}/api/karau-meet/recordings/${recordingId}`, {
        method: 'DELETE', headers: { 'Authorization': `Bearer ${token}` }
      });
      if (res.ok) {
        setRecordings(prev => prev.filter(r => r.recording_id !== recordingId));
        toast.success(t("karauMeet.recordingDeleted") || 'Recording deleted');
      }
    } catch { toast.error('Failed to delete'); }
  };

  const toggleTranscript = async (recordingId) => {
    if (expandedTranscript === recordingId) {
      setExpandedTranscript(null);
      return;
    }
    setExpandedTranscript(recordingId);
    if (transcriptData[recordingId]) return;
    const token = localStorage.getItem('token');
    try {
      const res = await fetch(`${API}/api/karau-meet/recordings/transcript/${recordingId}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (res.ok) {
        const data = await res.json();
        setTranscriptData(prev => ({ ...prev, [recordingId]: data }));
      }
    } catch {}
  };

  const generateNotes = async (recordingId) => {
    setGeneratingNotes(recordingId);
    const token = localStorage.getItem('token');
    try {
      const res = await fetch(`${API}/api/karau-meet/recordings/${recordingId}/notes/generate`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (res.ok) {
        const data = await res.json();
        setNotesData(prev => ({ ...prev, [recordingId]: data.notes }));
        setExpandedNotes(recordingId);
        toast.success('AI notes generated');
      } else {
        const err = await res.json().catch(() => ({}));
        toast.error(err.detail || 'Failed to generate notes');
      }
    } catch { toast.error('Notes generation error'); }
    setGeneratingNotes(null);
  };

  const fetchNotes = async (recordingId) => {
    if (notesData[recordingId]) {
      setExpandedNotes(expandedNotes === recordingId ? null : recordingId);
      return;
    }
    const token = localStorage.getItem('token');
    try {
      const res = await fetch(`${API}/api/karau-meet/recordings/${recordingId}/notes`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (res.ok) {
        const data = await res.json();
        if (data.notes) {
          setNotesData(prev => ({ ...prev, [recordingId]: data.notes }));
          setExpandedNotes(recordingId);
        }
      }
    } catch {}
  };

  const sendNotes = async (recordingId) => {
    if (!sendEmail.trim()) return;
    setSendingNotes(recordingId);
    const token = localStorage.getItem('token');
    const emails = sendEmail.split(',').map(e => e.trim()).filter(Boolean);
    try {
      const res = await fetch(`${API}/api/karau-meet/recordings/${recordingId}/notes/send`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify({ recipient_emails: emails })
      });
      if (res.ok) {
        toast.success(`Notes sent to ${emails.length} recipient(s)`);
        setSendEmail('');
        setSendingNotes(null);
      } else {
        toast.error('Failed to send notes');
      }
    } catch { toast.error('Send error'); }
    setSendingNotes(null);
  };

  const copyNotes = (recordingId) => {
    const notes = notesData[recordingId]?.notes;
    if (notes) {
      navigator.clipboard.writeText(notes);
      toast.success('Notes copied to clipboard');
    }
  };

  if (loading) {
    return (
      <div className="p-6 flex items-center justify-center">
        <Loader2 className="w-6 h-6 text-purple-400 animate-spin" />
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 space-y-5 max-w-5xl" style={{ fontFamily: "'IBM Plex Sans', sans-serif" }}>
      <div>
        <h1 className="text-xl font-bold text-white" data-testid="recordings-title">
          {t("karauMeet.recordingsTitle") || "Recordings"}
        </h1>
        <p className="text-xs text-karau-muted mt-0.5">{t("karauMeet.recordingsSubtitle") || "Your meeting recordings"}</p>
      </div>

      {stats && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div className="rounded-xl border border-white/5 bg-karau-card/40 p-3">
            <div className="flex items-center gap-2.5">
              <div className="w-9 h-9 rounded-lg bg-violet-500/15 flex items-center justify-center">
                <Video className="w-4 h-4 text-violet-400" />
              </div>
              <div>
                <p className="text-lg font-bold text-white" data-testid="stat-total">{stats.total_recordings}</p>
                <p className="text-[10px] text-karau-muted">{t("karauMeet.totalRecordings") || "Total"}</p>
              </div>
            </div>
          </div>
          <div className="rounded-xl border border-white/5 bg-karau-card/40 p-3">
            <div className="flex items-center gap-2.5">
              <div className="w-9 h-9 rounded-lg bg-emerald-500/15 flex items-center justify-center">
                <Clock className="w-4 h-4 text-emerald-400" />
              </div>
              <div>
                <p className="text-lg font-bold text-white" data-testid="stat-duration">{formatDuration(stats.total_duration_seconds)}</p>
                <p className="text-[10px] text-karau-muted">{t("karauMeet.totalDuration") || "Duration"}</p>
              </div>
            </div>
          </div>
          <div className="rounded-xl border border-white/5 bg-karau-card/40 p-3">
            <div className="flex items-center gap-2.5">
              <div className="w-9 h-9 rounded-lg bg-blue-500/15 flex items-center justify-center">
                <Cloud className="w-4 h-4 text-blue-400" />
              </div>
              <div>
                <p className="text-lg font-bold text-white" data-testid="stat-cloud">{stats.cloud_count || 0}</p>
                <p className="text-[10px] text-karau-muted">{t("karauMeet.cloudRecordings") || "Cloud"}</p>
              </div>
            </div>
          </div>
          <div className="rounded-xl border border-white/5 bg-karau-card/40 p-3">
            <div className="flex items-center gap-2.5">
              <div className="w-9 h-9 rounded-lg bg-amber-500/15 flex items-center justify-center">
                <Archive className="w-4 h-4 text-amber-400" />
              </div>
              <div>
                <p className="text-lg font-bold text-white" data-testid="stat-size">{formatFileSize(stats.total_size_bytes)}</p>
                <p className="text-[10px] text-karau-muted">{t("karauMeet.storageUsed") || "Storage"}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="rounded-xl border border-white/5 bg-karau-card/40">
        <div className="px-4 py-3 border-b border-white/5">
          <h2 className="text-sm font-semibold text-white">{t("karauMeet.yourRecordings") || "Your Recordings"}</h2>
        </div>
        <div className="p-3">
          {recordings.length === 0 ? (
            <div className="text-center py-10" data-testid="no-recordings">
              <Video className="w-10 h-10 text-slate-600 mx-auto mb-2" />
              <p className="text-sm text-karau-muted">{t("karauMeet.noRecordingsYet") || "No recordings yet"}</p>
              <p className="text-[10px] text-slate-600 mt-0.5">{t("karauMeet.startRecordingHint") || "Start recording in a meeting to see them here"}</p>
            </div>
          ) : (
            <div className="space-y-2">
              {recordings.map((rec) => (
                <div key={rec.recording_id} data-testid={`recording-${rec.recording_id}`}>
                  <div className="flex items-center justify-between p-3 bg-karau-bg/40 rounded-xl hover:bg-karau-surface/40 transition-colors group">
                    <div className="flex items-center gap-3 flex-1 min-w-0">
                      <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${
                        rec.storage_type === 'cloud' ? 'bg-blue-500/15' : 'bg-violet-500/15'
                      }`}>
                        {rec.storage_type === 'cloud'
                          ? <Cloud className="w-5 h-5 text-blue-400" />
                          : <HardDrive className="w-5 h-5 text-violet-400" />}
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm font-medium text-white truncate">{rec.meeting_title}</p>
                        <div className="flex items-center gap-2 text-[10px] text-karau-muted mt-0.5">
                          <span>{new Date(rec.recorded_at).toLocaleDateString()}</span>
                          <span>&middot;</span>
                          <span>{formatDuration(rec.duration_seconds)}</span>
                          <span>&middot;</span>
                          <span>{formatFileSize(rec.file_size_bytes)}</span>
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-1.5 ml-2">
                      {/* Transcription status */}
                      {rec.transcription_status === 'completed' && (
                        <Button variant="ghost" size="sm" onClick={() => toggleTranscript(rec.recording_id)}
                          className="h-7 px-1.5 text-emerald-400 hover:text-emerald-300 hover:bg-emerald-500/10"
                          data-testid={`transcript-${rec.recording_id}`}>
                          <FileText className="w-3.5 h-3.5 mr-0.5" />
                          {expandedTranscript === rec.recording_id ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                        </Button>
                      )}
                      {rec.transcription_status === 'completed' && (
                        notesData[rec.recording_id] ? (
                          <Button variant="ghost" size="sm" onClick={() => fetchNotes(rec.recording_id)}
                            className="h-7 px-1.5 text-violet-400 hover:text-violet-300 hover:bg-violet-500/10"
                            data-testid={`view-notes-${rec.recording_id}`}>
                            <Sparkles className="w-3.5 h-3.5 mr-0.5" />Notes
                          </Button>
                        ) : (
                          <Button variant="ghost" size="sm" onClick={() => generateNotes(rec.recording_id)}
                            disabled={generatingNotes === rec.recording_id}
                            className="h-7 px-1.5 text-amber-400 hover:text-amber-300 hover:bg-amber-500/10"
                            data-testid={`generate-notes-${rec.recording_id}`}>
                            {generatingNotes === rec.recording_id
                              ? <Loader2 className="w-3.5 h-3.5 mr-0.5 animate-spin" />
                              : <Sparkles className="w-3.5 h-3.5 mr-0.5" />}
                            AI Notes
                          </Button>
                        )
                      )}
                      {rec.transcription_status === 'completed' && rec.meeting_notes && !notesData[rec.recording_id] && (
                        <Button variant="ghost" size="sm" onClick={() => fetchNotes(rec.recording_id)}
                          className="h-7 px-1.5 text-violet-400 hover:text-violet-300 hover:bg-violet-500/10"
                          data-testid={`saved-notes-${rec.recording_id}`}>
                          <Sparkles className="w-3.5 h-3.5 mr-0.5" />Notes
                        </Button>
                      )}
                      {rec.transcription_status === 'processing' && (
                        <Badge className="bg-amber-500/10 text-amber-400 border-amber-500/15 text-[8px]">
                          <Loader2 className="w-2 h-2 mr-0.5 animate-spin" />Transcribing
                        </Badge>
                      )}
                      {rec.transcription_status === 'queued' && (
                        <Badge className="bg-purple-500/10 text-purple-400 border-purple-500/15 text-[8px]">Queued</Badge>
                      )}
                      {rec.storage_type === 'cloud' ? (
                        <Badge className="bg-blue-500/10 text-blue-400 border-blue-500/15 text-[9px]">
                          <Cloud className="w-2.5 h-2.5 mr-0.5" />Cloud
                        </Badge>
                      ) : (
                        <Badge className="bg-slate-500/10 text-slate-400 border-slate-500/15 text-[9px]">
                          <HardDrive className="w-2.5 h-2.5 mr-0.5" />Local
                        </Badge>
                      )}
                      {rec.storage_type === 'cloud' && (
                        <Button variant="ghost" size="sm" onClick={() => downloadRecording(rec)}
                          disabled={downloadingId === rec.recording_id}
                          className="h-7 w-7 p-0 text-emerald-400 hover:text-emerald-300 hover:bg-emerald-500/10"
                          data-testid={`download-${rec.recording_id}`}>
                          {downloadingId === rec.recording_id
                            ? <Loader2 className="w-3.5 h-3.5 animate-spin" />
                            : <Download className="w-3.5 h-3.5" />}
                        </Button>
                      )}
                      <Button variant="ghost" size="sm" onClick={() => deleteRecording(rec.recording_id)}
                        className="h-7 w-7 p-0 text-red-400 hover:text-red-300 hover:bg-red-500/10 opacity-0 group-hover:opacity-100 transition-opacity"
                        data-testid={`delete-${rec.recording_id}`}>
                        <X className="w-3.5 h-3.5" />
                      </Button>
                    </div>
                  </div>
                  {/* Expandable Transcript */}
                  {expandedTranscript === rec.recording_id && (
                    <div className="mt-1 p-3 bg-karau-card/30 rounded-lg border border-white/5 ml-13" data-testid={`transcript-content-${rec.recording_id}`}>
                      {!transcriptData[rec.recording_id] ? (
                        <div className="flex items-center gap-2 text-xs text-slate-400"><Loader2 className="w-3 h-3 animate-spin" />Loading transcript...</div>
                      ) : transcriptData[rec.recording_id].status === 'completed' && transcriptData[rec.recording_id].transcription ? (
                        <div className="space-y-2">
                          <div className="flex items-center justify-between">
                            <span className="text-[10px] text-emerald-400 font-medium flex items-center gap-1"><FileText className="w-3 h-3" />Transcript</span>
                            {transcriptData[rec.recording_id].transcription.language && (
                              <Badge className="bg-white/5 text-slate-400 border-white/10 text-[8px]">{transcriptData[rec.recording_id].transcription.language}</Badge>
                            )}
                          </div>
                          {transcriptData[rec.recording_id].transcription.segments?.length > 0 ? (
                            <div className="max-h-48 overflow-y-auto space-y-1">
                              {transcriptData[rec.recording_id].transcription.segments.map((seg, i) => (
                                <div key={i} className="flex gap-2 text-[10px]">
                                  <span className="text-purple-400 font-mono shrink-0 w-12">
                                    {Math.floor(seg.start / 60)}:{String(Math.floor(seg.start % 60)).padStart(2, '0')}
                                  </span>
                                  <span className="text-slate-300">{seg.text}</span>
                                </div>
                              ))}
                            </div>
                          ) : (
                            <p className="text-[10px] text-slate-300 whitespace-pre-wrap max-h-48 overflow-y-auto">
                              {transcriptData[rec.recording_id].transcription.text}
                            </p>
                          )}
                        </div>
                      ) : (
                        <p className="text-[10px] text-slate-500">{transcriptData[rec.recording_id].error || 'Transcript not available'}</p>
                      )}
                    </div>
                  )}

                  {/* Expandable AI Notes */}
                  {expandedNotes === rec.recording_id && notesData[rec.recording_id] && (
                    <div className="mt-1 p-3 bg-violet-500/5 rounded-lg border border-violet-500/10 ml-13" data-testid={`notes-content-${rec.recording_id}`}>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-[10px] text-violet-400 font-medium flex items-center gap-1">
                          <Sparkles className="w-3 h-3" />AI Meeting Notes
                        </span>
                        <div className="flex items-center gap-1">
                          <Button variant="ghost" size="sm" onClick={() => copyNotes(rec.recording_id)}
                            className="h-5 px-1.5 text-[8px] text-slate-400 hover:text-white" data-testid={`copy-notes-${rec.recording_id}`}>
                            <Copy className="w-2.5 h-2.5 mr-0.5" />Copy
                          </Button>
                          <Button variant="ghost" size="sm" onClick={() => setExpandedNotes(null)}
                            className="h-5 w-5 p-0 text-slate-400 hover:text-white">
                            <X className="w-3 h-3" />
                          </Button>
                        </div>
                      </div>
                      <div className="max-h-60 overflow-y-auto text-[10px] text-slate-300 whitespace-pre-wrap leading-relaxed prose-sm">
                        {notesData[rec.recording_id].notes}
                      </div>
                      <div className="mt-2 pt-2 border-t border-violet-500/10">
                        <p className="text-[9px] text-violet-400/70 mb-1.5 flex items-center gap-1">
                          <Mail className="w-2.5 h-2.5" />Send notes to participants
                        </p>
                        <div className="flex gap-1">
                          <Input
                            value={sendEmail}
                            onChange={e => setSendEmail(e.target.value)}
                            placeholder="email@example.com (comma-separated)"
                            className="bg-karau-bg/60 border-white/10 text-white text-[9px] h-6 rounded-lg flex-1"
                            data-testid={`send-notes-email-${rec.recording_id}`}
                          />
                          <Button size="sm" onClick={() => sendNotes(rec.recording_id)}
                            disabled={sendingNotes === rec.recording_id || !sendEmail.trim()}
                            className="h-6 px-2 text-[9px] bg-violet-500/80 hover:bg-violet-400 rounded-lg"
                            data-testid={`send-notes-btn-${rec.recording_id}`}>
                            {sendingNotes === rec.recording_id
                              ? <Loader2 className="w-2.5 h-2.5 animate-spin" />
                              : <Send className="w-2.5 h-2.5" />}
                          </Button>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

