import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";
import { useTheme } from "@/App";
import { 
  Bell, BellOff, Check, Trash2, RefreshCw, Settings, 
  Briefcase, MessageSquare, Calendar, Mail, Megaphone,
  Loader2, CheckCircle2, Circle, BellRing
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useTranslation } from "@/utils/i18n";
import { apiClient } from "@/utils/apiClient";

const NotificationsPage = ({ user }) => {
  const { isDark } = useTheme();
  const { t } = useTranslation();
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [preferences, setPreferences] = useState(null);
  const [subscriptions, setSubscriptions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSubscribing, setIsSubscribing] = useState(false);
  const [pushSupported, setPushSupported] = useState(false);
  const [pushPermission, setPushPermission] = useState('default');

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    try {
      const [historyRes, prefsRes, subsRes] = await Promise.all([
        apiClient.get("/api/notifications/history?limit=50"),
        apiClient.get("/api/notifications/preferences"),
        apiClient.get("/api/notifications/subscriptions")
      ]);

      setNotifications(historyRes.data.notifications || []);
      setUnreadCount(historyRes.data.unread_count || 0);
      setPreferences(prefsRes.data);
      setSubscriptions(subsRes.data.subscriptions || []);
    } catch (e) {
      console.error("Failed to fetch notifications:", e);
    }
    setIsLoading(false);
  }, []);

  useEffect(() => {
    // Check push notification support
    if ('Notification' in window && 'serviceWorker' in navigator) {
      setPushSupported(true);
      setPushPermission(Notification.permission);
    }

    fetchData();
  }, [fetchData]);

  const requestPushPermission = async () => {
    if (!pushSupported) {
      toast.error(t("notifications.notSupported") || "Push notifications not supported in this browser");
      return;
    }

    setIsSubscribing(true);
    try {
      const permission = await Notification.requestPermission();
      setPushPermission(permission);

      if (permission === 'granted') {
        // Register service worker and subscribe
        const subscription = {
          endpoint: `${window.location.origin}/push-endpoint-${Date.now()}`,
          keys: {
            p256dh: 'placeholder-key',
            auth: 'placeholder-auth'
          },
          user_agent: navigator.userAgent
        };

        await apiClient.post("/api/notifications/subscribe", subscription);
        toast.success(t("notifications.pushEnabled") || "Push notifications enabled!");
        fetchData();
      } else {
        toast.error(t("notifications.permissionDenied") || "Push notification permission denied");
      }
    } catch (e) {
      toast.error(t("notifications.enableFailed") || "Failed to enable push notifications");
      console.error(e);
    }
    setIsSubscribing(false);
  };

  const unsubscribe = async (endpoint) => {
    try {
      await apiClient.delete(`/api/notifications/unsubscribe?endpoint=${encodeURIComponent(endpoint)}`);
      toast.success(t("notifications.unsubscribed") || "Unsubscribed from push notifications");
      fetchData();
    } catch (e) {
      toast.error(t("notifications.unsubscribeFailed") || "Failed to unsubscribe");
    }
  };

  const updatePreference = async (key, value) => {
    const newPrefs = { ...preferences, [key]: value };
    setPreferences(newPrefs);

    try {
      await apiClient.put("/api/notifications/preferences", newPrefs);
      toast.success(t("notifications.prefsUpdated") || "Preferences updated");
    } catch (e) {
      toast.error(t("notifications.prefsFailed") || "Failed to update preferences");
      setPreferences(preferences); // Revert
    }
  };

  const markAsRead = async (notificationId) => {
    try {
      await apiClient.put(`/api/notifications/mark-read/${notificationId}`);
      setNotifications(prev => 
        prev.map(n => n.notification_id === notificationId ? { ...n, read: true } : n)
      );
      setUnreadCount(prev => Math.max(0, prev - 1));
    } catch (e) {
      toast.error(t("notifications.markReadFailed") || "Failed to mark as read");
    }
  };

  const markAllAsRead = async () => {
    try {
      await apiClient.put("/api/notifications/mark-all-read");
      setNotifications(prev => prev.map(n => ({ ...n, read: true })));
      setUnreadCount(0);
      toast.success(t("notifications.allMarkedRead") || "All notifications marked as read");
    } catch (e) {
      toast.error(t("notifications.markAllFailed") || "Failed to mark all as read");
    }
  };

  const sendTestNotification = async () => {
    try {
      await apiClient.post("/api/notifications/send-test");
      toast.success(t("notifications.testSent") || "Test notification sent!");
      fetchData();
    } catch (e) {
      toast.error(t("notifications.testFailed") || "Failed to send test notification");
    }
  };

  const getNotificationIcon = (type) => {
    switch (type) {
      case 'job_alert': return <Briefcase className="w-5 h-5 text-turquoise" />;
      case 'message': return <MessageSquare className="w-5 h-5 text-blue-500" />;
      case 'interview_reminder': return <Calendar className="w-5 h-5 text-purple-500" />;
      default: return <Bell className="w-5 h-5 text-slate-500" />;
    }
  };

  const preferenceItems = [
    { key: 'job_alerts', icon: Briefcase, label: t("notifications.jobAlerts") || 'Job Alerts', desc: t("notifications.jobAlertsDesc") || 'Get notified about new matching jobs' },
    { key: 'application_updates', icon: CheckCircle2, label: t("notifications.appUpdates") || 'Application Updates', desc: t("notifications.appUpdatesDesc") || 'Status changes on your applications' },
    { key: 'messages', icon: MessageSquare, label: t("notifications.messages") || 'Messages', desc: t("notifications.messagesDesc") || 'New messages from recruiters' },
    { key: 'interview_reminders', icon: Calendar, label: t("notifications.interviewReminders") || 'Interview Reminders', desc: t("notifications.interviewRemindersDesc") || 'Upcoming interview notifications' },
    { key: 'weekly_digest', icon: Mail, label: t("notifications.weeklyDigest") || 'Weekly Digest', desc: t("notifications.weeklyDigestDesc") || 'Weekly summary of job matches' },
    { key: 'marketing', icon: Megaphone, label: t("notifications.marketing") || 'Marketing', desc: t("notifications.marketingDesc") || 'Tips, news, and promotions' }
  ];

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="w-8 h-8 animate-spin text-turquoise" />
      </div>
    );
  }

  return (
    <div className="p-6 md:p-8 lg:p-12 max-w-5xl mx-auto" data-testid="notifications-page">
      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-semibold text-slate-900 dark:text-slate-100" style={{ fontFamily: 'IBM Plex Sans' }}>
            {t("notifications.title") || "Notifications"}
          </h1>
          <p className="text-slate-500 dark:text-slate-400 mt-1">
            {t("notifications.subtitle") || "Manage your notification preferences and history"}
          </p>
        </div>
        {unreadCount > 0 && (
          <Badge className="bg-turquoise text-white">{unreadCount} {t("notifications.unread") || "unread"}</Badge>
        )}
      </div>

      <Tabs defaultValue="history" className="space-y-6">
        <TabsList>
          <TabsTrigger value="history" className="flex items-center gap-2">
            <Bell className="w-4 h-4" /> {t("notifications.history") || "History"}
          </TabsTrigger>
          <TabsTrigger value="preferences" className="flex items-center gap-2">
            <Settings className="w-4 h-4" /> {t("notifications.preferences") || "Preferences"}
          </TabsTrigger>
        </TabsList>

        {/* Notification History */}
        <TabsContent value="history">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle>{t("notifications.historyTitle") || "Notification History"}</CardTitle>
                <CardDescription>{t("notifications.historyDesc") || "Your recent notifications"}</CardDescription>
              </div>
              <div className="flex gap-2">
                <Button variant="outline" size="sm" onClick={fetchData} data-testid="refresh-notifications">
                  <RefreshCw className="w-4 h-4 mr-1" /> {t("common.refresh") || "Refresh"}
                </Button>
                {unreadCount > 0 && (
                  <Button variant="outline" size="sm" onClick={markAllAsRead} data-testid="mark-all-read">
                    <Check className="w-4 h-4 mr-1" /> {t("notifications.markAllRead") || "Mark All Read"}
                  </Button>
                )}
              </div>
            </CardHeader>
            <CardContent>
              {notifications.length === 0 ? (
                <div className="text-center py-12 text-slate-400">
                  <BellOff className="w-12 h-12 mx-auto mb-4 opacity-40" />
                  <p>{t("notifications.noNotifications") || "No notifications yet"}</p>
                  <Button 
                    variant="outline" 
                    className="mt-4"
                    onClick={sendTestNotification}
                    data-testid="send-test-notification"
                  >
                    {t("notifications.sendTest") || "Send Test Notification"}
                  </Button>
                </div>
              ) : (
                <div className="space-y-3">
                  {notifications.map((notification) => (
                    <div
                      key={notification.notification_id}
                      className={`flex items-start gap-4 p-4 rounded-lg transition-colors cursor-pointer ${
                        notification.read 
                          ? 'bg-slate-50 dark:bg-slate-800/50' 
                          : 'bg-turquoise/5 dark:bg-turquoise/10 border-l-4 border-turquoise'
                      }`}
                      onClick={() => !notification.read && markAsRead(notification.notification_id)}
                      data-testid={`notification-${notification.notification_id}`}
                    >
                      <div className="mt-0.5">
                        {getNotificationIcon(notification.data?.type)}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <p className={`font-medium ${notification.read ? 'text-slate-600 dark:text-slate-400' : 'text-slate-900 dark:text-slate-100'}`}>
                            {notification.title}
                          </p>
                          {!notification.read && (
                            <Circle className="w-2 h-2 fill-turquoise text-turquoise" />
                          )}
                        </div>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
                          {notification.body}
                        </p>
                        <p className="text-xs text-slate-400 mt-2">
                          {new Date(notification.created_at).toLocaleString()}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Preferences */}
        <TabsContent value="preferences">
          <div className="space-y-6">
            {/* Push Notifications Card */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <BellRing className="w-5 h-5 text-turquoise" />
                  {t("notifications.pushNotifications") || "Push Notifications"}
                </CardTitle>
                <CardDescription>
                  {t("notifications.pushDesc") || "Receive instant notifications on this device"}
                </CardDescription>
              </CardHeader>
              <CardContent>
                {!pushSupported ? (
                  <p className="text-amber-600 dark:text-amber-400 text-sm">
                    {t("notifications.notSupported") || "Push notifications are not supported in this browser"}
                  </p>
                ) : pushPermission === 'granted' && subscriptions.length > 0 ? (
                  <div className="space-y-4">
                    <div className="flex items-center gap-3 p-3 bg-emerald-50 dark:bg-emerald-900/20 rounded-lg">
                      <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                      <span className="text-emerald-700 dark:text-emerald-300 font-medium">
                        {t("notifications.pushEnabled") || "Push notifications enabled"}
                      </span>
                    </div>

                    <div className="space-y-2">
                      <p className="text-sm text-slate-500 dark:text-slate-400">{t("notifications.subscribedDevices") || "Subscribed devices"}:</p>
                      {subscriptions.map((sub) => (
                        <div 
                          key={sub.subscription_id}
                          className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800 rounded-lg"
                        >
                          <div>
                            <p className="text-sm font-medium text-slate-700 dark:text-slate-300">
                              {sub.user_agent?.split(' ')[0] || 'Device'}
                            </p>
                            <p className="text-xs text-slate-500">
                              {t("notifications.added") || "Added"} {new Date(sub.created_at).toLocaleDateString()}
                            </p>
                          </div>
                          <Button 
                            variant="ghost" 
                            size="sm"
                            onClick={() => unsubscribe(sub.endpoint)}
                            className="text-red-500 hover:text-red-600"
                          >
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        </div>
                      ))}
                    </div>

                    <Button 
                      variant="outline" 
                      onClick={sendTestNotification}
                      className="w-full"
                      data-testid="test-push-notification"
                    >
                      <Bell className="w-4 h-4 mr-2" />
                      {t("notifications.sendTest") || "Send Test Notification"}
                    </Button>
                  </div>
                ) : (
                  <div className="text-center py-4">
                    <p className="text-slate-500 dark:text-slate-400 mb-4">
                      {t("notifications.enablePushDesc") || "Enable push notifications to receive instant updates"}
                    </p>
                    <Button 
                      onClick={requestPushPermission}
                      disabled={isSubscribing}
                      className="bg-turquoise hover:bg-turquoise/90"
                      data-testid="enable-push-btn"
                    >
                      {isSubscribing ? (
                        <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                      ) : (
                        <Bell className="w-4 h-4 mr-2" />
                      )}
                      {t("notifications.enablePush") || "Enable Push Notifications"}
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Notification Preferences */}
            <Card>
              <CardHeader>
                <CardTitle>{t("notifications.preferencesTitle") || "Notification Preferences"}</CardTitle>
                <CardDescription>{t("notifications.preferencesDesc") || "Choose what notifications you want to receive"}</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {preferenceItems.map(({ key, icon: Icon, label, desc }) => (
                    <div 
                      key={key}
                      className="flex items-center justify-between py-3 border-b border-slate-100 dark:border-slate-800 last:border-0"
                    >
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center">
                          <Icon className="w-5 h-5 text-slate-600 dark:text-slate-400" />
                        </div>
                        <div>
                          <p className="font-medium text-slate-900 dark:text-slate-100">{label}</p>
                          <p className="text-sm text-slate-500 dark:text-slate-400">{desc}</p>
                        </div>
                      </div>
                      <Switch
                        checked={preferences?.[key] ?? true}
                        onCheckedChange={(checked) => updatePreference(key, checked)}
                        data-testid={`pref-${key}`}
                      />
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
};

export default NotificationsPage;

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import {
  FileText, DollarSign, Calendar, Send, Plus, Loader2, Sparkles,
  Check, Clock, X, AlertCircle, ChevronRight, ArrowUpRight,
  ArrowDownRight, Briefcase, User, Eye
} from 'lucide-react';

const API = process.env.REACT_APP_BACKEND_URL;

const STATUS_CONFIG = {
  draft: { color: 'bg-slate-500/20 text-slate-400 border-slate-500/30', icon: FileText, label: 'Draft' },
  pending_approval: { color: 'bg-amber-500/20 text-amber-400 border-amber-500/30', icon: Clock, label: 'Pending' },
  approved: { color: 'bg-blue-500/20 text-blue-400 border-blue-500/30', icon: Check, label: 'Approved' },
  sent: { color: 'bg-cyan-500/20 text-cyan-400 border-cyan-500/30', icon: Send, label: 'Sent' },
  negotiating: { color: 'bg-violet-500/20 text-violet-400 border-violet-500/30', icon: AlertCircle, label: 'Negotiating' },
  accepted: { color: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30', icon: Check, label: 'Accepted' },
  declined: { color: 'bg-red-500/20 text-red-400 border-red-500/30', icon: X, label: 'Declined' },
  withdrawn: { color: 'bg-orange-500/20 text-orange-400 border-orange-500/30', icon: X, label: 'Withdrawn' },
};

const STATUS_FLOW = {
  draft: ['pending_approval', 'sent', 'withdrawn'],
  pending_approval: ['approved', 'withdrawn'],
  approved: ['sent', 'withdrawn'],
  sent: ['negotiating', 'accepted', 'declined', 'withdrawn'],
  negotiating: ['sent', 'accepted', 'declined', 'withdrawn'],
  accepted: [],
  declined: [],
  withdrawn: [],
};

function StatBadge({ label, value, icon: Icon, accent }) {
  return (
    <div className="p-3 rounded-lg bg-slate-700/30 border border-slate-700/40">
      <div className="flex items-center gap-2 mb-1">
        {Icon && <Icon className={`w-3.5 h-3.5 ${accent || 'text-slate-500'}`} />}
        <span className="text-[10px] text-slate-400 uppercase tracking-wider">{label}</span>
      </div>
      <p className="text-lg font-bold text-white">{value}</p>
    </div>
  );
}

function OfferTimeline({ timeline }) {
  if (!timeline?.length) return null;
  return (
    <div className="space-y-2 mt-3">
      <h4 className="text-xs font-medium text-slate-400">Activity Timeline</h4>
      {timeline.map((e, i) => (
        <div key={i} className="flex items-start gap-2.5 text-xs">
          <div className="w-1.5 h-1.5 rounded-full bg-teal-500 mt-1.5 shrink-0" />
          <div>
            <span className="text-slate-300 capitalize">{e.action.replace(/_/g, ' ')}</span>
            {e.by && <span className="text-slate-500 ml-1">by {e.by}</span>}
            <span className="text-slate-600 ml-2">{new Date(e.at).toLocaleDateString()}</span>
          </div>
        </div>
      ))}
    </div>
  );
}

function OfferDetail({ offer, onClose, onUpdate, onGenerateLetter }) {
  const [generatingLetter, setGeneratingLetter] = useState(false);
  const [letterContent, setLetterContent] = useState('');
  const fetchOpts = { credentials: 'include' };
  const postOpts = { credentials: 'include', headers: { 'Content-Type': 'application/json' } };

  const genLetter = async () => {
    setGeneratingLetter(true);
    try {
      const res = await fetch(`${API}/api/advanced/offers/${offer.id}/generate-letter`, { method: 'POST', ...fetchOpts });
      if (res.ok) { const d = await res.json(); setLetterContent(d.letter); }
    } catch (e) { console.error(e); }
    setGeneratingLetter(false);
  };

  const changeStatus = async (status) => {
    try {
      await fetch(`${API}/api/advanced/offers/${offer.id}/status`, {
        method: 'PUT', ...postOpts, body: JSON.stringify({ status })
      });
      onUpdate({ ...offer, status });
    } catch (e) { console.error(e); }
  };

  const nextStatuses = STATUS_FLOW[offer.status] || [];

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="bg-slate-800 border-slate-700 text-white max-w-2xl max-h-[85vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <span>{offer.candidate_name}</span>
            <ChevronRight className="w-3 h-3 text-slate-500" />
            <span className="text-slate-400 font-normal">{offer.job_title}</span>
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* Status & Actions */}
          <div className="flex items-center gap-2 flex-wrap">
            <Badge className={`${STATUS_CONFIG[offer.status]?.color || 'bg-slate-600'} text-xs`} data-testid="offer-detail-status">
              {STATUS_CONFIG[offer.status]?.label || offer.status}
            </Badge>
            {nextStatuses.map(s => (
              <Button key={s} size="sm" variant="outline" className="h-6 text-[10px] border-slate-600 text-slate-300 capitalize"
                onClick={() => changeStatus(s)} data-testid={`action-${s}`}>
                {STATUS_CONFIG[s]?.label || s}
              </Button>
            ))}
          </div>

          {/* Offer Details Grid */}
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            <StatBadge label="Salary" value={`${offer.currency} ${offer.salary?.toLocaleString()}`} icon={DollarSign} accent="text-emerald-400" />
            {offer.bonus > 0 && <StatBadge label="Bonus" value={`${offer.currency} ${offer.bonus?.toLocaleString()}`} icon={DollarSign} accent="text-amber-400" />}
            {offer.equity && <StatBadge label="Equity" value={offer.equity} icon={Briefcase} accent="text-violet-400" />}
            {offer.start_date && <StatBadge label="Start Date" value={offer.start_date} icon={Calendar} accent="text-blue-400" />}
            {offer.hiring_manager && <StatBadge label="Hiring Manager" value={offer.hiring_manager} icon={User} accent="text-cyan-400" />}
          </div>

          {/* Benefits */}
          {offer.benefits?.length > 0 && (
            <div>
              <h4 className="text-xs font-medium text-slate-400 mb-1.5">Benefits</h4>
              <div className="flex gap-1.5 flex-wrap">
                {offer.benefits.map(b => <span key={b} className="px-2 py-0.5 text-xs bg-slate-700/60 text-slate-300 rounded">{b}</span>)}
              </div>
            </div>
          )}

          {/* Notes */}
          {offer.notes && (
            <div>
              <h4 className="text-xs font-medium text-slate-400 mb-1">Notes</h4>
              <p className="text-sm text-slate-300">{offer.notes}</p>
            </div>
          )}

          {/* Timeline */}
          <OfferTimeline timeline={offer.timeline} />

          {/* AI Letter */}
          <div className="border-t border-slate-700 pt-3">
            <Button size="sm" className="bg-violet-600 hover:bg-violet-500 text-xs" onClick={genLetter} disabled={generatingLetter} data-testid="gen-letter-detail">
              {generatingLetter ? <Loader2 className="w-3 h-3 animate-spin mr-1" /> : <Sparkles className="w-3 h-3 mr-1" />} Generate AI Offer Letter
            </Button>
            {letterContent && (
              <div className="mt-3 p-4 bg-slate-900/50 rounded-lg border border-slate-700/50">
                <pre className="whitespace-pre-wrap text-xs text-slate-300 font-sans leading-relaxed" data-testid="offer-letter-detail">{letterContent}</pre>
              </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

export default function OfferManagementPage() {
  const [offers, setOffers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [selectedOffer, setSelectedOffer] = useState(null);
  const [statusFilter, setStatusFilter] = useState('all');
  const [form, setForm] = useState({
    candidate_name: '', job_title: '', salary: '', currency: 'USD',
    start_date: '', benefits: '', notes: '', equity: '', bonus: '', hiring_manager: ''
  });
  const fetchOpts = { credentials: 'include' };
  const postOpts = { credentials: 'include', headers: { 'Content-Type': 'application/json' } };

  useEffect(() => {
    fetch(`${API}/api/advanced/offers`, fetchOpts).then(r => r.ok ? r.json() : { offers: [] }).then(d => { setOffers(d.offers || []); setLoading(false); }).catch(() => setLoading(false));
  }, []);

  const createOffer = async () => {
    if (!form.candidate_name || !form.job_title || !form.salary) return;
    setLoading(true);
    try {
      const res = await fetch(`${API}/api/advanced/offers`, {
        method: 'POST', ...postOpts,
        body: JSON.stringify({
          ...form, salary: parseFloat(form.salary), bonus: parseFloat(form.bonus) || 0,
          candidate_id: '', job_id: '',
          benefits: form.benefits.split(',').map(b => b.trim()).filter(Boolean)
        })
      });
      if (res.ok) {
        const o = await res.json();
        setOffers([o, ...offers]);
        setShowCreate(false);
        setForm({ candidate_name: '', job_title: '', salary: '', currency: 'USD', start_date: '', benefits: '', notes: '', equity: '', bonus: '', hiring_manager: '' });
      }
    } catch (e) { console.error(e); }
    setLoading(false);
  };

  const updateStatus = async (offerId, status) => {
    try {
      await fetch(`${API}/api/advanced/offers/${offerId}/status`, { method: 'PUT', ...postOpts, body: JSON.stringify({ status }) });
      setOffers(offers.map(o => o.id === offerId ? { ...o, status } : o));
    } catch (e) { console.error(e); }
  };

  const filtered = statusFilter === 'all' ? offers : offers.filter(o => o.status === statusFilter);

  // Stats
  const stats = {
    total: offers.length,
    accepted: offers.filter(o => o.status === 'accepted').length,
    pending: offers.filter(o => ['draft', 'pending_approval', 'sent', 'negotiating'].includes(o.status)).length,
    declined: offers.filter(o => o.status === 'declined').length,
  };
  const acceptRate = stats.total ? `${Math.round((stats.accepted / stats.total) * 100)}%` : '0%';

  return (
    <div className="min-h-screen bg-slate-900 p-4 md:p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex items-center justify-between mb-5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-violet-500/20 to-pink-500/20 flex items-center justify-center">
              <FileText className="w-5 h-5 text-violet-400" />
            </div>
            <div>
              <h1 className="text-xl md:text-2xl font-bold text-white" data-testid="offers-title">Offer Management</h1>
              <p className="text-xs text-slate-400">Create, track, and manage job offers with AI</p>
            </div>
          </div>
          <Button className="bg-violet-600 hover:bg-violet-500 text-sm h-9" onClick={() => setShowCreate(true)} data-testid="create-offer-btn">
            <Plus className="w-4 h-4 mr-1.5" /> New Offer
          </Button>
        </div>

        {/* Stats Bar */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-5">
          <StatBadge label="Total Offers" value={stats.total} icon={FileText} accent="text-violet-400" />
          <StatBadge label="Acceptance Rate" value={acceptRate} icon={ArrowUpRight} accent="text-emerald-400" />
          <StatBadge label="Pending" value={stats.pending} icon={Clock} accent="text-amber-400" />
          <StatBadge label="Declined" value={stats.declined} icon={ArrowDownRight} accent="text-red-400" />
        </div>

        {/* Status Filters */}
        <div className="flex gap-1.5 mb-5 flex-wrap">
          {['all', 'draft', 'pending_approval', 'approved', 'sent', 'negotiating', 'accepted', 'declined'].map(s => (
            <button key={s} onClick={() => setStatusFilter(s)}
              className={`px-2.5 py-1 text-xs rounded-full border transition-all capitalize ${statusFilter === s
                ? (STATUS_CONFIG[s]?.color || 'bg-teal-500/20 text-teal-400 border-teal-500/30')
                : 'border-slate-700 text-slate-500 hover:border-slate-600'}`}
              data-testid={`filter-${s}`}>
              {s === 'all' ? `All (${offers.length})` : `${STATUS_CONFIG[s]?.label || s} (${offers.filter(o => o.status === s).length})`}
            </button>
          ))}
        </div>

        {/* Create Offer Dialog */}
        <Dialog open={showCreate} onOpenChange={setShowCreate}>
          <DialogContent className="bg-slate-800 border-slate-700 text-white max-w-lg">
            <DialogHeader><DialogTitle>New Job Offer</DialogTitle></DialogHeader>
            <div className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <Input value={form.candidate_name} onChange={e => setForm({ ...form, candidate_name: e.target.value })} placeholder="Candidate name *" className="bg-slate-700 border-slate-600 text-white" data-testid="offer-candidate-name" />
                <Input value={form.job_title} onChange={e => setForm({ ...form, job_title: e.target.value })} placeholder="Job title *" className="bg-slate-700 border-slate-600 text-white" data-testid="offer-job-title" />
              </div>
              <div className="grid grid-cols-3 gap-3">
                <Input type="number" value={form.salary} onChange={e => setForm({ ...form, salary: e.target.value })} placeholder="Salary *" className="bg-slate-700 border-slate-600 text-white" data-testid="offer-salary" />
                <Select value={form.currency} onValueChange={v => setForm({ ...form, currency: v })}>
                  <SelectTrigger className="bg-slate-700 border-slate-600 text-white"><SelectValue /></SelectTrigger>
                  <SelectContent><SelectItem value="USD">USD</SelectItem><SelectItem value="EUR">EUR</SelectItem><SelectItem value="GBP">GBP</SelectItem><SelectItem value="INR">INR</SelectItem></SelectContent>
                </Select>
                <Input type="number" value={form.bonus} onChange={e => setForm({ ...form, bonus: e.target.value })} placeholder="Bonus" className="bg-slate-700 border-slate-600 text-white" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <Input type="date" value={form.start_date} onChange={e => setForm({ ...form, start_date: e.target.value })} className="bg-slate-700 border-slate-600 text-white" />
                <Input value={form.equity} onChange={e => setForm({ ...form, equity: e.target.value })} placeholder="Equity (e.g., 0.1%)" className="bg-slate-700 border-slate-600 text-white" />
              </div>
              <Input value={form.hiring_manager} onChange={e => setForm({ ...form, hiring_manager: e.target.value })} placeholder="Hiring manager" className="bg-slate-700 border-slate-600 text-white" />
              <Input value={form.benefits} onChange={e => setForm({ ...form, benefits: e.target.value })} placeholder="Benefits (comma-separated)" className="bg-slate-700 border-slate-600 text-white" />
              <Textarea value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Notes" className="bg-slate-700 border-slate-600 text-white min-h-[60px]" />
            </div>
            <DialogFooter>
              <Button variant="ghost" className="text-slate-400" onClick={() => setShowCreate(false)}>Cancel</Button>
              <Button className="bg-violet-600 hover:bg-violet-500" onClick={createOffer} disabled={!form.candidate_name || !form.job_title || !form.salary} data-testid="save-offer-btn">Create Offer</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        {/* Offers List */}
        <div className="space-y-2" data-testid="offers-list">
          {filtered.length === 0 ? (
            <div className="text-center py-16 text-slate-500">
              <FileText className="w-10 h-10 mx-auto mb-3 opacity-15" />
              <p className="text-sm">{statusFilter === 'all' ? 'No offers yet. Create your first one.' : 'No offers with this status.'}</p>
            </div>
          ) : filtered.map(o => {
            const cfg = STATUS_CONFIG[o.status] || STATUS_CONFIG.draft;
            const nextActions = STATUS_FLOW[o.status] || [];
            return (
              <Card key={o.id} className="bg-slate-800/50 border-slate-700/40 hover:border-slate-600/60 transition-all group">
                <CardContent className="p-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3 min-w-0 flex-1">
                      <div className="w-9 h-9 rounded-full bg-gradient-to-br from-violet-500/30 to-pink-500/30 flex items-center justify-center text-sm font-bold text-violet-300 shrink-0">
                        {o.candidate_name?.charAt(0)?.toUpperCase()}
                      </div>
                      <div className="min-w-0">
                        <div className="flex items-center gap-2">
                          <p className="text-sm font-medium text-white truncate">{o.candidate_name}</p>
                          <ChevronRight className="w-3 h-3 text-slate-600 shrink-0" />
                          <p className="text-sm text-slate-400 truncate">{o.job_title}</p>
                        </div>
                        <div className="flex items-center gap-3 mt-0.5 text-xs text-slate-500">
                          <span className="flex items-center gap-1"><DollarSign className="w-3 h-3" /> {o.currency} {o.salary?.toLocaleString()}</span>
                          {o.start_date && <span className="flex items-center gap-1"><Calendar className="w-3 h-3" /> {o.start_date}</span>}
                          {o.hiring_manager && <span className="flex items-center gap-1"><User className="w-3 h-3" /> {o.hiring_manager}</span>}
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 shrink-0 ml-3">
                      <Badge className={`text-[10px] ${cfg.color}`}>{cfg.label}</Badge>
                      {nextActions.slice(0, 2).map(s => (
                        <Button key={s} size="sm" variant="ghost" className="h-6 text-[10px] text-slate-400 hover:text-white hidden md:flex"
                          onClick={(e) => { e.stopPropagation(); updateStatus(o.id, s); }} data-testid={`quick-${s}-${o.id}`}>
                          {STATUS_CONFIG[s]?.label || s}
                        </Button>
                      ))}
                      <Button size="sm" variant="ghost" className="h-7 text-xs text-teal-400" onClick={() => setSelectedOffer(o)} data-testid={`view-offer-${o.id}`}>
                        <Eye className="w-3 h-3 mr-1" /> View
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>

        {/* Offer Detail Dialog */}
        {selectedOffer && (
          <OfferDetail
            offer={selectedOffer}
            onClose={() => setSelectedOffer(null)}
            onUpdate={(updated) => { setSelectedOffer(updated); setOffers(offers.map(o => o.id === updated.id ? updated : o)); }}
          />
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { 
  Shield, Download, Trash2, FileText, Mic, Brain, 
  ChevronRight, AlertTriangle, Check, ExternalLink,
  Clock, Eye, Building2, Languages, Globe
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { useTranslation } from "@/utils/i18n";
import { useBrowserTranslationDetection, openGoogleTranslate, triggerBrowserTranslate } from "@/components/GlobalLanguageSelector";
import axios from "axios";
import { toast } from "sonner";

const API = process.env.REACT_APP_BACKEND_URL;

/**
 * Privacy Settings Page
 * GDPR/CCPA compliant data management
 */
const PrivacySettingsPage = () => {
  const { t } = useTranslation();
  const isBrowserTranslating = useBrowserTranslationDetection();
  const [consentStatus, setConsentStatus] = useState(null);
  const [auditLogs, setAuditLogs] = useState([]);
  const [subProcessors, setSubProcessors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [exportingData, setExportingData] = useState(false);
  const [deletingData, setDeletingData] = useState(false);
  const [deleteOptions, setDeleteOptions] = useState({
    delete_resume: false,
    delete_voice_history: false,
    delete_applications: false,
    delete_matches: false,
    delete_account: false
  });

  useEffect(() => {
    fetchPrivacyData();
  }, []);

  const fetchPrivacyData = async () => {
    setLoading(true);
    const token = localStorage.getItem("medmatch-token");
    const headers = { Authorization: `Bearer ${token}` };

    try {
      const [consentRes, logsRes, processorsRes] = await Promise.all([
        axios.get(`${API}/api/privacy/consent/status`, { headers }),
        axios.get(`${API}/api/privacy/audit/logs?limit=10`, { headers }),
        axios.get(`${API}/api/privacy/sub-processors`)
      ]);

      setConsentStatus(consentRes.data);
      setAuditLogs(logsRes.data.logs || []);
      setSubProcessors(processorsRes.data.sub_processors || []);
    } catch (err) {
      console.error("Error fetching privacy data:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleExportData = async () => {
    setExportingData(true);
    try {
      const token = localStorage.getItem("medmatch-token");
      const response = await axios.get(
        `${API}/api/privacy/data/export`,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      // Download as JSON
      const blob = new Blob([JSON.stringify(response.data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `medmatch-data-export-${new Date().toISOString().split('T')[0]}.json`;
      a.click();
      URL.revokeObjectURL(url);

      toast.success("Data exported successfully!");
    } catch (err) {
      toast.error("Failed to export data");
    } finally {
      setExportingData(false);
    }
  };

  const handleDeleteData = async () => {
    if (!Object.values(deleteOptions).some(v => v)) {
      toast.error("Please select data to delete");
      return;
    }

    setDeletingData(true);
    try {
      const token = localStorage.getItem("medmatch-token");
      const response = await axios.post(
        `${API}/api/privacy/data/delete`,
        deleteOptions,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      toast.success("Data deleted successfully");

      if (deleteOptions.delete_account) {
        // Logout if account deleted
        localStorage.clear();
        window.location.href = "/login";
      } else {
        fetchPrivacyData();
      }
    } catch (err) {
      toast.error(err.response?.data?.detail || "Failed to delete data");
    } finally {
      setDeletingData(false);
    }
  };

  const handleWithdrawConsent = async () => {
    try {
      const token = localStorage.getItem("medmatch-token");
      await axios.post(
        `${API}/api/privacy/consent/withdraw`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );

      toast.success("Consent withdrawn. AI-processed data will be deleted.");
      localStorage.removeItem("medmatch-consent-granted");
      fetchPrivacyData();
    } catch (err) {
      toast.error("Failed to withdraw consent");
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return "N/A";
    return new Date(dateString).toLocaleString();
  };

  if (loading) {
    return (
      <div className="p-6 md:p-8 max-w-4xl mx-auto">
        <div className="animate-pulse space-y-4">
          <div className="h-8 bg-slate-200 dark:bg-slate-700 rounded w-1/3" />
          <div className="h-32 bg-slate-200 dark:bg-slate-700 rounded" />
          <div className="h-32 bg-slate-200 dark:bg-slate-700 rounded" />
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 md:p-8 max-w-4xl mx-auto" data-testid="privacy-settings-page">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center gap-3 mb-2">
          <Shield className="w-8 h-8 text-turquoise" />
          <h1 className="text-2xl md:text-3xl font-semibold text-slate-900 dark:text-slate-100" style={{ fontFamily: 'IBM Plex Sans' }}>
            Privacy & Data
          </h1>
        </div>
        <p className="text-slate-500 dark:text-slate-400">
          Manage your data, consent preferences, and privacy settings
        </p>
      </div>

      {/* Consent Status */}
      <Card className="mb-6">
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-lg">Your Consents</CardTitle>
              <CardDescription>Active data processing permissions</CardDescription>
            </div>
            {consentStatus?.has_consented && (
              <Badge className="bg-emerald-500 text-white">Active</Badge>
            )}
          </div>
        </CardHeader>
        <CardContent>
          {consentStatus?.consent ? (
            <div className="space-y-4">
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div className="flex items-center gap-2">
                  <FileText className="w-4 h-4 text-slate-400" />
                  <span className="text-sm">Resume Processing</span>
                  {consentStatus.consent.resume_processing ? (
                    <Check className="w-4 h-4 text-emerald-500 ml-auto" />
                  ) : (
                    <span className="text-xs text-slate-400 ml-auto">Off</span>
                  )}
                </div>
                <div className="flex items-center gap-2">
                  <Mic className="w-4 h-4 text-slate-400" />
                  <span className="text-sm">Voice Processing</span>
                  {consentStatus.consent.voice_processing ? (
                    <Check className="w-4 h-4 text-emerald-500 ml-auto" />
                  ) : (
                    <span className="text-xs text-slate-400 ml-auto">Off</span>
                  )}
                </div>
                <div className="flex items-center gap-2">
                  <Brain className="w-4 h-4 text-slate-400" />
                  <span className="text-sm">AI Matching</span>
                  {consentStatus.consent.ai_matching ? (
                    <Check className="w-4 h-4 text-emerald-500 ml-auto" />
                  ) : (
                    <span className="text-xs text-slate-400 ml-auto">Off</span>
                  )}
                </div>
              </div>

              <div className="text-xs text-slate-400">
                Consent granted: {formatDate(consentStatus.consent.granted_at)}
              </div>

              <Button
                variant="outline"
                size="sm"
                className="text-rose-500 border-rose-200 hover:bg-rose-50"
                onClick={handleWithdrawConsent}
              >
                Withdraw All Consents
              </Button>
            </div>
          ) : (
            <div className="text-center py-4">
              <p className="text-slate-500 mb-4">No active consents. Some features may be limited.</p>
              <Button asChild>
                <a href="/consent">Grant Consent</a>
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Data Management */}
      <Card className="mb-6">
        <CardHeader>
          <CardTitle className="text-lg">Your Data</CardTitle>
          <CardDescription>Export or delete your personal data</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Export Data */}
          <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
            <div className="flex items-center gap-3">
              <Download className="w-5 h-5 text-turquoise" />
              <div>
                <p className="font-medium text-slate-900 dark:text-slate-100">Export All Data</p>
                <p className="text-xs text-slate-500">Download your data in JSON format (GDPR portability)</p>
              </div>
            </div>
            <Button
              variant="outline"
              onClick={handleExportData}
              disabled={exportingData}
              data-testid="export-data-btn"
            >
              {exportingData ? "Exporting..." : "Export"}
            </Button>
          </div>

          {/* Delete Data */}
          <Dialog>
            <DialogTrigger asChild>
              <div className="flex items-center justify-between p-4 bg-rose-50 dark:bg-rose-900/20 rounded-lg cursor-pointer hover:bg-rose-100 dark:hover:bg-rose-900/30 transition-colors">
                <div className="flex items-center gap-3">
                  <Trash2 className="w-5 h-5 text-rose-500" />
                  <div>
                    <p className="font-medium text-slate-900 dark:text-slate-100">Delete Data</p>
                    <p className="text-xs text-slate-500">Permanently remove your data (GDPR erasure)</p>
                  </div>
                </div>
                <ChevronRight className="w-5 h-5 text-slate-400" />
              </div>
            </DialogTrigger>

            <DialogContent>
              <DialogHeader>
                <DialogTitle className="flex items-center gap-2 text-rose-600">
                  <AlertTriangle className="w-5 h-5" />
                  Delete Your Data
                </DialogTitle>
              </DialogHeader>

              <div className="space-y-4 py-4">
                <p className="text-sm text-slate-600 dark:text-slate-400">
                  Select the data you want to permanently delete. This action cannot be undone.
                </p>

                <div className="space-y-3">
                  {[
                    { key: "delete_resume", label: "Resume & Profile", icon: FileText },
                    { key: "delete_voice_history", label: "Voice Transcriptions", icon: Mic },
                    { key: "delete_matches", label: "AI Match History & Saved Jobs", icon: Brain },
                    { key: "delete_applications", label: "Job Applications", icon: Building2 },
                    { key: "delete_account", label: "Entire Account", icon: Trash2, danger: true }
                  ].map(({ key, label, icon: Icon, danger }) => (
                    <label key={key} className={`flex items-center gap-3 p-3 rounded-lg cursor-pointer transition-colors ${
                      danger 
                        ? "bg-rose-50 dark:bg-rose-900/20 hover:bg-rose-100" 
                        : "bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700"
                    }`}>
                      <input
                        type="checkbox"
                        checked={deleteOptions[key]}
                        onChange={(e) => setDeleteOptions(prev => ({
                          ...prev,
                          [key]: e.target.checked
                        }))}
                        className="w-4 h-4"
                      />
                      <Icon className={`w-4 h-4 ${danger ? "text-rose-500" : "text-slate-400"}`} />
                      <span className={`text-sm ${danger ? "text-rose-700 dark:text-rose-400 font-medium" : ""}`}>
                        {label}
                      </span>
                    </label>
                  ))}
                </div>
              </div>

              <DialogFooter>
                <Button
                  variant="destructive"
                  onClick={handleDeleteData}
                  disabled={deletingData || !Object.values(deleteOptions).some(v => v)}
                  data-testid="confirm-delete-btn"
                >
                  {deletingData ? "Deleting..." : "Delete Selected Data"}
                </Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        </CardContent>
      </Card>

      {/* Third-Party Services */}
      <Card className="mb-6">
        <CardHeader>
          <CardTitle className="text-lg">Third-Party Services</CardTitle>
          <CardDescription>Services that process your data (sub-processors)</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {subProcessors.map((processor, i) => (
              <div key={i} className="flex items-start gap-3 p-3 bg-slate-50 dark:bg-slate-800 rounded-lg">
                <Building2 className="w-5 h-5 text-slate-400 mt-0.5" />
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className="font-medium text-slate-900 dark:text-slate-100">{processor.name}</span>
                    {processor.dpa_signed && (
                      <Badge variant="outline" className="text-xs text-emerald-600 border-emerald-200">
                        DPA Signed
                      </Badge>
                    )}
                  </div>
                  <p className="text-xs text-slate-500 mt-1">{processor.service}</p>
                  <p className="text-xs text-slate-400">Location: {processor.location}</p>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Language & Translation Settings */}
      <Card className="mb-6" data-testid="translation-settings-card">
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Languages className="w-5 h-5" />
            {t("language.useGoogleTranslate")}
          </CardTitle>
          <CardDescription>{t("language.googleTranslateDisclaimer")}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Browser Translation Status */}
          {isBrowserTranslating && (
            <div className="flex items-center gap-3 p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-800">
              <Languages className="w-5 h-5 text-blue-600" />
              <div>
                <p className="font-medium text-blue-900 dark:text-blue-100">{t("language.browserTranslationActive")}</p>
                <p className="text-xs text-blue-700 dark:text-blue-300">{t("language.browserTranslationNote")}</p>
              </div>
            </div>
          )}

          {/* Google Translate Button */}
          <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
            <div className="flex items-center gap-3">
              <ExternalLink className="w-5 h-5 text-blue-500" />
              <div>
                <p className="font-medium text-slate-900 dark:text-slate-100">{t("language.openGoogleTranslate")}</p>
                <p className="text-xs text-slate-500">Open this page in Google Translate for automatic translation</p>
              </div>
            </div>
            <Button
              variant="outline"
              onClick={openGoogleTranslate}
              className="text-blue-600 border-blue-200 hover:bg-blue-50"
              data-testid="settings-google-translate-btn"
            >
              <ExternalLink className="w-4 h-4 mr-2" />
              Open
            </Button>
          </div>

          {/* Browser Translate Button */}
          <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800 rounded-lg">
            <div className="flex items-center gap-3">
              <Globe className="w-5 h-5 text-blue-500" />
              <div>
                <p className="font-medium text-slate-900 dark:text-slate-100">{t("language.useBrowserTranslate")}</p>
                <p className="text-xs text-slate-500">Get instructions on how to use your browser's built-in translation</p>
              </div>
            </div>
            <Button
              variant="outline"
              onClick={triggerBrowserTranslate}
              className="text-blue-600 border-blue-200 hover:bg-blue-50"
              data-testid="settings-browser-translate-btn"
            >
              <Globe className="w-4 h-4 mr-2" />
              How-to
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Audit Log */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Eye className="w-5 h-5" />
            Privacy Activity Log
          </CardTitle>
          <CardDescription>Recent privacy-related actions on your account</CardDescription>
        </CardHeader>
        <CardContent>
          {auditLogs.length > 0 ? (
            <div className="space-y-2">
              {auditLogs.map((log, i) => (
                <div key={i} className="flex items-center gap-3 p-2 text-sm border-b last:border-0">
                  <Clock className="w-4 h-4 text-slate-400" />
                  <span className="text-slate-600 dark:text-slate-400">
                    {log.action.replace(/_/g, " ")}
                  </span>
                  <span className="text-xs text-slate-400 ml-auto">
                    {formatDate(log.timestamp)}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-sm text-slate-500 text-center py-4">
              No recent privacy activity
            </p>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default PrivacySettingsPage;

/**
 * Production Metrics Dashboard
 * Visualizes user engagement, AI usage, business metrics, and conversion funnels
 */
import React, { useState, useEffect, useCallback } from 'react';
import { useTranslation } from "@/utils/i18n";
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import {
  BarChart3,
  Users,
  TrendingUp,
  Activity,
  Zap,
  Brain,
  Target,
  Clock,
  ArrowUpRight,
  ArrowDownRight,
  RefreshCw,
  Calendar,
  Filter,
  Download,
  ChevronLeft,
  Eye,
  MousePointer,
  Smartphone,
  Monitor,
  Globe,
  DollarSign,
  FileText,
  Briefcase,
  MessageSquare,
  Sparkles,
  PieChart
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../components/ui/card';
import { Button } from '../components/ui/button';
import { Badge } from '../components/ui/badge';
import { Progress } from '../components/ui/progress';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../components/ui/select';
import { apiClient } from '@/utils/apiClient';

// ============== Chart Components ==============

// Simple Bar Chart
const SimpleBarChart = ({ data, label, color = "#14b8a6" }) => {
  if (!data || data.length === 0) return <div className="text-center text-muted-foreground py-8">No data available</div>;

  const maxValue = Math.max(...data.map(d => d.value));

  return (
    <div className="space-y-2">
      {data.map((item, idx) => (
        <div key={idx} className="flex items-center gap-3">
          <span className="text-xs text-muted-foreground w-24 truncate">{item.name}</span>
          <div className="flex-1 h-6 bg-muted/30 rounded-full overflow-hidden">
            <div 
              className="h-full rounded-full transition-all duration-500"
              style={{ 
                width: `${(item.value / maxValue) * 100}%`,
                backgroundColor: color
              }}
            />
          </div>
          <span className="text-sm font-medium w-16 text-right">{item.value.toLocaleString()}</span>
        </div>
      ))}
    </div>
  );
};

// Funnel Chart
const FunnelChart = ({ stages }) => {
  if (!stages || stages.length === 0) return <div className="text-center text-muted-foreground py-8">No funnel data</div>;

  const maxCount = stages[0]?.count || 1;
  const colors = ["#14b8a6", "#0ea5e9", "#8b5cf6", "#f59e0b", "#22c55e"];

  return (
    <div className="space-y-3">
      {stages.map((stage, idx) => {
        const widthPercent = (stage.count / maxCount) * 100;
        const conversionRate = idx > 0 ? ((stage.count / stages[idx-1].count) * 100).toFixed(1) : 100;

        return (
          <div key={stage.name} className="relative">
            <div className="flex items-center gap-3">
              <div className="w-28 text-sm font-medium truncate">{stage.name}</div>
              <div className="flex-1 relative">
                <div 
                  className="h-10 rounded-lg transition-all duration-500 flex items-center justify-end pr-3"
                  style={{ 
                    width: `${Math.max(widthPercent, 10)}%`,
                    backgroundColor: colors[idx % colors.length]
                  }}
                >
                  <span className="text-white text-sm font-bold">{stage.count.toLocaleString()}</span>
                </div>
              </div>
              {idx > 0 && (
                <Badge variant="outline" className="w-16 justify-center">
                  {conversionRate}%
                </Badge>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
};

// Metric Card
const MetricCard = ({ title, value, subtitle, icon: Icon, trend, trendValue, color = "turquoise" }) => {
  const colorClasses = {
    turquoise: "bg-turquoise/10 text-turquoise",
    blue: "bg-blue-500/10 text-blue-500",
    green: "bg-green-500/10 text-green-500",
    purple: "bg-purple-500/10 text-purple-500",
    orange: "bg-orange-500/10 text-orange-500",
    pink: "bg-pink-500/10 text-pink-500"
  };

  return (
    <Card className="hover:shadow-md transition-shadow">
      <CardContent className="p-5">
        <div className="flex items-start justify-between">
          <div className={`p-2.5 rounded-xl ${colorClasses[color]}`}>
            <Icon className="h-5 w-5" />
          </div>
          {trend && (
            <div className={`flex items-center gap-1 text-xs font-medium ${
              trend === 'up' ? 'text-green-500' : trend === 'down' ? 'text-red-500' : 'text-muted-foreground'
            }`}>
              {trend === 'up' ? <ArrowUpRight className="h-3 w-3" /> : <ArrowDownRight className="h-3 w-3" />}
              {trendValue}
            </div>
          )}
        </div>
        <div className="mt-3">
          <p className="text-2xl font-bold">{value}</p>
          <p className="text-sm text-muted-foreground">{title}</p>
          {subtitle && <p className="text-xs text-muted-foreground mt-1">{subtitle}</p>}
        </div>
      </CardContent>
    </Card>
  );
};

