                </div>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Compliance Widget - Takes 1 column */}
        <div className="lg:col-span-1">
          <ComplianceWidget />
        </div>
      </div>

      {/* Pipeline Overview */}
      {stats?.applicants?.total > 0 && (
        <Card className="mt-6">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
