                  </div>
                )}

                <p className="text-sm text-slate-500">{results.message}</p>
              </div>

              <DialogFooter>
                <Button onClick={() => setShowResultsDialog(false)} className="w-full">
                  {results.passed ? t("skills.myBadges") : t("interview.tryAgain")}
                </Button>
              </DialogFooter>
            </>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

