    if (key) return t(key);
    return video.category === 'job_seeker' ? t('videoTutorials.categories.jobSeeker') : 
           video.category === 'recruiter' ? t('videoTutorials.categories.recruiter') : 
           t('videoTutorials.categories.overview');
  }, [video.id, video.category, t]);

  // Get translated title
  const getTitle = useCallback(() => {
    const key = VIDEO_TITLE_KEYS[video.id];
    if (key) {
      const translated = t(key);
      if (translated && translated !== key) return translated;
    }
    return video.title;
  }, [video.id, video.title, t]);

  // Get translated description
  const getDescription = useCallback(() => {
    const key = VIDEO_DESC_KEYS[video.id];
    if (key) {
      const translated = t(key);
      if (translated && translated !== key) return translated;
    }
    return video.description;
  }, [video.id, video.description, t]);

  const handleClick = useCallback(() => {
    onSelect(video);
  }, [video, onSelect]);

  return (
    <div 
      className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-200 dark:border-slate-700 overflow-hidden hover:shadow-md transition-all cursor-pointer group"
      onClick={handleClick}
      data-testid={`video-card-${video.id}`}
    >
      <div className="h-40 relative overflow-hidden">
        <LazyImage 
          src={presenterImage} 
          alt="Tutorial Presenter"
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-black/20 to-transparent" />
        <div className="absolute inset-0 flex items-center justify-center">
          <div className="w-14 h-14 bg-white/90 rounded-full flex items-center justify-center group-hover:scale-110 transition-transform shadow-lg">
            <Play className="w-7 h-7 text-teal-600 ml-1" />
          </div>
        </div>
        <span className="absolute bottom-2 right-2 bg-black/60 text-white text-xs px-2 py-1 rounded">
          {video.duration}
        </span>
        <span className={`absolute top-2 left-2 ${video.color} text-white text-xs px-2 py-1 rounded-full`}>
          {getCategoryLabel()}
        </span>
      </div>
      <div className="p-4">
        <h3 className="font-semibold text-gray-900 dark:text-white mb-1">{getTitle()}</h3>
        <p className="text-sm text-slate-700 dark:text-gray-300 line-clamp-2">{getDescription()}</p>
      </div>
    </div>
  );
});

// Optimized Video Modal with preload="metadata" and efficient loading
const VideoModal = memo(({ video, onClose, selectedLanguage, setSelectedLanguage, showSubtitles, setShowSubtitles, t }) => {
  const [translating, setTranslating] = useState(false);
  const [videoLoaded, setVideoLoaded] = useState(false);
  const [buffering, setBuffering] = useState(true);
  const [translationError, setTranslationError] = useState(null);
  const [generatedAudioUrl, setGeneratedAudioUrl] = useState(null);
  const videoRef = useRef(null);
  const audioRef = useRef(null);

  // AUTO-GENERATE audio when language changes (not English)
  // AND automatically start playing translated audio when ready
  useEffect(() => {
    if (!video || selectedLanguage === 'en') {
      setGeneratedAudioUrl(null);
      // Unmute video for English
      if (videoRef.current) {
        videoRef.current.muted = false;
      }
      return;
    }

    // Check if audio already exists, then auto-generate if needed
    const checkAndGenerateAudio = async () => {
      try {
        // First check status to see if audio exists
        const statusRes = await axios.get(`${API}/api/tutorials/translate/${video.id}/status?lang=${selectedLanguage}`);

        if (statusRes.data.status === 'ready' && statusRes.data.audio_url) {
          // Audio already exists - use it immediately
          const audioUrl = `${API}${statusRes.data.audio_url}`;
          setGeneratedAudioUrl(audioUrl);
          // Auto-mute original video and play translated audio
          if (videoRef.current) {
            videoRef.current.muted = true;
          }
          return;
        }

        // Audio doesn't exist - auto-generate it
        setTranslating(true);
        setTranslationError(null);

        await axios.post(`${API}/api/tutorials/translate/${video.id}?lang=${selectedLanguage}`);

        // Poll for completion
        const checkStatus = async () => {
          const res = await axios.get(`${API}/api/tutorials/translate/${video.id}/status?lang=${selectedLanguage}`);
          if (res.data.status === 'ready') {
            setTranslating(false);
            const audioUrl = res.data.audio_url || res.data.video_url;
            if (audioUrl) {
              const fullAudioUrl = `${API}${audioUrl}`;
              setGeneratedAudioUrl(fullAudioUrl);
              // Auto-mute original video when translated audio is ready
              if (videoRef.current) {
                videoRef.current.muted = true;
              }
            }
          } else if (res.data.status === 'generating') {
            setTimeout(checkStatus, 1500);
          } else if (res.data.status === 'failed') {
            setTranslating(false);
            setTranslationError(res.data.error || t('translation.failed'));
          } else {
            setTranslating(false);
          }
        };
        checkStatus();
      } catch (error) {
        console.error('Auto audio generation failed:', error);
        setTranslating(false);
      }
    };

    checkAndGenerateAudio();
  }, [video, selectedLanguage, t]);

  // Handle video events for loading states - defined before early return
  const handleLoadedMetadata = useCallback(() => {
    setVideoLoaded(true);
  }, []);

  const handleCanPlay = useCallback(() => {
    setBuffering(false);

    // Programmatically enable captions track if showSubtitles is true
    if (videoRef.current && showSubtitles) {
      const tracks = videoRef.current.textTracks;
      if (tracks && tracks.length > 0) {
        for (let i = 0; i < tracks.length; i++) {
          tracks[i].mode = 'showing';
        }
      }
    }
  }, [showSubtitles]);

  const handleWaiting = useCallback(() => {
    setBuffering(true);
  }, []);

  const handlePlaying = useCallback(() => {
    setBuffering(false);
  }, []);

  // Cleanup on unmount - defined before early return
  useEffect(() => {
    return () => {
      if (videoRef.current) {
        videoRef.current.pause();
        videoRef.current.src = '';
        videoRef.current.load();
      }
    };
  }, []);

  // Sync audio with video - defined before early return
  // Handle muting original video when translated audio plays
  useEffect(() => {
    if (videoRef.current && audioRef.current && generatedAudioUrl) {
      const videoElement = videoRef.current;
      const audioElement = audioRef.current;

      const syncAudio = () => {
        if (audioElement) {
          audioElement.currentTime = videoElement.currentTime;
        }
      };

      // When video plays, sync translated audio if video is muted (translated mode)
      const handlePlay = () => {
        if (videoElement.muted && audioElement) {
          audioElement.play();
        }
      };

      const handlePause = () => audioElement?.pause();

      videoElement.addEventListener('play', handlePlay);
      videoElement.addEventListener('pause', handlePause);
      videoElement.addEventListener('seeked', syncAudio);

      return () => {
        videoElement.removeEventListener('play', handlePlay);
        videoElement.removeEventListener('pause', handlePause);
        videoElement.removeEventListener('seeked', syncAudio);
      };
    }
  }, [generatedAudioUrl]);

  // Early return AFTER all hooks
  if (!video) return null;

  const videoUrl = selectedLanguage === 'en' 
    ? video.file 
    : `${video.file}?lang=${selectedLanguage}`;

  const subtitleUrl = `${API}/api/tutorials/subtitles/${video.id}?lang=${selectedLanguage}`;

  const langName = LANGUAGES.find(l => l.code === selectedLanguage)?.name || 'English';

  const requestTranslation = async () => {
    setTranslating(true);
    setTranslationError(null);
    try {
      await axios.post(`${API}/api/tutorials/translate/${video.id}?lang=${selectedLanguage}`);
      const checkStatus = async () => {
        const res = await axios.get(`${API}/api/tutorials/translate/${video.id}/status?lang=${selectedLanguage}`);
        if (res.data.status === 'ready') {
          setTranslating(false);
          // Set the generated audio URL
          const audioUrl = res.data.audio_url || res.data.video_url;
          if (audioUrl) {
            setGeneratedAudioUrl(`${API}${audioUrl}`);
          }
        } else if (res.data.status === 'generating') {
          setTimeout(checkStatus, 2000);
        } else if (res.data.status === 'failed') {
          setTranslating(false);
          setTranslationError(res.data.error || t('translation.failed'));
        } else {
          setTranslating(false);
        }
      };
      checkStatus();
    } catch (error) {
      console.error('Translation request failed:', error);
      setTranslating(false);
      setTranslationError(t('translation.failed'));
    }
  };

  // Play generated audio alongside video - MUTE original video audio
  const playAudioWithVideo = () => {
    if (videoRef.current && audioRef.current && generatedAudioUrl) {
      // Mute the original video audio
      videoRef.current.muted = true;
      // Play the translated audio
      audioRef.current.play();
    }
  };

  // Stop translated audio and unmute video
  const stopTranslatedAudio = () => {
    if (videoRef.current && audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
      videoRef.current.muted = false;
    }
  };

  return (
    <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4" onClick={onClose}>
      <div className="bg-white rounded-xl max-w-4xl w-full overflow-hidden" onClick={e => e.stopPropagation()}>
        {/* Header with improved contrast - dark text on light background */}
        <div className="p-4 border-b flex justify-between items-center bg-slate-50">
          <h3 className="font-semibold text-lg text-slate-900">{video.title}</h3>
          <div className="flex items-center gap-4">
            {/* Language Selector */}
            <div className="flex items-center gap-2">
              <Globe className="w-4 h-4 text-slate-600" />
              <select 
                value={selectedLanguage}
                onChange={(e) => setSelectedLanguage(e.target.value)}
                className="text-sm border border-slate-300 rounded px-2 py-1 text-slate-800 bg-white"
              >
                {LANGUAGES.map(lang => (
                  <option key={lang.code} value={lang.code}>{lang.name}</option>
                ))}
              </select>
            </div>
            {/* Subtitles Toggle */}
            <button 
              onClick={() => setShowSubtitles(!showSubtitles)}
              className={`flex items-center gap-1 text-sm px-2 py-1 rounded border ${showSubtitles ? 'bg-teal-100 text-teal-700 border-teal-300' : 'bg-slate-100 text-slate-700 border-slate-300'}`}
            >
              <Subtitles className="w-4 h-4" />
              CC
            </button>
            <button onClick={onClose} className="text-slate-500 hover:text-slate-700">
              ✕
            </button>
          </div>
        </div>
        <div className="aspect-video bg-black relative">
          {/* Loading/Buffering overlay */}
          {(translating || buffering) && (
            <div className="absolute inset-0 bg-black/80 flex flex-col items-center justify-center text-white z-10">
              <Loader2 className="w-8 h-8 animate-spin mb-2" />
              <p>{translating 
                ? `${t('helpTutorials.generatingVersion')} ${langName}...`
                : t('helpTutorials.loadingVideo') || t('videoTutorials.loadingVideo')
              }</p>
              {translating && <p className="text-sm text-gray-400">{t('helpTutorials.mayTakeMinute')}</p>}
            </div>
          )}

          {/* Poster/Thumbnail while video loads */}
          {!videoLoaded && (
            <div className="absolute inset-0 flex items-center justify-center bg-gray-900">
              <img 
                src={PRESENTER_IMAGES[video.id] || "/images/presenter.jpeg"}
                alt="Video thumbnail"
                className="w-full h-full object-contain opacity-50"
              />
            </div>
          )}

          <video 
            ref={videoRef}
            src={videoUrl} 
            controls 
            autoPlay
            preload="metadata"
            playsInline
            className={`w-full h-full ${videoLoaded ? 'opacity-100' : 'opacity-0'}`}
            data-testid="video-player"
            crossOrigin="anonymous"
            onLoadedMetadata={handleLoadedMetadata}
            onCanPlay={handleCanPlay}
            onWaiting={handleWaiting}
            onPlaying={handlePlaying}
            poster={PRESENTER_IMAGES[video.id] || "/images/presenter.jpeg"}
          >
            {showSubtitles && (
              <track 
                kind="captions" 
                src={subtitleUrl}
                srcLang={selectedLanguage}
                label={langName}
                default
              />
            )}
            Your browser does not support video playback.
          </video>

          {/* Custom Caption Overlay for better visibility */}
          {showSubtitles && (
            <div className="absolute bottom-12 left-0 right-0 text-center px-4 pointer-events-none">
              <div className="inline-block bg-black/80 text-white px-4 py-2 rounded text-sm max-w-lg" id={`caption-display-${video.id}`}>
                {/* Captions will be rendered by the video element */}
              </div>
            </div>
          )}
        </div>
        {/* Bottom panel with improved text contrast - FIXED ACCESSIBILITY */}
        <div className="p-4 bg-slate-50 border-t border-slate-200">
          <p className="text-slate-800 mb-3 font-medium">{video.description}</p>
          <div className="flex items-center gap-3 flex-wrap">
            {/* Caption Status */}
            <span className={`text-xs px-2 py-1 rounded-full font-medium ${showSubtitles ? 'bg-teal-100 text-teal-800' : 'bg-slate-200 text-slate-700'}`}>
              {showSubtitles ? `✓ ${t('helpTutorials.captionsOn')}` : t('helpTutorials.captionsOff')}
            </span>

            {/* Language Info */}
            <span className="text-xs text-slate-700 font-medium">
              {t('helpTutorials.captions')}: {langName}
            </span>

            {/* Audio Status */}
            {selectedLanguage !== 'en' && !generatedAudioUrl && (
              <span className="text-xs text-amber-800 bg-amber-100 px-2 py-1 rounded font-medium">
                {t('helpTutorials.audioInEnglish')} • {t('helpTutorials.captionsIn')} {langName}
              </span>
            )}

            {/* Generated Audio Active Status */}
            {generatedAudioUrl && videoRef.current?.muted && (
              <span className="text-xs text-green-800 bg-green-100 px-2 py-1 rounded font-medium flex items-center gap-1">
                🔊 {t('helpTutorials.playingAudio')} {langName}
              </span>
            )}

            {/* Generated Audio Ready Status */}
            {generatedAudioUrl && !videoRef.current?.muted && (
              <span className="text-xs text-green-800 bg-green-100 px-2 py-1 rounded font-medium flex items-center gap-1">
                ✓ {langName} {t('helpTutorials.audioReady')}
              </span>
            )}
          </div>

          {/* Hidden Audio Element for Generated Audio */}
          {generatedAudioUrl && (
            <audio ref={audioRef} src={generatedAudioUrl} preload="auto" />
          )}

          {/* AI Audio Generation Section */}
          {selectedLanguage !== 'en' && (
            <div className="mt-3 pt-3 border-t border-slate-200">
              <div className="flex items-center gap-2 flex-wrap">
                {!generatedAudioUrl ? (
                  <>
                    <button
                      onClick={requestTranslation}
                      disabled={translating}
                      className="text-sm bg-purple-600 text-white px-3 py-1.5 rounded hover:bg-purple-700 disabled:opacity-50 flex items-center gap-1 font-medium"
                    >
                      {translating ? (
                        <>
                          <Loader2 className="w-3 h-3 animate-spin" />
                          {t('helpTutorials.generatingAudio')}
                        </>
                      ) : (
                        <>{t('helpTutorials.generateAudio')} {langName} ({t('helpTutorials.free')})</>
                      )}
                    </button>
                    <span className="text-xs text-green-800 font-medium">{t('helpTutorials.neuralVoice')} • {t('helpTutorials.noCost')}</span>
                  </>
                ) : (
                  <>
                    <button
                      onClick={playAudioWithVideo}
                      className="text-sm bg-green-600 text-white px-3 py-1.5 rounded hover:bg-green-700 flex items-center gap-1 font-medium"
                    >
                      🔊 {t('helpTutorials.playAudio')} {langName}
                    </button>
                    <button
                      onClick={stopTranslatedAudio}
                      className="text-sm bg-slate-600 text-white px-3 py-1.5 rounded hover:bg-slate-700 flex items-center gap-1 font-medium"
                    >
                      🔇 {t('helpTutorials.useOriginalAudio')}
                    </button>
                    <span className="text-xs text-slate-700 font-medium">{t('helpTutorials.audioSyncs')}</span>
                  </>
                )}
              </div>
              {translationError && (
                <p className="text-xs text-red-700 mt-2 font-medium">{translationError}</p>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
});

