        </div>
        <div className="flex items-center gap-2 bg-teal-50 dark:bg-teal-900/30 px-3 py-2 rounded-lg">
          <Globe className="w-5 h-5 text-teal-600 dark:text-teal-400" />
          <span className="text-sm font-medium text-teal-700 dark:text-teal-300">{languageList.length} {t('helpTutorials.languagesAvailable')}</span>
        </div>
      </div>

      {/* Main Content Grid */}
      <div className="grid lg:grid-cols-3 gap-6">
        {/* Video Player */}
        <div className="lg:col-span-2">
          <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-200 dark:border-slate-700 overflow-hidden">
            {/* Video Container */}
            <div className="aspect-video bg-gray-900 relative">
              {videoError ? (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-white">
                  <div className="w-16 h-16 bg-red-500/20 rounded-full flex items-center justify-center mb-3">
                    <Play className="w-8 h-8 text-red-400" />
                  </div>
                  <p className="text-red-400">{videoError}</p>
                  <button 
                    onClick={() => setVideoError(null)}
                    className="mt-3 text-sm text-gray-400 hover:text-white"
                  >
                    {t('helpTutorials.tryAgain')}
                  </button>
                </div>
              ) : (
                <>
                  <video
                    ref={videoRef}
                    src={videoUrl}
                    className="w-full h-full object-contain"
                    onEnded={handleVideoEnded}
                    onError={handleVideoError}
                    onCanPlay={handleCanPlay}
                    onPlaying={() => setIsPlaying(true)}
                    onPause={() => setIsPlaying(false)}
                    preload="metadata"
                    playsInline
                    controls={isPlaying}
                    data-testid="tutorial-video-player"
                  />

                  {/* Play Overlay */}
                  {!isPlaying && (
